// French, server-side formatting (docs/08-stack.md: the backoffice stays in
// French, no next-intl there). Formatted here, not in the client table
// component, to avoid an `Intl` hydration mismatch (specs/BO-02-portefeuille
// plan, risk table).
const EURO_FORMATTER = new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR" });
const PERCENT_FORMATTER = new Intl.NumberFormat("fr-FR", { style: "percent", maximumFractionDigits: 1 });
const NUMBER_FORMATTER = new Intl.NumberFormat("fr-FR");

const EM_DASH = "—";
const MICROS_PER_EURO = 1_000_000;

export function formatEuroCents(cents: number): string {
  return EURO_FORMATTER.format(cents / 100);
}

// AI cost and margin are stored in micros (millionths of a dollar,
// docs/07-modele-de-donnees.md); shown in € at USD = EUR 1:1, like the
// frozen `marginMicros` total already does (plan design decision 6). A
// generation costs a fraction of a cent, so the decimals grow until the
// first significant digit and the next one show (0,0012 €, up to 6): a
// non-zero cost never reads as 0,00 € (QA1 B8).
const MAX_MICROS_FRACTION_DIGITS = 6;

export function formatEuroMicros(micros: number, minimumFractionDigits = 2): string {
  const euros = micros / MICROS_PER_EURO;
  const leadingZeros = euros === 0 ? 0 : Math.ceil(-Math.log10(Math.abs(euros)));
  const maximumFractionDigits = Math.min(MAX_MICROS_FRACTION_DIGITS, Math.max(minimumFractionDigits, leadingZeros + 1));
  return new Intl.NumberFormat("fr-FR", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(euros);
}

export function formatPercent(rate: number | null): string {
  return rate === null ? EM_DASH : PERCENT_FORMATTER.format(rate);
}

export function formatNumber(value: number): string {
  return NUMBER_FORMATTER.format(value);
}

import { KpiCard } from "@/components/backoffice/kpi-card";
import type { PortfolioMetrics } from "@/lib/dal/metrics";
import { formatEuroCents, formatEuroMicros, formatNumber, formatPercent } from "./format";

// docs/02-ecrans.md › BO-02: "KPIs globaux en tête" (plan design decision
// 7 — 4 labels, no deltas). Gross margin is a rate (margin / revenue), not
// a euro amount: `null` (shown as "—") when there is no revenue to divide
// by.
function grossMarginRate(totals: PortfolioMetrics["totals"]): number | null {
  const revenueMicros = totals.revenueCents * 10_000;
  return revenueMicros > 0 ? totals.marginMicros / revenueMicros : null;
}

export function PortfolioKpis({ totals }: { totals: PortfolioMetrics["totals"] }) {
  return (
    <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
      <KpiCard label="Visites · 30 j" value={formatNumber(totals.visits)} />
      <KpiCard label="Revenu · 30 j" value={formatEuroCents(totals.revenueCents)} />
      <KpiCard label="Coût IA · 30 j" value={formatEuroMicros(totals.aiCostMicros)} />
      <KpiCard label="Marge brute" value={formatPercent(grossMarginRate(totals))} />
    </div>
  );
}

"use client";

import type { Route } from "next";
import Link from "next/link";
import { useState } from "react";
import { StatusBadge } from "@/components/backoffice/status-badge";
import { DecisionBadge } from "./decision-badge";
import type { PortfolioRow } from "./rows";
import { DEFAULT_SORT, sortRows, type SortColumn, type SortDirection } from "./sort";

const COLUMNS: { key: SortColumn; label: string }[] = [
  { key: "status", label: "Statut" },
  { key: "visits", label: "Visites" },
  { key: "conversion", label: "Conversion" },
  { key: "revenue", label: "Revenu" },
  { key: "aiCost", label: "Coût IA" },
  { key: "margin", label: "Marge" },
];

// Sort's ARIA vocabulary (docs/02-ecrans.md › BO-02 tableau triable):
// "none" for every header that is not the current sort key.
function ariaSortFor(
  column: SortColumn,
  current: SortColumn,
  direction: SortDirection,
): "ascending" | "descending" | "none" {
  if (column !== current) return "none";
  return direction === "asc" ? "ascending" : "descending";
}

// typedRoutes cannot prove a plain `string` slug fits the dynamic segment
// outside a JSX href, hence the cast; the route itself exists (BO-03).
function productHref(slug: string): Route {
  return `/admin/products/${slug}` as Route;
}

export function PortfolioTable({ rows }: { rows: PortfolioRow[] }) {
  const [sort, setSort] = useState<{ column: SortColumn; direction: SortDirection }>(DEFAULT_SORT);

  function toggleSort(column: SortColumn) {
    setSort((previous) => {
      if (previous.column !== column) return { column, direction: "asc" };
      return { column, direction: previous.direction === "asc" ? "desc" : "asc" };
    });
  }

  const sorted = sortRows(rows, sort.column, sort.direction);

  return (
    <div>
      <p className="mb-2 text-sm text-muted-foreground">Produits ({rows.length})</p>
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b text-left">
            <th scope="col" className="py-2 pr-4 font-medium">
              Produit
            </th>
            {COLUMNS.map(({ key, label }) => (
              <th key={key} scope="col" aria-sort={ariaSortFor(key, sort.column, sort.direction)} className="py-2 pr-4">
                <button type="button" onClick={() => toggleSort(key)} className="font-medium hover:underline">
                  {label}
                </button>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sorted.map((row) => (
            <tr key={row.productId} className="border-b last:border-0">
              <td className="py-2 pr-4">
                <Link href={productHref(row.slug)} className="font-medium hover:underline">
                  {row.name}
                </Link>
                <div className="text-xs text-muted-foreground">/{row.slug}</div>
              </td>
              <td className="py-2 pr-4">
                <div className="flex items-center gap-2">
                  <StatusBadge status={row.status} />
                  <DecisionBadge decision={row.decision} />
                </div>
              </td>
              <td className="py-2 pr-4">{row.display.visits}</td>
              <td className="py-2 pr-4">{row.display.conversion}</td>
              <td className="py-2 pr-4">{row.display.revenue}</td>
              <td className="py-2 pr-4">{row.display.aiCost}</td>
              <td className="py-2 pr-4">{row.display.margin}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import Link from "next/link";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/shared/empty-state";
import type { PortfolioMetrics } from "@/lib/dal/metrics";
import { PortfolioKpis } from "./portfolio-kpis";
import { PortfolioTable } from "./portfolio-table";
import type { PortfolioRow } from "./rows";

const NEW_PRODUCT_HREF = "/admin/products/new";

// docs/02-ecrans.md › BO-02 état "Vide (aucun produit)": KPIs stay (all
// zero), the table is replaced by an empty state with a create action
// (specs/BO-02-portefeuille.md plan, design decision 8).
export function PortfolioView({ totals, rows }: { totals: PortfolioMetrics["totals"]; rows: PortfolioRow[] }) {
  return (
    <div className="grid gap-6">
      <PortfolioKpis totals={totals} />
      {rows.length === 0 ? (
        <EmptyState
          title="Aucun produit"
          description="Créez votre premier produit pour voir apparaître ses métriques ici."
          action={
            <Button asChild>
