import { evaluate, type Decision } from "@/lib/decision";
import type { ProductMetrics } from "@/lib/dal/metrics";
import type { Thresholds } from "@/lib/dal/thresholds";
import { formatEuroMicros, formatNumber, formatPercent } from "@/app/(backoffice)/admin/_components/portfolio/format";

const EM_DASH = "—";

export type DecisionSuggestion = { headline: string; detail: string } | null;

export type DecisionCopy = {
  thresholds: { label: string; value: string }[];
  current: { visits: string; conversion: string; margin: string };
  suggestion: DecisionSuggestion;
  badge: Decision;
};

// docs/01-produit.md › Statut Test → Learn → Scale → Killed, docs/07 › decision_thresholds
// (plan design decision 4): the 4 studio thresholds, this product's current values, the same
// `evaluate()` decision the portfolio badge uses (`badge`, so the sheet's header and the
// portfolio table never disagree) and its French `suggestion` text. A killed product never
// suggests anything: the decision has already been made.
export function toDecisionCopy(metrics: ProductMetrics, thresholds: Thresholds): DecisionCopy {
  const thresholdLines = [
    { label: "Visites minimales", value: formatNumber(thresholds.minVisits) },
    { label: "Conversion « à couper » sous", value: formatPercent(thresholds.killMaxConversion) },
    { label: "Conversion « à scaler » à partir de", value: formatPercent(thresholds.scaleMinConversion) },
    { label: "Marge positive exigée", value: thresholds.scaleRequiresPositiveMargin ? "Oui" : "Non" },
  ];
  const current = {
    visits: formatNumber(metrics.visits),
    conversion: formatPercent(metrics.signupToPurchaseRate),
    margin: metrics.marginPerGenerationMicros === null ? EM_DASH : formatEuroMicros(metrics.marginPerGenerationMicros),
  };
  const badge = toBadge(metrics, thresholds);

  return { thresholds: thresholdLines, current, suggestion: toSuggestion(metrics, thresholds, badge), badge };
}

function toBadge(metrics: ProductMetrics, thresholds: Thresholds): Decision {
  if (metrics.status === "killed") return null;
  return evaluate(
    {
      visits: metrics.visits,
      signupToPurchaseRate: metrics.signupToPurchaseRate,
      marginPerGenerationMicros: metrics.marginPerGenerationMicros,
    },
    thresholds,
  );
}

function toSuggestion(metrics: ProductMetrics, thresholds: Thresholds, badge: Decision): DecisionSuggestion {
  if (metrics.status === "killed") return null;
  if (metrics.visits < thresholds.minVisits) {
    return {
      headline: "Pas assez de visites pour décider",
      detail: `${formatNumber(metrics.visits)} / ${formatNumber(thresholds.minVisits)}`,
    };
  }
  if (badge === "kill") return { headline: "Seuil de décision atteint", detail: "Statut suggéré : Killed (à couper)" };
  if (badge === "scale") return { headline: "Seuil de décision atteint", detail: "Statut suggéré : Scale (à scaler)" };
  return { headline: "Pas de suggestion", detail: "on continue d'observer" };
}

import type { DecisionMetrics } from "@/lib/decision";
import type { Thresholds } from "@/lib/dal/thresholds";

export type GaugeZone = "kill" | "neutral" | "scale";

export type ThresholdGauge = {
  gate: { visits: number; minVisits: number; met: boolean; progress: number };
  scaleMax: number;
  zones: { killEnd: number; scaleStart: number };
  marker: { position: number; zone: GaugeZone } | null;
};

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));

// Pure geometry for the BO-03 threshold gauge (docs/01-produit.md › Statut Test →
// Learn → Scale → Killed): the same primitives `evaluate()` reads, reshaped into
// positions on a 0..1 axis. Never itself a decision — decision-copy.ts's
// `toDecisionCopy()` (via `evaluate()`) still owns the actual suggestion; this
// only draws where the current numbers sit relative to the two thresholds.
export function computeThresholdGauge(metrics: DecisionMetrics, thresholds: Thresholds): ThresholdGauge {
  const gate = {
    visits: metrics.visits,
    minVisits: thresholds.minVisits,
    met: metrics.visits >= thresholds.minVisits,
    progress: thresholds.minVisits > 0 ? clamp01(metrics.visits / thresholds.minVisits) : 1,
  };

  const rate = metrics.signupToPurchaseRate;
  const scaleMax = Math.max(
    thresholds.scaleMinConversion * 1.5,
    thresholds.killMaxConversion * 1.2,
    (rate ?? 0) * 1.15,
    0.01,
  );

  const zones = {
    killEnd: clamp01(thresholds.killMaxConversion / scaleMax),
    scaleStart: clamp01(thresholds.scaleMinConversion / scaleMax),
  };

  const marker =
    rate === null
      ? null
      : {
          position: clamp01(rate / scaleMax),
          zone: (rate < thresholds.killMaxConversion
            ? "kill"
            : rate >= thresholds.scaleMinConversion
              ? "scale"
              : "neutral") as GaugeZone,
        };

  return { gate, scaleMax, zones, marker };
}

import type { DecisionMetrics } from "@/lib/decision";
import type { Thresholds } from "@/lib/dal/thresholds";
import { formatPercent } from "@/app/(backoffice)/admin/_components/portfolio/format";
import { computeThresholdGauge, type GaugeZone } from "./decision-gauge-data";

const ZONE_COLOR: Record<GaugeZone, string> = { kill: "#dc2626", neutral: "#a1a1aa", scale: "#16a34a" };
const ZONE_FILL: Record<GaugeZone, string> = { kill: "#fecaca", neutral: "#e4e4e7", scale: "#bbf7d0" };
const ZONE_LABEL: Record<GaugeZone, string> = { kill: "à couper", neutral: "zone neutre", scale: "à scaler" };

const AXIS_WIDTH = 300;
const BAR_Y = 18;
const BAR_HEIGHT = 10;

// docs/01-produit.md › Statut Test → Learn → Scale → Killed (BO-03): the
// current conversion rate plotted against the studio's kill/scale
// thresholds, so the badge's verdict is something a visitor can *see*, not
// just read. Server-rendered (no interactivity), driven by the same
// primitives `evaluate()` reads — never a second source of truth for the
// decision itself, only its geometry (decision-gauge-data.ts).
export function DecisionGauge({ metrics, thresholds }: { metrics: DecisionMetrics; thresholds: Thresholds }) {
  const gauge = computeThresholdGauge(metrics, thresholds);
  const killEndX = gauge.zones.killEnd * AXIS_WIDTH;
  const scaleStartX = gauge.zones.scaleStart * AXIS_WIDTH;
  const markerX = gauge.marker ? gauge.marker.position * AXIS_WIDTH : null;
  const markerZone = gauge.marker?.zone;

  return (
    <div className="grid gap-2">
      <svg
        viewBox={`0 0 ${AXIS_WIDTH} 44`}
        className="w-full"
        role="img"
        aria-label="Position par rapport aux seuils de décision"
      >
        <rect x={0} y={BAR_Y} width={killEndX} height={BAR_HEIGHT} rx={4} fill={ZONE_FILL.kill} />
        <rect
          x={killEndX}
          y={BAR_Y}
          width={Math.max(0, scaleStartX - killEndX)}
          height={BAR_HEIGHT}
          fill={ZONE_FILL.neutral}
        />
        <rect
          x={scaleStartX}
          y={BAR_Y}
          width={Math.max(0, AXIS_WIDTH - scaleStartX)}
          height={BAR_HEIGHT}
          rx={4}
          fill={ZONE_FILL.scale}
        />
        <line
          x1={killEndX}
          x2={killEndX}
          y1={BAR_Y - 3}
          y2={BAR_Y + BAR_HEIGHT + 3}
          stroke={ZONE_COLOR.kill}
          strokeWidth={2}
        />
        <line
          x1={scaleStartX}
          x2={scaleStartX}
          y1={BAR_Y - 3}
          y2={BAR_Y + BAR_HEIGHT + 3}
          stroke={ZONE_COLOR.scale}
          strokeWidth={2}
        />
        <text x={killEndX} y={BAR_Y - 6} textAnchor="middle" className="fill-muted-foreground text-[8px]">
          {formatPercent(thresholds.killMaxConversion)}
        </text>
        <text x={scaleStartX} y={BAR_Y - 6} textAnchor="middle" className="fill-muted-foreground text-[8px]">
          {formatPercent(thresholds.scaleMinConversion)}
        </text>
        {markerX !== null && markerZone ? (
          <g data-testid="gauge-marker">
            <circle
              cx={markerX}
              cy={BAR_Y + BAR_HEIGHT / 2}
              r={5}
              fill={ZONE_COLOR[markerZone]}
              stroke="white"
              strokeWidth={1.5}
            />
            <text
              x={markerX}
              y={BAR_Y + BAR_HEIGHT + 16}
              textAnchor="middle"
              className="fill-foreground text-[9px] font-medium"
            >
              {formatPercent(metrics.signupToPurchaseRate)}
            </text>
          </g>
        ) : null}
      </svg>
      <ul className="flex flex-wrap gap-3 text-xs text-muted-foreground">
        {(["kill", "neutral", "scale"] as const).map((zone) => (
          <li key={zone} className="flex items-center gap-1.5">
            <span aria-hidden="true" className="size-2 rounded-full" style={{ backgroundColor: ZONE_COLOR[zone] }} />
            {ZONE_LABEL[zone]}
          </li>
        ))}
      </ul>
      {!gauge.gate.met ? (
        <p className="text-xs text-muted-foreground">
          Seuil de visites non atteint ({gauge.gate.visits.toLocaleString("fr-FR")} /{" "}
          {gauge.gate.minVisits.toLocaleString("fr-FR")}) — tendance indicative seulement, pas encore de verdict.
        </p>
      ) : null}
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { DecisionMetrics } from "@/lib/decision";
import type { Thresholds } from "@/lib/dal/thresholds";
import type { ProductStatus } from "@/lib/schemas/product-config";
import type { DecisionCopy } from "./decision-copy";
import { DecisionGauge } from "./decision-gauge";
import { StatusChange } from "./status/status-change";

export type DecisionPanelProduct = { productId: string; slug: string; name: string; status: ProductStatus };

// docs/01-produit.md › "les seuils de décision" (BO-03): the studio's 4 thresholds, this
// product's current values, and — when there is one — the suggestion `toDecisionCopy` derived
// from the same `evaluate()` as the header's DecisionBadge. `null` (a killed product, or a
// product below the min-visits gate that still shows a "not enough data" line — decision-copy.ts
// handles both) renders no suggestion block at all.
//
// specs/mockups/BO-06.png: when the suggestion actually carries a decision (`badge` is `kill` or
// `scale`, not the "not enough visits" or "no suggestion" copies), the box also mounts
// `StatusChange`, preselected on that suggestion, so the admin can act right where the numbers
// justify it — a second mount point next to the header's (BO-06 task item 2).
export function DecisionPanel({
  decision,
  product,
  metrics,
  thresholds,
}: {
  decision: DecisionCopy;
  product: DecisionPanelProduct;
  metrics: DecisionMetrics;
  thresholds: Thresholds;
