import type { DailyPoint, Funnel, FunnelStep, ProductMetrics } from "@/lib/dal/metrics";
import type { ProductStatus } from "@/lib/schemas/product-config";
import type { DecisionMetrics } from "@/lib/decision";
import type { Thresholds } from "@/lib/dal/thresholds";
import {
  formatEuroCents,
  formatEuroMicros,
  formatNumber,
  formatPercent,
} from "@/app/(backoffice)/admin/_components/portfolio/format";
import { toDecisionCopy, type DecisionCopy } from "./decision-copy";

const EM_DASH = "—";

// BO-03's 4 KPI cards (docs/02-ecrans.md, plan design decision 3 — no "Visites" card, no deltas:
// orchestrator decision 4). ARPU isn't stored on ProductMetrics (unlike the portfolio's gross
// margin rate, docs/01-produit.md › ARPU = revenu / inscrits): `null` (shown "—") at 0 signups.
export function toKpis(metrics: ProductMetrics): { label: string; value: string }[] {
  const arpu = metrics.signups > 0 ? metrics.revenueCents / metrics.signups : null;
  return [
    { label: "Revenu · 30 j", value: formatEuroCents(metrics.revenueCents) },
    { label: "ARPU", value: arpu === null ? EM_DASH : formatEuroCents(arpu) },
    { label: "Coût IA · 30 j", value: formatEuroMicros(metrics.aiCostMicros) },
    {
      label: "Marge / génération",
      value: metrics.marginPerGenerationMicros === null ? EM_DASH : formatEuroMicros(metrics.marginPerGenerationMicros),
    },
  ];
}

const STEP_LABELS: Record<FunnelStep["type"], string> = {
  visit: "Visites landing",
  first_generation: "1re génération",
  signup: "Inscription",
  credits_exhausted: "Crédits épuisés",
  purchase: "Achat",
};

export type FunnelRow = { type: FunnelStep["type"]; label: string; count: string; rate: string; widthPercent: number };

// docs/02-ecrans.md › Funnel: "5 étapes avec volumes et taux de passage" — a bar per step, width
// proportional to `visits` (the first step, always 100 unless visits is 0), clamped to [0, 100]
// so a data inconsistency can never overflow the bar. The rate itself is clamped to [0, 1]
// (QA1-P1-Q5), independently of lib/dal/metrics.ts's own clamp: no step's pass rate is ever
// displayed above 100%, whatever `rateFromPrevious` carries.
export function toFunnelRows(steps: FunnelStep[], visits: number): FunnelRow[] {
  return steps.map((step) => ({
    type: step.type,
    label: STEP_LABELS[step.type],
    count: formatNumber(step.count),
    rate: formatPercent(step.rateFromPrevious === null ? null : Math.min(1, step.rateFromPrevious)),
    widthPercent: visits > 0 ? Math.min(100, Math.max(0, (step.count / visits) * 100)) : 0,
  }));
}

export type TrendPoint = { date: string; visits: number; purchases: number };

// docs/01-produit.md › "courbes sur 30 jours": a dd/MM label (the ISO date's day and month,
// already ordered by the DAL) and the two series the trend chart plots.
export function toTrendPoints(daily: DailyPoint[]): TrendPoint[] {
  return daily.map((point) => ({
    date: `${point.date.slice(8, 10)}/${point.date.slice(5, 7)}`,
    visits: point.visits,
    purchases: point.purchases,
  }));
}

export type ProductSheetViewModel = {
  productId: string;
  slug: string;
  name: string;
  status: ProductStatus;
  hasData: boolean;
  kpis: { label: string; value: string }[];
  funnelRows: FunnelRow[];
  trend: TrendPoint[];
  decision: DecisionCopy;
  decisionMetrics: DecisionMetrics;
  thresholds: Thresholds;
};

// The product sheet's (BO-03) full view model, computed once on the server from `getFunnel` and
// `getThresholds`'s real data (design decisions 3-4). `hasData` gates the "no data" state
// (docs/02-ecrans.md › BO-03 état "Produit sans données"): true as soon as there is at least one
// visit, false only for a brand-new, never-visited product.
export function toProductSheet(funnel: Funnel, thresholds: Thresholds): ProductSheetViewModel {
  const { metrics } = funnel;
  return {
    productId: metrics.productId,
    slug: metrics.slug,
    name: metrics.name,
    status: metrics.status,
    hasData: metrics.visits > 0,
    kpis: toKpis(metrics),
    funnelRows: toFunnelRows(funnel.steps, metrics.visits),
    trend: toTrendPoints(funnel.daily),
    decision: toDecisionCopy(metrics, thresholds),
    decisionMetrics: {
      visits: metrics.visits,
      signupToPurchaseRate: metrics.signupToPurchaseRate,
      marginPerGenerationMicros: metrics.marginPerGenerationMicros,
    },
    thresholds,
  };
}

"use client";

import { Line, LineChart, ResponsiveContainer, XAxis } from "recharts";
import type { TrendPoint } from "./sheet";

// Series colours of the BO-03 mockup (specs/mockups/BO-03.png): Visites in
// violet, Achats in orange and dashed. Fixed hex values rather than theme
// tokens: the backoffice's neutral primary/accent both render near-black,
// which made the two series indistinguishable (QA1 B16).
const SERIES = {
  visits: { label: "Visites", color: "#7c3aed", dash: undefined },
  purchases: { label: "Achats", color: "#f97316", dash: "5 4" },
} as const;

// docs/01-produit.md › "courbes sur 30 jours": the only Recharts leaf on the sheet (plan design
// decision 7). An HTML legend rather than Recharts' own (harder to test and to theme) names the
// two series; the chart itself carries no axis labels beyond the x dates, kept minimal.
export function TrendChart({ points }: { points: TrendPoint[] }) {
  return (
    <div className="grid gap-2">
      <ul className="flex gap-4 text-sm">
        {Object.entries(SERIES).map(([key, series]) => (
          <li key={key} className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              data-testid={`legend-${key}`}
              className="w-4 border-t-2"
              style={{ borderColor: series.color, borderStyle: series.dash ? "dashed" : "solid" }}
            />
            {series.label}
          </li>
        ))}
      </ul>
      <div className="h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={points}>
            <XAxis dataKey="date" tick={{ fontSize: 12 }} />
            <Line type="monotone" dataKey="visits" stroke={SERIES.visits.color} dot={false} strokeWidth={2} />
            <Line
              type="monotone"
              dataKey="purchases"
              stroke={SERIES.purchases.color}
              strokeDasharray={SERIES.purchases.dash}
              dot={false}
              strokeWidth={2}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

app/(backoffice)/admin/products/[slug]/p.content:
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { getFunnel } from "@/lib/dal/metrics";
import { getProduct } from "@/lib/dal/products";
import { getThresholds } from "@/lib/dal/thresholds";
import { requireAdmin } from "@/lib/dal/session";
import { toProductSheet } from "./_components/sheet";
import { ProductSheetSkeleton } from "./_components/product-sheet-skeleton";
import { ProductSheetView } from "./_components/product-sheet-view";

const RANGE_DAYS = 30;

// BO-03 (specs/BO-03-fiche.md): session-gated (own requireAdmin(), like every /admin page —
// require-admin-coverage.test.ts), never cached (docs/04-nextjs.md), so it streams under
// <Suspense> while the shell above renders instantly. notFound() for an unknown slug
// (docs/02-ecrans.md › SA-08-like "produit introuvable" for the backoffice); a killed product
// still renders (ProductSheetView's own banner), it just isn't notFound()'d.
async function ProductSheet({ params }: { params: Promise<{ slug: string }> }) {
  await requireAdmin();
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();

  const [funnel, thresholds] = await Promise.all([
    getFunnel(product.id, { days: RANGE_DAYS }),
    getThresholds(product.id),
  ]);
  const sheet = toProductSheet(funnel, thresholds);

  return <ProductSheetView sheet={sheet} />;
}

export default function ProductSheetPage({ params }: PageProps<"/admin/products/[slug]">) {
  return (
    <main className="p-6">
      <Suspense fallback={<ProductSheetSkeleton />}>
        <ProductSheet params={params} />
      </Suspense>
    </main>
  );
}

app/(backoffice)/admin/settings/_actions.content:
"use server";

import { updateTag } from "next/cache";
import { unstable_rethrow } from "next/navigation";
import { z } from "zod";
import { requireAdmin } from "@/lib/dal/session";
import { resetThresholds, saveThresholds } from "@/lib/dal/thresholds";
import { thresholdsInputSchema } from "@/lib/schemas/inputs";
import { parsePercentInput, percentToRate } from "./_components/percent";
import { issuesToErrors } from "./_components/validation";

// BO-09 (specs/BO-09-seuils.md): one Server Action per form (CLAUDE.md's
// "une action par domaine"), both re-checking `requireAdmin()` even though
// `(backoffice)/layout.tsx` also gates the whole admin (mirrors every
// other admin action in this repo).
export type ThresholdsActionState = { ok?: boolean; errors?: Record<string, string>; formError?: string };

const productIdSchema = z.uuid().nullable();

function candidateFromForm(formData: FormData) {
  return {
    minVisits: Number(formData.get("minVisits")),
    killMaxConversion: percentToRate(parsePercentInput(String(formData.get("killMaxConversion") ?? ""))),
    scaleMinConversion: percentToRate(parsePercentInput(String(formData.get("scaleMinConversion") ?? ""))),
    scaleRequiresPositiveMargin: formData.get("scaleRequiresPositiveMargin") === "on",
  };
}

// drizzle wraps the Postgres driver's error on `.cause` (lib/db/schema.test.ts,
// plan's orchestrator decision 6); `23514` is a CHECK violation —
// `decision_thresholds_kill_lt_scale`, the one this form can actually
// trigger past its own Zod `.refine` (a race with another admin's save).
function isCheckViolation(err: unknown): boolean {
  const cause = (err as { cause?: { code?: unknown } } | undefined)?.cause;
  const code = cause?.code ?? (err as { code?: unknown } | undefined)?.code;
  return code === "23514";
}

const KILL_LT_SCALE_ERROR = { scaleMinConversion: "Le seuil « à scaler » doit être supérieur au seuil « à couper »" };

// BO-09 spec bullets 1, 2, 3, 5: saves the studio defaults (`productId ===
// null`) or a single product's override, from a form posting the % fields
// directly (no client-side JSON blob, unlike BO-05's product form: this
// form has 4 fields only).
export async function saveThresholdSettings(
  productId: string | null,
  _prevState: ThresholdsActionState,
  formData: FormData,
): Promise<ThresholdsActionState> {
  await requireAdmin();

  const parsedId = productIdSchema.safeParse(productId);
  if (!parsedId.success) return { formError: "Produit invalide" };

  const parsed = thresholdsInputSchema.safeParse(candidateFromForm(formData));
  if (!parsed.success) return { errors: issuesToErrors(parsed.error.issues) };

  try {
    const result = await saveThresholds(parsedId.data, parsed.data);
    if (!result.ok) return { formError: "Produit introuvable" };
    updateTag("thresholds");
    return { ok: true };
  } catch (err) {
    unstable_rethrow(err);
    if (isCheckViolation(err)) return { errors: KILL_LT_SCALE_ERROR };
    console.error("[admin/settings] saveThresholdSettings failed", err);
    throw err;
  }
}

// BO-09 spec bullet 2's « Réinitialiser »: deletes the product's override.
export async function resetProductThresholds(
  productId: string,
  _prevState: ThresholdsActionState,
  _formData: FormData,
): Promise<ThresholdsActionState> {
  await requireAdmin();

  const parsedId = z.uuid().safeParse(productId);
  if (!parsedId.success) return { formError: "Produit invalide" };

  try {
    const result = await resetThresholds(parsedId.data);
    if (!result.ok) return { formError: "Produit introuvable" };
    updateTag("thresholds");
    return { ok: true };
  } catch (err) {
    unstable_rethrow(err);
    console.error("[admin/settings] resetProductThresholds failed", err);
    throw err;
  }
}

app/(backoffice)/admin/settings/_compone.content:
// BO-09 (specs/BO-09-seuils.md): the two conversion thresholds are entered
// in % (docs/02-ecrans.md › BO-09: "conversion « à couper », conversion «
// à scaler » en %"), stored as a rate in [0, 1] (docs/07's
// `numeric(5,4)`). Rounded to 4 decimals before Zod sees it, so a value
// merely re-saved unchanged never drifts from the stored rate by a
// floating-point rounding error.
const RATE_DECIMALS = 1e4;

export function percentToRate(percent: number): number {
  return Math.round((percent / 100) * RATE_DECIMALS) / RATE_DECIMALS;
}

export function rateToPercent(rate: number): number {
  return Math.round(rate * RATE_DECIMALS * 100) / RATE_DECIMALS;
}

// A `<input type="number">`'s raw string value: `""` (cleared field) must
// fail Zod's `.number()` check rather than silently becoming `0`, so it
// parses to `NaN` like an unparsable string does.
export function parsePercentInput(raw: string): number {
  return raw === "" ? NaN : Number(raw);
}

import type { Thresholds, ThresholdOverride } from "@/lib/dal/thresholds";
import { evaluate, type Decision, type DecisionMetrics } from "@/lib/decision";
import type { ThresholdsInput } from "@/lib/schemas/inputs";

// BO-09's "avant d'enregistrer, aperçu des produits dont le badge
// changerait" (spec bullet 4): field-by-field merge, shared with
// `getThresholds` (lib/dal/thresholds.ts)'s own merge, but here pure and
// client-safe (no cache, no session).
export function mergeThresholds(base: Thresholds, override: ThresholdOverride | null): Thresholds {
  if (!override) return base;
  return {
    minVisits: override.minVisits ?? base.minVisits,
    killMaxConversion: override.killMaxConversion ?? base.killMaxConversion,
    scaleMinConversion: override.scaleMinConversion ?? base.scaleMinConversion,
    scaleRequiresPositiveMargin: override.scaleRequiresPositiveMargin ?? base.scaleRequiresPositiveMargin,
  };
}

export type PreviewProduct = {
  productId: string;
  name: string;
  visits: number;
  signupToPurchaseRate: number | null;
  marginPerGenerationMicros: number | null;
  override: ThresholdOverride | null;
};

// The defaults form previews every product (a product's own override, if
// any, still wins on the fields it sets); the per-product form previews
// only the one product being edited.
export type PreviewScope = { kind: "default" } | { kind: "product"; productId: string };

export type PreviewChange = { productId: string; name: string; before: Decision; after: Decision };

function metricsOf(product: PreviewProduct): DecisionMetrics {
  return {
    visits: product.visits,
    signupToPurchaseRate: product.signupToPurchaseRate,
    marginPerGenerationMicros: product.marginPerGenerationMicros,
  };
}

// BO-09's live preview (spec bullet 4), computed on the client from
// already-loaded data (no round trip while typing): only the rows whose
// `evaluate()` badge actually changes. The caller only invokes this with a
// candidate that already passed `thresholdsInputSchema.safeParse`
// (`ThresholdsSettings`/`ThresholdsForm`, plan design decision 7's "invalid
// candidate → no preview").
export function previewChanges(
  products: PreviewProduct[],
  defaults: Thresholds,
  scope: PreviewScope,
  candidate: ThresholdsInput,
): PreviewChange[] {
  const changes: PreviewChange[] = [];
  for (const product of products) {
    if (scope.kind === "product" && product.productId !== scope.productId) continue;
    const before = evaluate(metricsOf(product), mergeThresholds(defaults, product.override));
    const afterThresholds = scope.kind === "default" ? mergeThresholds(candidate, product.override) : candidate;
    const after = evaluate(metricsOf(product), afterThresholds);
    if (before !== after) changes.push({ productId: product.productId, name: product.name, before, after });
  }
  return changes;
}

import { Skeleton } from "@/components/ui/skeleton";

// Shared by <Suspense fallback> on /admin/settings and settings/loading.tsx
// (mirrors portfolio-skeleton.tsx's pattern): roughly the shape of
// ThresholdsSettings' two forms, so the page never jumps once the real
// data streams in.
export function SettingsSkeleton() {
  return (
    <div className="grid gap-6">
      <div className="grid gap-4 rounded-md border p-4">
        {Array.from({ length: 4 }, (_, index) => (
          <Skeleton key={index} className="h-9" />
        ))}
      </div>
      <div className="grid gap-4 rounded-md border p-4">
        {Array.from({ length: 4 }, (_, index) => (
          <Skeleton key={index} className="h-9" />
        ))}
      </div>
    </div>
  );
}

import type { PortfolioMetrics } from "@/lib/dal/metrics";
import type { ThresholdOverride, Thresholds } from "@/lib/dal/thresholds";
import type { ThresholdSettings } from "@/lib/dal/thresholds";
import type { ProductStatus } from "@/lib/schemas/product-config";

export type SettingsProductRow = {
  productId: string;
  name: string;
  status: ProductStatus;
  isSeed: boolean;
  visits: number;
  signupToPurchaseRate: number | null;
  marginPerGenerationMicros: number | null;
  override: ThresholdOverride | null;
};

export type SettingsView = {
  defaults: { values: Thresholds; isSeed: boolean };
  products: SettingsProductRow[];
};

// `/admin/settings`'s page-level join (plan design decision 9): the page
// reads `getPortfolioMetrics` and `getThresholdSettings` in parallel, then
// this pure function combines them into one row per product — funnel
// numbers for the live preview, `override` for the two forms. A product
// with no metrics row (a data inconsistency `getPortfolioMetrics` cannot
// produce for a product `getThresholdSettings` also lists, since both read
// the same `products` table) falls back to its id and zeroed metrics
// rather than throwing.
export function toSettingsView(metrics: PortfolioMetrics, settings: ThresholdSettings): SettingsView {
  const metricsByProductId = new Map(metrics.products.map((product) => [product.productId, product]));
  return {
    defaults: settings.defaults,
    products: settings.products.map((row) => {
      const product = metricsByProductId.get(row.productId);
      return {
        productId: row.productId,
        name: product?.name ?? row.productId,
        status: product?.status ?? "test",
        isSeed: row.isSeed,
        visits: product?.visits ?? 0,
        signupToPurchaseRate: product?.signupToPurchaseRate ?? null,
        marginPerGenerationMicros: product?.marginPerGenerationMicros ?? null,
        override: row.override,
      };
    }),
  };
}

"use client";

import { useActionState, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import type { Thresholds } from "@/lib/dal/thresholds";
import { thresholdsInputSchema } from "@/lib/schemas/inputs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveThresholdSettings, type ThresholdsActionState } from "../_actions";
import { parsePercentInput, percentToRate, rateToPercent } from "./percent";
import { previewChanges, type PreviewProduct } from "./preview";

const initialState: ThresholdsActionState = {};

// BO-09 spec bullet 1: the studio's default seuils (`/admin/settings`),
// with a live preview of the products whose badge would change (bullet 4).
export function ThresholdsForm({ defaults, products }: { defaults: Thresholds; products: PreviewProduct[] }) {
  const [minVisits, setMinVisits] = useState(String(defaults.minVisits));
  const [killPercent, setKillPercent] = useState(String(rateToPercent(defaults.killMaxConversion)));
  const [scalePercent, setScalePercent] = useState(String(rateToPercent(defaults.scaleMinConversion)));
  const [requiresMargin, setRequiresMargin] = useState(defaults.scaleRequiresPositiveMargin);
  const [state, formAction, pending] = useActionState(saveThresholdSettings.bind(null, null), initialState);

  useEffect(() => {
    if (state.ok) toast.success("Seuils par défaut enregistrés");
    if (state.formError) toast.error(state.formError);
  }, [state]);

  const errors = state.errors ?? {};

  const candidate = useMemo(() => {
    const parsed = thresholdsInputSchema.safeParse({
      minVisits: Number(minVisits),
      killMaxConversion: percentToRate(parsePercentInput(killPercent)),
      scaleMinConversion: percentToRate(parsePercentInput(scalePercent)),
      scaleRequiresPositiveMargin: requiresMargin,
    });
    return parsed.success ? parsed.data : null;
  }, [minVisits, killPercent, scalePercent, requiresMargin]);

  const changes = useMemo(
    () => (candidate ? previewChanges(products, defaults, { kind: "default" }, candidate) : []),
    [candidate, products, defaults],
  );

  return (
    <form action={formAction} className="grid gap-4 rounded-md border p-4">
      <h2 className="text-lg font-semibold">Seuils par défaut du studio</h2>

      <div className="grid gap-1.5">
        <Label htmlFor="default-min-visits">Visites minimales</Label>
