import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { cn } from "@/components/utils";

type Trend = "up" | "down" | "flat";

const TREND_CLASSES: Record<Trend, string> = {
  up: "text-primary",
  down: "text-destructive",
  flat: "text-muted-foreground",
};

// Normalises points to a 0..100 x / 0..100 y SVG polyline (no chart
// dependency, docs/02-ecrans.md › Carte KPI: value, 30-day delta, sparkline).
function sparklinePoints(points: number[]): string {
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  return points
    .map((value, index) => {
      const x = (index / (points.length - 1)) * 100;
      const y = 100 - ((value - min) / range) * 100;
      return `${x},${y}`;
    })
    .join(" ");
}

export function KpiCard({
  label,
  value,
  delta,
  points,
}: {
  label: string;
  value: string;
  delta?: { text: string; trend: Trend };
  points?: number[];
}) {
  return (
    <Card>
      <CardHeader className="pb-0">
        <p className="text-sm text-muted-foreground">{label}</p>
      </CardHeader>
      <CardContent className="flex items-end justify-between gap-2">
        <div>
          <p className="text-2xl font-semibold">{value}</p>
          {delta ? <p className={cn("text-xs", TREND_CLASSES[delta.trend])}>{delta.text}</p> : null}
        </div>
        {points && points.length > 1 ? (
          <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-8 w-20 text-primary" aria-hidden="true">
            <polyline points={sparklinePoints(points)} fill="none" stroke="currentColor" strokeWidth="4" />
          </svg>
        ) : null}
      </CardContent>
    </Card>
  );
}

lib/dal/metrics.ts.content:
import "server-only";
import { sql } from "drizzle-orm";
import { z } from "zod";
import { db } from "@/lib/db";
import type { EventType } from "@/lib/schemas/event-type";
import type { ProductStatus } from "@/lib/schemas/product-config";
import { requireAdmin } from "./session";

// Frozen contract (specs/CONTRACT-types.md). † Return shapes proposed from
// the BO-02 (portfolio) and BO-03 (product sheet) bullets of
// docs/02-ecrans.md, since docs/11's contract table only names the two
// functions. Money in cents, AI cost in micros (`cost_micros`, docs/07), a
// conversion rate is `null` when its denominator is 0. All read `events`
// (docs/01-produit.md). `getPortfolioMetrics` calls `requireAdmin()`
// (reads `headers()`) and is never cached, unlike docs/04's
// `metrics:{slug}` sketch (specs/BO-02-portefeuille.md plan, design
// decision 1): admin data streams under `<Suspense>` instead, like every
// other session-gated read in this file.
export type MetricsRange = { days: number };

export type ProductMetrics = {
  productId: string;
  slug: string;
  name: string;
  status: ProductStatus;
  visits: number;
  firstGenerations: number;
  signups: number;
  creditsExhausted: number;
  purchases: number;
  generations: number;
  revenueCents: number;
  aiCostMicros: number;
  signupToPurchaseRate: number | null;
  marginPerGenerationMicros: number | null;
};

export type PortfolioMetrics = {
  totals: { visits: number; revenueCents: number; aiCostMicros: number; marginMicros: number };
  products: ProductMetrics[];
};

export type FunnelStep = { type: Exclude<EventType, "generation">; count: number; rateFromPrevious: number | null };

export type DailyPoint = {
  date: string;
  visits: number;
  signups: number;
  purchases: number;
  revenueCents: number;
  aiCostMicros: number;
};

export type Funnel = { metrics: ProductMetrics; steps: FunnelStep[]; daily: DailyPoint[] };

const FUNNEL_STEP_TYPES = ["visit", "first_generation", "signup", "credits_exhausted", "purchase"] as const;

// The 5 funnel steps (BO-03) and their pass rate from the previous step, from one product's
// ProductMetrics: `null` for the first step (no previous step) and whenever the previous step's
// count is 0 (nothing to divide by). Each step counts distinct persons (QA1-P1-Q5), independent
// of whether that same person also has an event for the previous step (a person is never
// required to "pass through" earlier steps to be counted at a later one): the rate can still
// exceed 1 at the range boundary (e.g. a signup just before `since`, a credits_exhausted just
// after), so it is clamped to `[0, 1]` — the count itself is left untouched, a true fact.
function buildSteps(metrics: ProductMetrics): FunnelStep[] {
  const counts: Record<(typeof FUNNEL_STEP_TYPES)[number], number> = {
    visit: metrics.visits,
    first_generation: metrics.firstGenerations,
    signup: metrics.signups,
    credits_exhausted: metrics.creditsExhausted,
    purchase: metrics.purchases,
  };
  return FUNNEL_STEP_TYPES.map((type, index) => {
    const previousType = FUNNEL_STEP_TYPES[index - 1];
    const previousCount = previousType ? counts[previousType] : null;
    return {
      type,
      count: counts[type],
      rateFromPrevious: previousCount && previousCount > 0 ? Math.min(1, counts[type] / previousCount) : null,
    };
  });
}

type DailyRow = {
  date: string;
  visits: number;
  signups: number;
  purchases: number;
  revenue_cents: number | string;
  ai_cost_micros: number | string;
};

function toDailyPoint(row: DailyRow): DailyPoint {
  return {
    date: row.date,
    visits: row.visits,
    signups: row.signups,
    purchases: row.purchases,
    revenueCents: Number(row.revenue_cents),
    aiCostMicros: Number(row.ai_cost_micros),
  };
}

// One point per UTC calendar day of the range, `since` (00:00 UTC) to today included, zero-filled
// where nothing happened (docs/01: "courbes sur 30 jours"). Own query, filtered to one product:
// `events` for visits/signups/purchases, `purchases` for revenue, `generations` for AI cost (every
// status, like selectProductRows). Bucketed by `(created_at at time zone 'UTC')::date` so the
// day boundary is UTC midnight regardless of the server's local time zone.
async function selectDailyPoints(productId: string, since: string, days: number): Promise<DailyPoint[]> {
  const result = await db.execute<DailyRow>(sql`
    select
      to_char(gs.day, 'YYYY-MM-DD') as date,
      coalesce(ev.visits, 0)::int as visits,
      coalesce(ev.signups, 0)::int as signups,
      coalesce(ev.purchases, 0)::int as purchases,
      coalesce(pu.revenue_cents, 0)::bigint as revenue_cents,
      coalesce(gen.ai_cost_micros, 0)::bigint as ai_cost_micros
    from generate_series(${since}::date, ${since}::date + (${days - 1} || ' days')::interval, interval '1 day') as gs(day)
    left join (
      select
        (created_at at time zone 'UTC')::date as day,
        count(*) filter (where type = 'visit') as visits,
        count(*) filter (where type = 'signup') as signups,
        count(*) filter (where type = 'purchase') as purchases
      from events
      where product_id = ${productId} and created_at >= ${since}
      group by 1
    ) ev on ev.day = gs.day
    left join (
      select (created_at at time zone 'UTC')::date as day, sum(amount_cents) as revenue_cents
      from purchases
      where product_id = ${productId} and created_at >= ${since}
      group by 1
    ) pu on pu.day = gs.day
    left join (
      select (created_at at time zone 'UTC')::date as day, coalesce(sum(cost_micros), 0) as ai_cost_micros
      from generations
      where product_id = ${productId} and created_at >= ${since}
      group by 1
    ) gen on gen.day = gs.day
    order by gs.day asc
  `);
  return [...result].map(toDailyPoint);
}

const MIN_RANGE_DAYS = 1;
const MAX_RANGE_DAYS = 365;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

// `{ days: 1 }` means "today only", `{ days: 30 }` the last 30 UTC calendar
// days, today included: `since` is 00:00 UTC of the day `days - 1` days ago
// (specs/BO-02-portefeuille.md plan, design decision 3).
function computeSince(days: number, now: Date = new Date()): Date {
  const startOfToday = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return new Date(startOfToday - (days - 1) * MS_PER_DAY);
}

function validateRangeDays(range: MetricsRange): number {
  const { days } = range;
  if (!Number.isInteger(days) || days < MIN_RANGE_DAYS || days > MAX_RANGE_DAYS) {
    throw new RangeError(
      `MetricsRange.days must be an integer between ${MIN_RANGE_DAYS} and ${MAX_RANGE_DAYS}, got ${days}`,
    );
  }
  return days;
}

export type PortfolioRow = {
  product_id: string;
  slug: string;
  name: string | null;
  status: ProductStatus;
  visits: number;
  first_generations: number;
  signups: number;
  credits_exhausted: number;
  purchases: number;
  generations: number;
  revenue_cents: number | string;
  ai_cost_micros: number | string;
  buyers: number;
  credits_sold: number;
  cost_per_generation: number | null;
};

// The pure row → ProductMetrics mapping (exported for lib/dal/metrics.test.ts to exercise
// directly with a fabricated row, instead of inserting a schema-invalid product_versions row
// into the shared test DB — specs/BO-02-portefeuille.md review round). Two defensive
// fallbacks, both driven by data SQL alone cannot guarantee (a product's config could, in
// theory, be missing `name` or `pricing.costPerGeneration`):
// - `name`: `null` (config has no `name`) falls back to `slug`.
// - `marginPerGenerationMicros`: a price per credit (in micros, from the pack revenue
//   actually collected in range) times the product's `costPerGeneration`, minus the average
//   AI cost of a succeeded generation (specs/BO-02-portefeuille.md plan, design decision 2).
//   `null` when there is nothing to divide by: no credits sold, no succeeded generation, or no
//   `costPerGeneration` in the product's config.
export function toProductMetrics(row: PortfolioRow): ProductMetrics {
  const revenueCents = Number(row.revenue_cents);
  const aiCostMicros = Number(row.ai_cost_micros);
  const signupToPurchaseRate = row.signups > 0 ? row.buyers / row.signups : null;
  const marginPerGenerationMicros =
    row.credits_sold > 0 && row.generations > 0 && row.cost_per_generation !== null
      ? Math.round(((revenueCents * 10_000) / row.credits_sold) * row.cost_per_generation) -
        Math.round(aiCostMicros / row.generations)
      : null;
  return {
    productId: row.product_id,
    slug: row.slug,
    name: row.name ?? row.slug,
    status: row.status,
    visits: row.visits,
    firstGenerations: row.first_generations,
    signups: row.signups,
    creditsExhausted: row.credits_exhausted,
    purchases: row.purchases,
    generations: row.generations,
    revenueCents,
    aiCostMicros,
    signupToPurchaseRate,
    marginPerGenerationMicros,
  };
}

// The portfolio's aggregation SQL (BO-02), extracted so getFunnel (BO-03) can reuse it filtered
// to one product instead of duplicating the 3 subqueries: `products` joined to its current
// `product_versions` row (for `name` and `pricing.costPerGeneration`), left-joined to `events`
// (the 5 funnel-step counts), `purchases` (revenue, credits sold, distinct buyers) and
// `generations` (succeeded count, AI cost over every status), grouped by `product_id` so no
// product fans out into duplicate rows. With no `productId`, every product is returned, `killed`
// included; with one, at most one row (empty when the id doesn't exist).
//
// Each of the 5 step counts is `count(distinct coalesce(user_id, anonymous_id))` (QA1-P1-Q5): one
// identity for every type, not user_id for signup/credits_exhausted/purchase and anonymous_id for
// visit separately. In production this is exactly D1's identity (every real signup/
// credits_exhausted/purchase write always carries a userId, so coalesce resolves to user_id
// there, and visit/first_generation never carry a userId of their own kind that would collide) —
// the change only matters for scripts/seed.ts's synthetic story, which sets anonymous_id alone
// for all 5 types and must still count as one person per anonymous_id, not 0 (orchestrator
// decision: scripts/seed.ts itself stays untouched, out of this spec's Périmètre).
async function selectProductRows(since: string, productId?: string): Promise<PortfolioRow[]> {
  const result = await db.execute<PortfolioRow>(sql`
    select
      p.id as product_id,
      p.slug as slug,
      pv.config ->> 'name' as name,
      p.status as status,
      coalesce(ev.visits, 0)::int as visits,
      coalesce(ev.first_generations, 0)::int as first_generations,
      coalesce(ev.signups, 0)::int as signups,
      coalesce(ev.credits_exhausted, 0)::int as credits_exhausted,
      coalesce(ev.purchases, 0)::int as purchases,
      coalesce(gen.generations, 0)::int as generations,
      coalesce(pu.revenue_cents, 0)::bigint as revenue_cents,
      coalesce(gen.ai_cost_micros, 0)::bigint as ai_cost_micros,
      coalesce(pu.buyers, 0)::int as buyers,
      coalesce(pu.credits_sold, 0)::int as credits_sold,
      (pv.config -> 'pricing' ->> 'costPerGeneration')::int as cost_per_generation
    from products p
    inner join product_versions pv
      on pv.product_id = p.id and pv.version = p.current_version
    left join (
      select
        product_id,
        count(distinct coalesce(user_id, anonymous_id)) filter (where type = 'visit') as visits,
        count(distinct coalesce(user_id, anonymous_id)) filter (where type = 'first_generation') as first_generations,
        count(distinct coalesce(user_id, anonymous_id)) filter (where type = 'signup') as signups,
        count(distinct coalesce(user_id, anonymous_id)) filter (where type = 'credits_exhausted') as credits_exhausted,
        count(distinct coalesce(user_id, anonymous_id)) filter (where type = 'purchase') as purchases
      from events
      where created_at >= ${since}
      group by product_id
    ) ev on ev.product_id = p.id
    left join (
      select
        product_id,
        sum(amount_cents) as revenue_cents,
        sum(credits) as credits_sold,
        count(distinct user_id) as buyers
      from purchases
      where created_at >= ${since}
      group by product_id
    ) pu on pu.product_id = p.id
    left join (
      select
        product_id,
        count(*) filter (where status = 'succeeded') as generations,
        coalesce(sum(cost_micros), 0) as ai_cost_micros
      from generations
      where created_at >= ${since}
      group by product_id
    ) gen on gen.product_id = p.id
    ${productId ? sql`where p.id = ${productId}` : sql``}
  `);
  return [...result];
}

// Powers the portfolio (BO-02); calls `requireAdmin()` inside, before
// validating the range (specs/BO-02-portefeuille.md plan, design decision 2).
export const getPortfolioMetrics: (range: MetricsRange) => Promise<PortfolioMetrics> = async (range) => {
  await requireAdmin();
  const days = validateRangeDays(range);
  // `postgres` (the driver) refuses a bare `Date` as a bind parameter; an
  // ISO string round-trips through `timestamptz` correctly.
  const since = computeSince(days).toISOString();

  const productMetrics = (await selectProductRows(since)).map(toProductMetrics);
  return {
    totals: {
      visits: productMetrics.reduce((sum, product) => sum + product.visits, 0),
      revenueCents: productMetrics.reduce((sum, product) => sum + product.revenueCents, 0),
      aiCostMicros: productMetrics.reduce((sum, product) => sum + product.aiCostMicros, 0),
      marginMicros: productMetrics.reduce(
        (sum, product) => sum + product.revenueCents * 10_000 - product.aiCostMicros,
        0,
      ),
    },
    products: productMetrics,
  };
};

// Powers the product sheet (BO-03); calls `requireAdmin()` inside, before validating the range
// (mirrors getPortfolioMetrics). A malformed or unknown productId throws before any SQL runs
// (`z.uuid()`, cheaper and clearer than a Postgres "invalid input syntax for type uuid" error):
// there is no "empty funnel" to render for a product that doesn't exist, unlike an idle product,
// whose row exists with zero counts.
export const getFunnel: (productId: string, range: MetricsRange) => Promise<Funnel> = async (productId, range) => {
  await requireAdmin();
  const days = validateRangeDays(range);
  if (!z.uuid().safeParse(productId).success) {
    throw new Error(`getFunnel: unknown product ${productId}`);
  }
  const since = computeSince(days).toISOString();

  const [row] = await selectProductRows(since, productId);
  if (!row) throw new Error(`getFunnel: unknown product ${productId}`);
  const metrics = toProductMetrics(row);
  const daily = await selectDailyPoints(productId, since, days);
  return { metrics, steps: buildSteps(metrics), daily };
};

lib/dal/thresholds.ts.content:
import "server-only";
import { isNull, isNotNull, or, eq } from "drizzle-orm";
import { cacheLife, cacheTag } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { decisionThresholds, products } from "@/lib/db/schema";
import { thresholdsInputSchema, type ThresholdsInput } from "@/lib/schemas/inputs";
import { requireAdmin } from "./session";

// The default row's 4 fields are `CHECK (product_id IS NOT NULL OR all 4
// values NOT NULL)` in the database (docs/07), but the Drizzle column
// types stay nullable: this schema turns that DB invariant into a runtime
// check instead of an unchecked `!` assertion.
const defaultThresholdsRowSchema = z.object({
  minVisits: z.number(),
  killMaxConversion: z.number(),
  scaleMinConversion: z.number(),
  scaleRequiresPositiveMargin: z.boolean(),
});

// Frozen contract (specs/CONTRACT-types.md): the merged (default + product
// override) decision thresholds (docs/07 › decision_thresholds), read by
// `lib/decision.ts`'s pure `evaluate(metrics, thresholds)`. Cached, tag
// `thresholds` (docs/11's contract table). Real in V1 (reads the seeded
// setting); only the write arrives with BO-09. Studio-wide, non-sensitive,
// cached data: no session check here, unlike the write side (BO-09).
export type Thresholds = {
  minVisits: number;
  killMaxConversion: number;
  scaleMinConversion: number;
  scaleRequiresPositiveMargin: boolean;
};

export const getThresholds: (productId: string) => Promise<Thresholds> = async (productId) => {
  "use cache";
  cacheLife("max");
  cacheTag("thresholds");

  // One query for both rows (docs/07): the default (product_id IS NULL)
  // and this product's override, if any.
  const rows = await db.query.decisionThresholds.findMany({
    where: or(isNull(decisionThresholds.productId), eq(decisionThresholds.productId, productId)),
  });
  const defaultRow = rows.find((row) => row.productId === null);
  if (!defaultRow) throw new Error("default thresholds missing");
  const parsedDefault = defaultThresholdsRowSchema.safeParse(defaultRow);
  if (!parsedDefault.success) throw new Error("default thresholds row incomplete");
  const defaults = parsedDefault.data;
  const override = rows.find((row) => row.productId === productId);

  return {
    minVisits: override?.minVisits ?? defaults.minVisits,
    killMaxConversion: override?.killMaxConversion ?? defaults.killMaxConversion,
    scaleMinConversion: override?.scaleMinConversion ?? defaults.scaleMinConversion,
    scaleRequiresPositiveMargin: override?.scaleRequiresPositiveMargin ?? defaults.scaleRequiresPositiveMargin,
  };
};

// BO-09 (specs/BO-09-seuils.md): the admin-only per-product override, or
// `null` when the product follows the studio defaults as-is.
export type ThresholdOverride = { [K in keyof Thresholds]: Thresholds[K] | null };

// BO-09's /admin/settings read: the studio defaults plus every product's
// own override (or `null`), so the page can render both forms and the
// "surchargé" list without one round trip per product.
export type ThresholdSettings = {
  defaults: { values: Thresholds; isSeed: boolean };
  products: { productId: string; isSeed: boolean; override: ThresholdOverride | null }[];
};

export type ThresholdsWriteResult = { ok: true } | { ok: false; reason: "product_not_found" };

function toOverride(row: {
  minVisits: number | null;
  killMaxConversion: number | null;
  scaleMinConversion: number | null;
  scaleRequiresPositiveMargin: boolean | null;
}): ThresholdOverride {
  return {
    minVisits: row.minVisits,
    killMaxConversion: row.killMaxConversion,
    scaleMinConversion: row.scaleMinConversion,
    scaleRequiresPositiveMargin: row.scaleRequiresPositiveMargin,
  };
}

// BO-09's read side of `/admin/settings` (admin-gated, uncached: an admin
// editing the thresholds always sees the row it is about to write, unlike
// the public, cached `getThresholds` above).
export async function getThresholdSettings(): Promise<ThresholdSettings> {
  await requireAdmin();

  const defaultRow = await db.query.decisionThresholds.findFirst({
    where: isNull(decisionThresholds.productId),
  });
  if (!defaultRow) throw new Error("default thresholds missing");
  const parsedDefault = defaultThresholdsRowSchema.safeParse(defaultRow);
  if (!parsedDefault.success) throw new Error("default thresholds row incomplete");

  const productRows = await db.select({ id: products.id, isSeed: products.isSeed }).from(products);
  const overrideRows = await db.query.decisionThresholds.findMany({
    where: isNotNull(decisionThresholds.productId),
  });
  const overrideByProductId = new Map(overrideRows.map((row) => [row.productId as string, row]));

  return {
    defaults: { values: parsedDefault.data, isSeed: defaultRow.isSeed },
    products: productRows.map((product) => {
      const override = overrideByProductId.get(product.id);
      return { productId: product.id, isSeed: product.isSeed, override: override ? toOverride(override) : null };
    }),
  };
}

// docs/07's `numeric(5,4)` stores 4 decimals; compares rounded to the same
// precision so a value merely re-saved unchanged is treated as equal to
// the default, never stored as a spurious override.
const RATE_SCALE = 1e4;
function sameRate(a: number, b: number): boolean {
  return Math.round(a * RATE_SCALE) === Math.round(b * RATE_SCALE);
}

// BO-09's diff-against-default override storage (plan design decision 2):
// `minVisits` and `scaleRequiresPositiveMargin` are stored only when they
// differ from the default; the two conversions are stored as a pair (both
// or neither) so an override can never silently pair one edited rate with
// the studio's own other rate and violate `kill < scale` behind the
// admin's back. All 4 null means "no override left": the row is deleted.
function buildOverrideValues(
  candidate: ThresholdsInput,
  defaults: Thresholds,
): {
  minVisits: number | null;
  killMaxConversion: number | null;
  scaleMinConversion: number | null;
  scaleRequiresPositiveMargin: boolean | null;
} {
  const conversionsDiffer =
    !sameRate(candidate.killMaxConversion, defaults.killMaxConversion) ||
    !sameRate(candidate.scaleMinConversion, defaults.scaleMinConversion);
  return {
    minVisits: candidate.minVisits === defaults.minVisits ? null : candidate.minVisits,
    killMaxConversion: conversionsDiffer ? candidate.killMaxConversion : null,
    scaleMinConversion: conversionsDiffer ? candidate.scaleMinConversion : null,
    scaleRequiresPositiveMargin:
      candidate.scaleRequiresPositiveMargin === defaults.scaleRequiresPositiveMargin
        ? null
        : candidate.scaleRequiresPositiveMargin,
  };
}

function isAllNull(values: {
  minVisits: number | null;
  killMaxConversion: number | null;
  scaleMinConversion: number | null;
  scaleRequiresPositiveMargin: boolean | null;
}): boolean {
  return (
    values.minVisits === null &&
    values.killMaxConversion === null &&
    values.scaleMinConversion === null &&
    values.scaleRequiresPositiveMargin === null
  );
}

// BO-09's save, for the studio defaults (`productId === null`) or a single
// product's override. `values` is already Zod-valid (`ThresholdsInput`,
// `kill < scale`); this function re-validates it (a DAL function is never
// the only line of defense, CLAUDE.md) and lets a `ZodError` propagate to
// the caller.
export async function saveThresholds(
  productId: string | null,
  values: ThresholdsInput,
): Promise<ThresholdsWriteResult> {
  const session = await requireAdmin();
  const parsed = thresholdsInputSchema.parse(values);

  if (productId === null) {
    await db.transaction(async (tx) => {
      const [row] = await tx
        .select()
        .from(decisionThresholds)
        .where(isNull(decisionThresholds.productId))
        .for("update");
      if (!row) throw new Error("saveThresholds: default thresholds row missing");
      await tx
        .update(decisionThresholds)
        .set({
          minVisits: parsed.minVisits,
          killMaxConversion: parsed.killMaxConversion,
          scaleMinConversion: parsed.scaleMinConversion,
          scaleRequiresPositiveMargin: parsed.scaleRequiresPositiveMargin,
          updatedBy: session.user.id,
          updatedAt: new Date(),
        })
        .where(isNull(decisionThresholds.productId));
    });
    return { ok: true };
  }

  return db.transaction(async (tx) => {
    // Not `.for("update")`: this row is only read to check the product
    // exists, never written by this transaction (the diff below writes
    // `decisionThresholds`, not `products`), so there is nothing here to
    // serialize against a concurrent write.
    const [productRow] = await tx.select().from(products).where(eq(products.id, productId));
    if (!productRow) return { ok: false, reason: "product_not_found" as const };

    // Locked too (review round, DB MEDIUM): without `.for("update")` here, a
    // concurrent default save (which does lock this row) could commit its
    // own new default in between this read and this override's insert,
    // leaving the diff computed against a stale default — this blocks
    // until that other transaction commits and reads its fresh values.
    const [defaultRow] = await tx
      .select()
      .from(decisionThresholds)
      .where(isNull(decisionThresholds.productId))
      .for("update");
    if (!defaultRow) throw new Error("saveThresholds: default thresholds row missing");
    const defaults = defaultThresholdsRowSchema.parse(defaultRow);

    const overrideValues = buildOverrideValues(parsed, defaults);
    if (isAllNull(overrideValues)) {
      await tx.delete(decisionThresholds).where(eq(decisionThresholds.productId, productId));
      return { ok: true };
    }

    await tx
      .insert(decisionThresholds)
      .values({ productId, ...overrideValues, updatedBy: session.user.id })
      .onConflictDoUpdate({
        target: decisionThresholds.productId,
        set: { ...overrideValues, updatedBy: session.user.id, updatedAt: new Date() },
      });
    return { ok: true };
  });
}

// BO-09's « Réinitialiser » (spec bullet 2): deletes the product's override
// row so it falls back to the studio defaults. Idempotent: a product with
// no override row returns `{ ok: true }` too.
export async function resetThresholds(productId: string): Promise<ThresholdsWriteResult> {
  await requireAdmin();
  return db.transaction(async (tx) => {
    // Not `.for("update")`: only an existence check, this transaction never
    // writes `products`.
    const [productRow] = await tx.select().from(products).where(eq(products.id, productId));
    if (!productRow) return { ok: false, reason: "product_not_found" as const };
    await tx.delete(decisionThresholds).where(eq(decisionThresholds.productId, productId));
    return { ok: true };
  });
}

lib/decision.ts.content:
import type { Thresholds } from "./dal/thresholds";

// Frozen contract (specs/BO-02-portefeuille.md, plan decision 5): a pure
// function, independent of the product's current status, so BO-02 and
// BO-03 both suggest the same badge from the same metrics and thresholds.
export type Decision = "kill" | "scale" | null;

export type DecisionMetrics = {
  visits: number;
  signupToPurchaseRate: number | null;
  marginPerGenerationMicros: number | null;
};

// docs/01-produit.md › Statut Test → Learn → Scale → Killed, docs/07 ›
// decision_thresholds: below min_visits, no suggestion at all (not enough
// volume to trust the rate); a null rate (no signup yet) never suggests a
// badge either, kill included (plan decision 4, literal rule).
export function evaluate(metrics: DecisionMetrics, thresholds: Thresholds): Decision {
  if (metrics.visits < thresholds.minVisits) return null;
  const { signupToPurchaseRate: rate, marginPerGenerationMicros: margin } = metrics;
  if (rate === null) return null;
  if (rate < thresholds.killMaxConversion) return "kill";
  const marginOk = !thresholds.scaleRequiresPositiveMargin || (margin !== null && margin > 0);
  if (rate >= thresholds.scaleMinConversion && marginOk) return "scale";
  return null;
}

lib/schemas/inputs.ts.content:
import { z } from "zod";
import { eventTypeSchema } from "./event-type";
import { packSchema } from "./pack";
import { MAX_INPUTS, productStatusSchema } from "./product-config";

// Same key format as inputFieldSchema.key (product-config.ts): a field key
// is always a lowercase identifier.
const inputFieldKeySchema = z.string().regex(/^[a-z][a-z0-9_]*$/, "key must start with a lowercase letter");

// Input schemas of the Server Actions and Route Handlers of later specs
// (CLAUDE.md: "Every Server Action and Route Handler re-checks auth and
// parses input with the shared Zod schema from lib/schemas/"). Frozen here
// per specs/CONTRACT-types.md so no later spec needs lib/schemas in its
// Périmètre.

// SA-02 `api/generate`: the per-field check against `config.inputs` happens
// in the route, from the product config; this schema only bounds the shape
// and rejects an oversized payload before that comparison runs — a product
// declares at most MAX_INPUTS fields (product-config.ts), so the record
// can never legitimately carry more keys.
export const generateInputSchema = z.object({
  input: z
    .record(inputFieldKeySchema, z.string().max(5000))
    .refine((input) => Object.keys(input).length <= MAX_INPUTS, {
      error: `at most ${MAX_INPUTS} input keys`,
    }),
  idempotencyKey: z.uuid(),
});
export type GenerateInput = z.infer<typeof generateInputSchema>;

// SA-03 signup (magic link).
export const signupInputSchema = z.object({
  email: z.email(),
});
export type SignupInput = z.infer<typeof signupInputSchema>;

// SA-05 purchase: a pack id is only unique within a product, so `purchase`
// itself also takes `productId` (see lib/dal/credits.ts).
export const purchaseInputSchema = z.object({
  packId: packSchema.shape.id,
  idempotencyKey: z.uuid(),
});
export type PurchaseInput = z.infer<typeof purchaseInputSchema>;

// TRACKING beacon (`api/events`): the product comes from the route's
// `[app]`, not from the body. `metadata` is public, unauthenticated input
// (sendBeacon, docs/04-nextjs.md), so it is bounded: at most 10 keys, each
// at most 40 characters, and a string value at most 200 characters.
const metadataValueSchema = z.union([z.string().max(200), z.number(), z.boolean(), z.null()]);
export const trackEventInputSchema = z.object({
  type: eventTypeSchema,
  anonymousId: z.uuid(),
  metadata: z
    .record(z.string().max(40), metadataValueSchema)
    .refine((metadata) => Object.keys(metadata).length <= 10, { error: "at most 10 metadata keys" })
    .optional(),
});
export type TrackEventInput = z.infer<typeof trackEventInputSchema>;

// BO-06 status change.
export const statusChangeInputSchema = z.object({
  status: productStatusSchema,
  note: z.string().max(500).nullable(),
});
export type StatusChangeInput = z.infer<typeof statusChangeInputSchema>;

// BO-09 decision thresholds. Mirrors docs/07's
// `CHECK (kill_max_conversion < scale_min_conversion)` and
// `CHECK (min_visits > 0)`; BO-05's mockup (docs/02-ecrans.md): "Erreur si
// « à couper » ≥ « à scaler »".
export const thresholdsInputSchema = z
  .object({
    minVisits: z.int().min(1),
    killMaxConversion: z.number().min(0).max(1),
    scaleMinConversion: z.number().min(0).max(1),
    scaleRequiresPositiveMargin: z.boolean(),
  })
  .refine((thresholds) => thresholds.killMaxConversion < thresholds.scaleMinConversion, {
    error: "scaleMinConversion must be greater than killMaxConversion",
    path: ["scaleMinConversion"],
  });
export type ThresholdsInput = z.infer<typeof thresholdsInputSchema>;

