"use server";

import { APIError } from "better-auth/api";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";
import { adminLoginSchema } from "@/lib/schemas/admin-login";

export type LoginState = { error?: string };

const GENERIC_ERROR = "Identifiants invalides";

export async function login(_prevState: LoginState, formData: FormData): Promise<LoginState> {
  const parsed = adminLoginSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });
  if (!parsed.success) return { error: GENERIC_ERROR };

  try {
    await auth.api.signInEmail({ body: parsed.data, headers: await headers() });
  } catch (err) {
    if (!(err instanceof APIError)) {
      // An infrastructure failure (DB outage, network error…), not an auth
      // rejection: the auth hook in lib/auth.ts and Better Auth itself only
      // ever throw APIError for a wrong password or a role=user account.
      // Log it server-side with context instead of swallowing it silently;
      // the UI still gets the same generic message, never a stack trace.
      console.error("[admin/login] unexpected error during sign-in", err);
      return { error: GENERIC_ERROR };
    }
    // Same message for a wrong password and for a role=user account: the
    // auth hook in lib/auth.ts already makes both fail the same way, and
    // this action never distinguishes them either (docs/07-modele-de-donnees.md).
    return { error: GENERIC_ERROR };
  }

  redirect("/admin");
}

app/(backoffice)/admin/ops/_actions.ts.content:
"use server";

import { updateTag } from "next/cache";
import { unstable_rethrow } from "next/navigation";
import { listThemeOptions } from "@/lib/dal/product-editor";
import { listProducts } from "@/lib/dal/products";
import { requireAdmin } from "@/lib/dal/session";
// The one accepted exception to "only lib/dal touches the database"
// (docs/09, plan's orchestrator decision 7): scripts/reset-demo.ts owns
// its own Postgres client, exactly like scripts/seed.ts, so it stays
// usable from the CLI (`pnpm tsx scripts/reset-demo.ts`) and from here.
import { resetDemo } from "@/scripts/reset-demo";

export type ResetDemoState = { ok?: boolean; error?: string };

// BO-01's admin/ops page (specs/DEMO-mode.md): owner-only, re-checked here
// too (a Server Action is a public POST endpoint, CLAUDE.md), never just
// on the page. `listProducts`/`listThemeOptions` are read *before*
// resetDemo runs, so every slug and seeded theme that existed a moment
// ago (visitor-created products included) gets its cache tag cleared too,
// not only the ones that survive the reset.
export async function resetDemoAction(_prevState: ResetDemoState, _formData: FormData): Promise<ResetDemoState> {
  const session = await requireAdmin();
  if (session.user.role !== "owner") {
    return { error: "Réservé au propriétaire de la démo" };
  }

  try {
    const [productsBefore, themes] = await Promise.all([listProducts(), listThemeOptions()]);

    await resetDemo();

    updateTag("products");
    updateTag("thresholds");
    for (const product of productsBefore) updateTag(`product:${product.slug}`);
    for (const theme of themes.filter((candidate) => candidate.isSeed)) updateTag(`theme:${theme.id}`);

    return { ok: true };
  } catch (err) {
    unstable_rethrow(err);
    console.error("[admin/ops] resetDemoAction failed", err);
    return { error: "La réinitialisation a échoué" };
  }
}

app/(backoffice)/admin/ops/_components/r.content:
"use client";

import { useActionState, useEffect, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import type { ResetDemoState } from "../_actions";

const initialState: ResetDemoState = {};

// `_actions.ts` transitively imports the DAL and scripts/reset-demo.ts's
// own Postgres client — a static import here would drag that into every
// test that renders this component (mirrors status-change.tsx's own
// comment for the exact same reason).
async function callResetDemoAction(prevState: ResetDemoState, formData: FormData): Promise<ResetDemoState> {
  const { resetDemoAction } = await import("../_actions");
  return resetDemoAction(prevState, formData);
}

// specs/DEMO-mode.md (orchestrator decision 7): a destructive two-step
// confirm, no navigation link anywhere pointing at this page. The first
// click only reveals the confirmation step; the Server Action only ever
// runs from the second, explicit click.
export function ResetForm() {
  const [confirming, setConfirming] = useState(false);
  const [state, formAction, pending] = useActionState(callResetDemoAction, initialState);

  // Collapses back to the first step the moment a *new* successful result
  // arrives — adjusted during render, not in an effect (React docs:
  // "storing information from previous renders"), so it converges within
  // the same render pass instead of a setState-in-effect's extra one.
  const [handledState, setHandledState] = useState(state);
  if (state !== handledState) {
    setHandledState(state);
    if (state.ok) setConfirming(false);
  }

  useEffect(() => {
    if (state.ok) toast.success("Démo réinitialisée");
    else if (state.error) toast.error(state.error);
  }, [state]);

  if (!confirming) {
    return (
      <Button type="button" variant="destructive" onClick={() => setConfirming(true)}>
        Réinitialiser la démo
      </Button>
    );
  }

  return (
    <form action={formAction} className="grid gap-4">
      <p role="alert" className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm">
        {state.error ??
          "Cette action supprime les produits créés par les visiteurs et toute l'activité, puis rejoue le seed. Irréversible."}
      </p>
      <div className="flex gap-2">
        <Button type="button" variant="outline" onClick={() => setConfirming(false)} disabled={pending}>
          Annuler
        </Button>
        <Button type="submit" variant="destructive" disabled={pending}>
          Confirmer la réinitialisation
        </Button>
      </div>
    </form>
  );
}

app/(backoffice)/admin/ops/page.tsx.content:
import { Suspense } from "react";
import { notFound } from "next/navigation";
import { getSession, requireAdmin } from "@/lib/dal/session";
import { ResetForm } from "./_components/reset-form";

// A 60s timeout for the reset Server Action invoked from this page
// (resetDemoAction wipes and reseeds usage across 3 products, longer than
// the default action timeout might allow): the route segment config
// applies here rather than on `_actions.ts` itself — a build spike
// (plan's orchestrator decision 6) showed Turbopack rejects any
// non-async export from a `'use server'` file, `export const maxDuration`
// included.
export const maxDuration = 60;

// QA1-P2-N1: OpsPage itself stays synchronous, with no top-level `await`.
// getSession()/requireAdmin() read the session (io() + cookies()/headers(),
// lib/dal/session.ts) — a request-time read that Cache Components can't
// prerender into the route's static shell. Read directly here, it broke
// navigation prerendering ("uncached data during prerendering or a
// navigation … accessed outside of `<Suspense>`", reproduced on the dev
// server against an RSC prefetch of /admin/ops). Pushed into <OpsGate>
// under <Suspense> instead, matching the framework's own pattern (docs/04
// › Rendu et cache; node_modules/next/dist/docs/01-app/02-guides/
// authentication-with-cache-components.md › "Show the user without
// blocking the page").
export default function OpsPage() {
  return (
    <main className="mx-auto grid max-w-xl gap-6 p-6">
      <Suspense fallback={<OpsFallback />}>
        <OpsGate />
      </Suspense>
    </main>
  );
}

function OpsFallback() {
  return <p className="text-sm text-muted-foreground">Chargement…</p>;
}

// specs/DEMO-mode.md: not `ops/_ops` (a `_`-prefixed segment is never
// routable, docs/09-arborescence.md), reserved to the `owner` role, 404
// for anyone else — including a role="admin" caller, who gets a real
// admin session but is still not this repo's `owner` (docs/07 › `users`).
// No link anywhere points here: it stays "cachée" by omission.
async function OpsGate() {
  const session = await getSession();
  if (session?.user.role !== "owner") {
    notFound();
  }
  // Not dead code: the owner check above already 404s anyone who isn't
  // `owner`, but this still defends in depth on the owner path itself
  // (an owner session that somehow fails requireAdmin's own check —
  // e.g. expired between the two calls — is redirected to /admin/login
  // instead of falling through). It's also what keeps every /admin page
  // calling requireAdmin() itself true (require-admin coverage test,
  // app/(backoffice)/admin/require-admin-coverage.test.ts, which reads
  // this whole file's source, not just OpsPage's own body).
  await requireAdmin();

  return (
    <>
      <h1 className="text-2xl font-semibold">Opérations</h1>
      <p className="text-sm text-muted-foreground">
        Supprime les produits créés par les visiteurs et toute l&apos;activité, puis rejoue le seed (thèmes, LettrePro,
        DescriPro, NomDeMarque, comptes admin et owner, seuils par défaut).
      </p>
      <ResetForm />
    </>
  );
}

