app/(products)/[app]/api/events/anonymou.content:
import "server-only";
import { z } from "zod";

// Shared by api/events (TRACKING) and, later, SA-02 and SA-03 (plan's
// Orchestrator decision 2): a single cookie name and shape, so the visit
// beacon and an authenticated generation or signup agree on the same
// anonymous id.
export const ANONYMOUS_ID_COOKIE = "anonymous_id";
const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

// The nil (all-zero) and max (all-one) uuids are syntactically valid per
// z.uuid() but never a real, proxy.ts-minted identity (QA1-P1-B4 plan step
// 6): treating them as "no cookie" keeps readAnonymousId's guarantee that a
// non-null result always came from a real random identity.
const DEGENERATE_UUIDS = new Set(["00000000-0000-0000-0000-000000000000", "ffffffff-ffff-ffff-ffff-ffffffffffff"]);

// The cookie is server-authoritative: only a syntactically valid, non-nil,
// non-max uuid is trusted back from the client. A tampered or missing
// cookie reads as "no cookie" (null), never as a thrown error.
export function readAnonymousId(value: string | undefined): string | null {
  if (!value) return null;
  if (!z.uuid().safeParse(value).success) return null;
  if (DEGENERATE_UUIDS.has(value)) return null;
  return value;
}

export function anonymousIdCookie(value: string, secure: boolean) {
  return {
    name: ANONYMOUS_ID_COOKIE,
    value,
    httpOnly: true,
    sameSite: "lax" as const,
    path: "/",
    maxAge: ONE_YEAR_SECONDS,
    secure,
  };
}

app/(products)/[app]/api/events/route.ts.content:
import "server-only";
import { NextResponse, type NextRequest } from "next/server";
import { track } from "@/lib/dal/events";
import { getProduct } from "@/lib/dal/products";
import { trackEventInputSchema } from "@/lib/schemas/inputs";
import { slugSchema } from "@/lib/schemas/product-config";
import { ANONYMOUS_ID_COOKIE, readAnonymousId } from "./anonymous-id";

// The public endpoint `<TrackVisit>` beacons to (docs/04-nextjs.md): a
// static landing cannot call `track()` itself, so this Route Handler does
// it on the visitor's behalf, for the `visit` type only — every other
// event type is written server-side, from a Server Action or Route
// Handler that already has a session or a debited generation
// (specs/TRACKING.md, docs/04-nextjs.md: "n'accepte que les types d'events
// publics").
const MAX_BODY_BYTES = 2048;

function reject(status: number): NextResponse {
  return new NextResponse(null, { status });
}

// Reads the body without ever buffering more than `limit` bytes (+ one
// pending chunk): a declared `Content-Length` over the cap rejects before
// the stream is touched at all; otherwise the stream is read chunk by
// chunk and cancelled — not drained — the moment the running total crosses
// the cap. `await request.text()` alone would buffer a chunked body with no
// Content-Length in full before the length check ever ran.
async function readBodyWithLimit(
  request: NextRequest,
  limit: number,
): Promise<{ ok: true; text: string } | { ok: false }> {
  const contentLength = request.headers.get("content-length");
  if (contentLength && Number(contentLength) > limit) return { ok: false };

  const body = request.body;
  if (!body) return { ok: true, text: "" };

  const reader = body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > limit) {
      await reader.cancel();
      return { ok: false };
    }
    chunks.push(value);
  }
  return { ok: true, text: Buffer.concat(chunks).toString("utf8") };
}

export async function POST(request: NextRequest, { params }: RouteContext<"/[app]/api/events">): Promise<NextResponse> {
  const bodyResult = await readBodyWithLimit(request, MAX_BODY_BYTES);
  if (!bodyResult.ok) return reject(413);
  const rawBody = bodyResult.text;

  // sendBeacon never sets an Origin header for a same-origin request in
  // most browsers; when it is present, it must match (docs/04-nextjs.md's
  // security note applied to a POST endpoint with no auth to lean on).
  const origin = request.headers.get("origin");
  if (origin && origin !== request.nextUrl.origin) return reject(403);

  const { app: slug } = await params;
  const slugResult = slugSchema.safeParse(slug);
  if (!slugResult.success) return reject(404);

  let json: unknown;
  try {
    json = JSON.parse(rawBody);
  } catch {
    return reject(400);
  }

  const parsed = trackEventInputSchema.safeParse(json);
  if (!parsed.success) return reject(400);

  // Only `visit` is accepted from the client (docs/04-nextjs.md); every
  // other type would let anyone fabricate funnel steps.
  if (parsed.data.type !== "visit") return reject(403);

  const product = await getProduct(slugResult.data);
  if (!product || product.status === "killed") return reject(404);

  // QA1-P1-B4: identity only ever comes from the cookie `proxy.ts` sets on
  // the first GET of a product page, never from the request body. Trusting
  // the body let two concurrent cookieless beacons (StrictMode's doubled
  // effect, or two tabs) each mint their own id and both reach track(),
  // writing two visitors for one visit. `parsed.data.anonymousId` is still
  // validated by the frozen schema above but is otherwise ignored here.
  const anonymousId = readAnonymousId(request.cookies.get(ANONYMOUS_ID_COOKIE)?.value);
  if (!anonymousId) return reject(204);

  await track({
    type: parsed.data.type,
    productId: product.id,
    userId: null,
    anonymousId,
    metadata: parsed.data.metadata,
  });

  return reject(204);
}

app/(products)/[app]/api/generate/route..content:
import "server-only";
import { randomUUID } from "node:crypto";
import { cookies, headers } from "next/headers";
import { after } from "next/server";
import { streamGeneration } from "@/lib/ai/generate";
import { debit, refund } from "@/lib/dal/credits";
import { track } from "@/lib/dal/events";
import {
  countPriorGenerations,
  deleteGeneration,
  findGenerationByKey,
  hashIp,
  markGenerationFailed,
  recordAnonymousGeneration,
  recordGeneration,
  saveGeneration,
} from "@/lib/dal/generations";
import { getProduct } from "@/lib/dal/products";
import { getSession } from "@/lib/dal/session";
// `clientIp` used to be a private byte-for-byte copy here (SECURITY plan,
// decision D4): lib/rate-limit.ts is now the single source, and its own
// comment carries the trust-model note (X-Forwarded-For only as trustworthy
// as whatever sits in front of Node).
import { clientIp } from "@/lib/rate-limit";
import { generateInputSchema } from "@/lib/schemas/inputs";
import { guardRequest } from "@/lib/security";
import { ANONYMOUS_ID_COOKIE, anonymousIdCookie, readAnonymousId } from "../events/anonymous-id";
import { toolInputSchema } from "../../tool/_lib/tool-input-schema";

export const maxDuration = 60;

function jsonError(error: string, status: number, extra?: Record<string, unknown>) {
  return Response.json({ error, ...extra }, { status });
}

// POST [app]/api/generate (SA-02): Zod-validated input → guardRequest →
// identity (session, or anonymous cookie + IP) → recordGeneration (pending)
// → debit → streamText (lib/ai/generate.ts), streamed to the client. Success
// finalizes the row and tracks events in after(); failure marks it failed
// and refunds (docs/05-ia.md's sequence diagram).
export async function POST(request: Request, { params }: RouteContext<"/[app]/api/generate">) {
  const { app: slug } = await params;
  const product = await getProduct(slug);
  if (!product || product.status === "killed") return jsonError("not_found", 404);

  // Bonus per docs/01 (image output), out of this spec's Périmètre: refuse
  // cleanly rather than silently mis-handling it as markdown.
  if (product.generation.outputType === "image") return jsonError("unsupported_output_type", 501);

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return jsonError("invalid_json", 400);
  }
  const parsedBody = generateInputSchema.safeParse(body);
  if (!parsedBody.success) return jsonError("invalid_input", 400);
  const { input, idempotencyKey } = parsedBody.data;

  const fields = toolInputSchema(product.inputs, input);
  if (!fields.success) return jsonError("invalid_input", 400, { fieldErrors: fields.fieldErrors });

  // A replayed key is rejected before any guard or write: it can only be a
  // retry of a request that already ran once.
  if (await findGenerationByKey(idempotencyKey)) return jsonError("duplicate_request", 409);

  const guard = await guardRequest("generate");
  if (!guard.ok) return jsonError(guard.reason, guard.reason === "bot" ? 403 : 429);

  const session = await getSession();
  const userId = session?.user.id ?? null;

  const requestHeaders = await headers();
  const ipHash = hashIp(clientIp(requestHeaders));

  const cookieStore = await cookies();
  // Shared with TRACKING (api/events): same cookie name and shape, so a
  // visit and a generation from the same visitor agree on one anonymous id.
  // Read even for a signed-in caller (QA1-P1-B5): the cookie set during
  // their earlier anonymous free generation is still in the browser, and
  // countPriorGenerations below needs it to see that prior row. It is
  // never assigned to `anonymousId` below, the variable tracked events
  // use: a signed-in generation always tracks with `anonymousId: null`.
  const existingAnonymousId = readAnonymousId(cookieStore.get(ANONYMOUS_ID_COOKIE)?.value);

  let generationId: string;
  let anonymousId: string | null = null;
  let freeGenerationsLeft: number | null = null;
  let isFirstGeneration: boolean;

  if (userId) {
    const priorCount = await countPriorGenerations({
      productId: product.id,
      userId,
      anonymousId: existingAnonymousId,
      ipHash: null,
    });
    isFirstGeneration = priorCount === 0;
    const recorded = await recordGeneration({
      productId: product.id,
      productVersion: product.version,
      userId,
      anonymousId: null,
      ipHash,
      input: fields.data,
      idempotencyKey,
    });
    generationId = recorded.id;
  } else {
    // recordAnonymousGeneration counts and inserts atomically (security
    // review, MEDIUM): the separate count-then-insert this route used to do
    // let concurrent requests all pass the "under the limit" check.
    anonymousId = existingAnonymousId ?? randomUUID();
    const recorded = await recordAnonymousGeneration({
      productId: product.id,
      productVersion: product.version,
      anonymousId,
      ipHash,
      input: fields.data,
      idempotencyKey,
      limit: product.pricing.anonymousFreeGenerations,
    });
    if (!recorded.ok) return jsonError("signup_required", 401);
    generationId = recorded.id;
    freeGenerationsLeft = recorded.freeGenerationsLeft;
    isFirstGeneration = recorded.isFirst;
  }

  if (userId) {
    const debitResult = await debit({
      userId,
      productId: product.id,
      cost: product.pricing.costPerGeneration,
      generationId,
      idempotencyKey,
    });
    if (!debitResult.ok) {
      // QA1-P1-B7: a refusal is not a generation (BO-04's activity must
      // list only served or genuinely failed-then-refunded attempts). The
      // row `recordGeneration` wrote above is still `pending` — never ran,
      // never refunded — so it is deleted, not marked failed.
      await deleteGeneration(generationId);
      after(() => track({ type: "credits_exhausted", productId: product.id, userId, anonymousId: null }));
      return jsonError("insufficient_balance", 402);
    }
    if ("replay" in debitResult) return jsonError("duplicate_request", 409);
  }

  try {
    const result = streamGeneration({
      product,
      inputs: fields.data,
      onSuccess: async (generationResult) => {
        await saveGeneration(generationId, generationResult);
        // Awaited inside the after() callback (silent-failure review,
        // MEDIUM): an un-awaited `void track(...)` returned undefined from
        // the callback, so after()'s waitUntil considered the task done
        // before the tracking write actually settled, and a rejection was
        // never reported anywhere.
        after(async () => {
          await track({
            type: "generation",
            productId: product.id,
            userId,
            anonymousId,
            metadata: { generationId },
          });
          if (isFirstGeneration) {
            await track({
              type: "first_generation",
              productId: product.id,
              userId,
              anonymousId,
              metadata: { generationId },
            });
          }
        });
      },
      onError: async (error) => {
        console.error(`[api/generate] generation ${generationId} failed`, error);
        await markGenerationFailed(generationId);
        if (userId) await refund(generationId);
      },
    });

    // Registered with after() (security review, HIGH), not just fired and
    // forgotten: after() extends the invocation's lifetime until this
    // promise settles, so onFinish/onError (and the save or the refund they
    // trigger) still run even if the client disconnects before the stream
    // ends — a bare `void result.consumeStream()` gave the platform no
    // signal to keep the invocation alive for that long. `Promise.resolve`
    // narrows `consumeStream()`'s `PromiseLike<void>` to the `Promise<void>`
    // `after()`'s `AfterTask` type requires.
    after(Promise.resolve(result.consumeStream()));

    const response = result.toUIMessageStreamResponse({
      onError: () => "generation_failed",
      headers: {
        "x-generation-id": generationId,
        ...(freeGenerationsLeft !== null ? { "x-free-generations-left": String(freeGenerationsLeft) } : {}),
      },
    });

    if (!userId && !existingAnonymousId && anonymousId) {
      const secure = new URL(request.url).protocol === "https:";
      cookieStore.set(anonymousIdCookie(anonymousId, secure));
    }

    return response;
  } catch (error) {
    // A synchronous failure before any byte streamed (e.g. model resolution):
    // the status code can still change, unlike an in-stream `error` part.
    console.error(`[api/generate] generation ${generationId} failed synchronously`, error);
    await markGenerationFailed(generationId);
    if (userId) await refund(generationId);
    return jsonError("generation_failed", 502, { refunded: Boolean(userId) });
  }
}

app/(products)/[app]/checkout/_actions.t.content:
"use server";

import { unstable_rethrow } from "next/navigation";
import { after } from "next/server";
import { purchase as purchaseCredits } from "@/lib/dal/credits";
import { track } from "@/lib/dal/events";
import { getProduct } from "@/lib/dal/products";
import { getSession } from "@/lib/dal/session";
import { slugSchema } from "@/lib/schemas/product-config";
import { purchaseInputSchema } from "@/lib/schemas/inputs";
import { guardRequest } from "@/lib/security";

// SA-05 (specs/SA-05-paiement.md): the checkout's only Server Action, called
// directly from CheckoutFlow (a plain async call, not a form action: there
// is no per-field validation state to carry, only a pack to buy). Order
// (plan's design decision 1): session → parse slug + purchaseInputSchema →
// guardRequest("purchase") → getProduct (killed counts as unknown) → pack
// checked against the config, before any write → ledger purchase() →
// after(track) → { ok: true, balance }; the router refresh is CheckoutFlow's,
// see QA1-P1-B3 (.claude/qa/reports/2026-09-25-full.md › B3): a server
// refresh() re-fetches the full /pricing page kept behind the checkout
// modal, which gets intercepted by @modal/(.)pricing and forces a hard
// reload (.claude/plans/QA1-P1-B3.plan.md, root cause).
export type PurchaseResult =
  | { ok: true; balance: number }
  | { ok: false; error: "unauthenticated" | "invalid_request" | "unknown_pack" | "bot" | "rate_limited" | "failed" };

export async function purchase(slug: string, packId: string, idempotencyKey: string): Promise<PurchaseResult> {
  const session = await getSession();
  if (!session) return { ok: false, error: "unauthenticated" };

  const parsedSlug = slugSchema.safeParse(slug);
  const parsedInput = purchaseInputSchema.safeParse({ packId, idempotencyKey });
  if (!parsedSlug.success || !parsedInput.success) return { ok: false, error: "invalid_request" };

  const guard = await guardRequest("purchase");
  if (!guard.ok) return { ok: false, error: guard.reason };

  const product = await getProduct(parsedSlug.data);
  if (!product || product.status === "killed") return { ok: false, error: "invalid_request" };

  const pack = product.pricing.packs.find((candidate) => candidate.id === parsedInput.data.packId);
  if (!pack) return { ok: false, error: "unknown_pack" };

  try {
    const result = await purchaseCredits({
      userId: session.user.id,
      productId: product.id,
      packId: pack.id,
      idempotencyKey: parsedInput.data.idempotencyKey,
    });

    // Registered with after() (docs/04-nextjs.md: events are written after
    // the response, never adding latency); a rejection is logged, never
    // thrown, so a TRACKING outage can't turn a successful purchase into an
    // error for the buyer (plan's design decision 1).
    after(async () => {
      try {
        await track({
          type: "purchase",
          productId: product.id,
          userId: session.user.id,
          anonymousId: null,
          metadata: {
            packId: pack.id,
            credits: pack.credits,
            amountCents: pack.priceCents,
            purchaseKey: parsedInput.data.idempotencyKey,
          },
        });
      } catch (error) {
        console.error("[checkout] purchase tracking failed", error);
      }
    });

    return { ok: true, balance: result.balance };
  } catch (error) {
    unstable_rethrow(error);
    console.error("[checkout] purchase failed", error);
    return { ok: false, error: "failed" };
  }
}

