import "server-only";
import { desc, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { magicLinkOutbox } from "@/lib/db/auth-schema";

// Frozen contract (specs/CONTRACT-types.md, orchestrator decision 1). SA-03
// has no `lib/dal` file in its own Périmètre but must show the simulated
// inbox (docs/08-stack.md: "Après « Recevoir mon lien », une modale « Boîte
// de réception (démo) » s'ouvre et affiche l'email"). Frozen here so
// CONTRACT-data can implement it and SA-03 can consume it.
//
// Called only by the signup Server Action (SA-03), right after
// `signInMagicLink` for that same email, in the same request. Admin and
// owner emails never have a row: SETUP's `sendMagicLink` writes the link
// to the database instead of sending it (docs/08), but only for regular
// users, so a demo visitor typing an admin email finds nothing here.
// Showing the link to whoever typed the email is the dossier's accepted
// demo design; the call is throttled by `guardRequest("signup")`.
export const getLatestMagicLink: (email: string) => Promise<{ url: string; createdAt: Date } | null> = async (
  email,
) => {
  const row = await db.query.magicLinkOutbox.findFirst({
    where: sql`lower(${magicLinkOutbox.email}) = lower(${email})`,
    orderBy: desc(magicLinkOutbox.createdAt),
  });
  return row ? { url: row.url, createdAt: row.createdAt } : null;
};

lib/dal/product-status.ts.content:
import "server-only";
import { eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { products } from "@/lib/db/schema";
import type { ProductStatus } from "@/lib/schemas/product-config";
import { requireAdmin } from "./session";

// specs/BO-06-statut.md: the real body, replacing the CONTRACT-types V1
// stub. No transition matrix (plan's orchestrator decision 2 — any status
// to any other, including the frozen contract's scale → scale call): the
// UI alone disables the current status. `requireAdmin` first, then a
// locking transaction so a concurrent edit never races the write: `select
// … for update`, a missing row throws.
export const updateStatus: (productId: string, status: ProductStatus, note: string | null) => Promise<void> = async (
  productId,
  status,
  note,
) => {
  await requireAdmin();
  await db.transaction(async (tx) => {
    const [row] = await tx.select().from(products).where(eq(products.id, productId)).for("update");
    if (!row) throw new Error(`updateStatus: product ${productId} not found`);

    await tx
      .update(products)
      .set({ status, statusNote: note, updatedAt: new Date() })
      .where(eq(products.id, productId));
  });
};

lib/dal/session.ts.content:
import "server-only";
import { io } from "next/cache";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { cache } from "react";
import { auth } from "@/lib/auth";

// Frozen contract (specs/SETUP-skeleton.md): signatures stay as-is for
// every spec built on top of the backoffice.
export type Session = typeof auth.$Infer.Session;

const ADMIN_ROLES = new Set(["admin", "owner"]);

// QA1-P1-B14 (.claude/plans/QA1-P1-B14.plan.md): auth.api.getSession() calls
// `new Date()` internally (Better Auth's own expiry check), which Cache
// Components flags as "unstable value new Date() while prerendering" even
// though headers() is already awaited first — the "postpone" signal from a
// Request-time API isn't guaranteed to unwind through arbitrary library
// code. `await io()` as the very first statement (node_modules/next/dist/docs/…
// /io.md) excludes everything after it from the static shell regardless,
// and resolves immediately outside prerendering (real requests, Server
// Actions, Route Handlers, Vitest), so no behaviour change for any caller.
export const getSession = cache(async (): Promise<Session | null> => {
  await io();
  const session = await auth.api.getSession({ headers: await headers() });
  return session ?? null;
});

export async function requireAdmin(): Promise<Session> {
  const session = await getSession();
  if (!session || !ADMIN_ROLES.has(session.user.role)) {
    redirect("/admin/login");
  }
  return session;
}

lib/db/auth-schema.ts.content:
// Better Auth tables, written by hand from the core schema of the installed
// version (node_modules/better-auth/.../db/get-tables + core/src/db/get-tables.ts,
// better-auth@1.7.6): table names plural, columns snake_case, matching the
// `drizzleAdapter(db, { provider: "pg", usePlural: true })` config in
// lib/auth.ts (docs/09-arborescence.md).
//
// `magic_link_outbox` is not a Better Auth table: it is where the simulated
// magic-link email (docs/08-stack.md) is stored instead of being sent.
//
// No `import "server-only"`: drizzle-kit and tsx import this module outside
// a request.
import { pgEnum, pgTable, text, timestamp, uuid, boolean } from "drizzle-orm/pg-core";

export const userRole = pgEnum("user_role", ["user", "admin", "owner"]);

export const users = pgTable("users", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  role: userRole("role").notNull().default("user"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const sessions = pgTable("sessions", {
  id: text("id").primaryKey(),
  expiresAt: timestamp("expires_at").notNull(),
  token: text("token").notNull().unique(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  ipAddress: text("ip_address"),
  userAgent: text("user_agent"),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
});

export const accounts = pgTable("accounts", {
  id: text("id").primaryKey(),
  accountId: text("account_id").notNull(),
  providerId: text("provider_id").notNull(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  idToken: text("id_token"),
  accessTokenExpiresAt: timestamp("access_token_expires_at"),
  refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
  scope: text("scope"),
  password: text("password"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const verifications = pgTable("verifications", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: timestamp("expires_at").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const magicLinkOutbox = pgTable("magic_link_outbox", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull(),
  url: text("url").notNull(),
  // Our own table (not a Better Auth one): house convention is timestamptz
  // (docs/07-modele-de-donnees.md), unlike the four Better Auth tables above.
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

lib/db/index.ts.content:
import "server-only";
import { AsyncLocalStorage } from "node:async_hooks";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { env } from "@/lib/env";
import * as authSchema from "./auth-schema";
import * as schema from "./schema";

// Explicit pool sizes (docs/10-tooling-dev.md: no `process.env` read in
// application code — `lib/env.ts` is the only place that does). The app
// pool is generous; the test pool is capped low on purpose: Vitest forks
// run one Postgres pool per test *file* (not one shared process across the
// whole run), so the widest real concurrency inside a single file is 5 (the
// `Promise.all` x 5 lock tests in lib/dal/generations.test.ts and
// lib/dal/credits.test.ts). castflow's own pool was raised from 5 to 10
// because ~74 files shared ONE `bun test` process without `--isolate`; that
// scale never applies here, so we keep the lower number.
export const APP_POOL_MAX = 10;
export const TEST_POOL_MAX = 5;

export function poolMaxFor(nodeEnv: typeof env.NODE_ENV): number {
  return nodeEnv === "test" ? TEST_POOL_MAX : APP_POOL_MAX;
}

const createDb = () =>
  drizzle(postgres(env.DATABASE_URL, { max: poolMaxFor(env.NODE_ENV) }), {
    schema: { ...schema, ...authSchema },
  });

// Module-level singletons, cached on `globalThis` (outside production) so
// that both Next.js's dev server (re-evaluates modules on every edit) and
// Vitest's `vi.resetModules()` (used across lib/dal/*.test.ts to re-import a
// DAL module after mocking one of its dependencies) reuse the same pool and
// the same transaction storage, instead of opening a fresh one each time.
type BaseDb = ReturnType<typeof createDb>;
type Tx = Parameters<Parameters<BaseDb["transaction"]>[0]>[0];
export type TestTxScope = { tx: Tx; open: boolean };

const globalForDb = globalThis as unknown as {
  msbDb?: BaseDb;
  msbTestTxStorage?: AsyncLocalStorage<TestTxScope>;
};

export const baseDb: BaseDb = globalForDb.msbDb ?? createDb();
if (env.NODE_ENV !== "production") globalForDb.msbDb = baseDb;

export const testTxStorage: AsyncLocalStorage<TestTxScope> =
  globalForDb.msbTestTxStorage ?? new AsyncLocalStorage<TestTxScope>();
if (env.NODE_ENV !== "production") globalForDb.msbTestTxStorage = testTxStorage;

// Outside `withTestTransaction` (no open scope): the base instance, exactly
// today's behaviour. Inside one: the transaction `withTestTransaction`
// opened. `lib/db/test-transaction.ts` is the only other reader of
// `testTxStorage`/`baseDb`; nothing else should import them.
function currentTarget(): BaseDb {
  const scope = testTxStorage.getStore();
  if (!scope) return baseDb;
  if (!scope.open) {
    throw new Error("db used after withTestTransaction ended (floating promise?)");
  }
  return scope.tx as unknown as BaseDb;
}

// A Proxy so `db` keeps the exact static type of the base Drizzle instance
// (no DAL signature or call site changes) while every access — property
// reads, `in`, assignment, `Object.defineProperty` (what `vi.spyOn` uses),
// `delete`, `Object.getOwnPropertyDescriptor`, `Object.getPrototypeOf` — is
// resolved against whichever instance is current *at the time of the
// call*, not once at import time.
function createRoutingDb(): BaseDb {
  return new Proxy({} as BaseDb, {
    get(_target, prop) {
      const target = currentTarget();
      const value = Reflect.get(target as object, prop, target);
      return typeof value === "function" ? value.bind(target) : value;
    },
    has(_target, prop) {
      return Reflect.has(currentTarget() as object, prop);
    },
    set(_target, prop, value) {
      return Reflect.set(currentTarget() as object, prop, value);
    },
    defineProperty(_target, prop, descriptor) {
      return Reflect.defineProperty(currentTarget() as object, prop, descriptor);
    },
    deleteProperty(_target, prop) {
      return Reflect.deleteProperty(currentTarget() as object, prop);
    },
    // Without this trap the Proxy's own prototype stays that of its literal
    // `{}` target: `db instanceof PgDatabase` and drizzle-orm's `is(db, …)`
    // both return false, and any method that lives on the prototype
    // (instead of an own property) resolves through *this* — routed —
    // prototype, so a `vi.spyOn` placed on the real class's prototype still
    // takes effect through `db`.
    getPrototypeOf() {
      return Reflect.getPrototypeOf(currentTarget() as object);
    },
    getOwnPropertyDescriptor(_target, prop) {
      const target = currentTarget();
      const descriptor = Reflect.getOwnPropertyDescriptor(target as object, prop);
      // `db` swaps targets over time, but a Proxy must keep reporting
      // non-configurable for any *own* property that was already
      // non-configurable on a *previous* target it reported through this
      // same trap — an invariant the engine enforces regardless of the
      // `getPrototypeOf` trap above. Forcing every own data property
      // configurable sidesteps that invariant; methods themselves live on
      // the prototype (routed by `getPrototypeOf`, not by this trap) and
      // are what `vi.spyOn(db, "someMethod")` actually patches.
      return descriptor ? { ...descriptor, configurable: true } : descriptor;
    },
  });
}

// In production and development, `db` is `baseDb` itself: identical to the
// pre-TOOLING-test-transaction behaviour. Only under test does it route
// through the AsyncLocalStorage scope.
export const db: BaseDb = env.NODE_ENV === "test" ? createRoutingDb() : baseDb;

lib/db/schema.ts.content:
// Business tables (docs/07-modele-de-donnees.md): the full catalogue
// (themes, products, product_versions, decision_thresholds) and usage
// (credit_transactions, balances, generations, purchases, events) blocks.
// `users` is Better Auth's table, extended with `role` (auth-schema.ts):
// that makes 10 business tables in total.
//
// No `import "server-only"` here: drizzle-kit and tsx (scripts/seed.ts,
// drizzle.config.ts) import this module directly, outside a request.
//
// Relative imports only: drizzle-kit does not resolve the `@/*` alias.
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { eventTypeSchema, type EventType } from "../schemas/event-type";
import { productStatusSchema, type ProductStatus } from "../schemas/product-config";
import type { ProductConfig } from "../schemas/product-config";
import { landingVariantSchema, type LandingVariant } from "../schemas/theme-tokens";
import type { ThemeTokens } from "../schemas/theme-tokens";
import { users } from "./auth-schema";

// Enums are built from the Zod schemas' `.options` (specs/CONTRACT-data
// plan › Frozen inputs) so the database and the shared Zod schemas cannot
// drift apart. `.options` is a plain (runtime) array; the cast below only
// restores the literal tuple type pgEnum expects, from the very type the
// Zod schema already carries.
export const productStatus = pgEnum(
  "product_status",
  productStatusSchema.options as unknown as [ProductStatus, ...ProductStatus[]],
);
export const landingVariant = pgEnum(
  "landing_variant",
  landingVariantSchema.options as unknown as [LandingVariant, ...LandingVariant[]],
);
export const eventType = pgEnum("event_type", eventTypeSchema.options as unknown as [EventType, ...EventType[]]);

// Not driven by a Zod schema (docs/07 names these two enums directly, no
// shared input schema references them).
export const creditReason = pgEnum("credit_reason", ["signup_bonus", "purchase", "generation", "refund"]);
export const generationStatus = pgEnum("generation_status", ["pending", "succeeded", "failed"]);

const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

export const themes = pgTable("themes", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  tokens: jsonb("tokens").$type<ThemeTokens>().notNull(),
  landingVariant: landingVariant("landing_variant").notNull(),
  isSeed: boolean("is_seed").notNull().default(false),
  updatedAt: timestamptz("updated_at").notNull().defaultNow(),
});

// `current_version` deliberately has no FK to `product_versions`: inserting
// a product and its first version would otherwise be a circular reference.
// The composite FK lives on `generations` instead (docs/07's invariant "Une
// génération pointe vers une config qui existe").
export const products = pgTable(
  "products",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull().unique(),
    status: productStatus("status").notNull().default("test"),
    themeId: uuid("theme_id")
      .notNull()
      .references(() => themes.id),
    currentVersion: integer("current_version").notNull(),
    locale: text("locale").notNull(),
    isSeed: boolean("is_seed").notNull().default(false),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    statusNote: text("status_note"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (table) => [
    check("products_slug_format", sql`${table.slug} ~ '^[a-z0-9]+(-[a-z0-9]+)*$'`),
    check("products_current_version_positive", sql`${table.currentVersion} >= 1`),
    check("products_locale_valid", sql`${table.locale} IN ('fr', 'en')`),
  ],
);

export const productVersions = pgTable(
  "product_versions",
  {
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    version: integer("version").notNull(),
    config: jsonb("config").$type<ProductConfig>().notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [
    primaryKey({ columns: [table.productId, table.version] }),
    check("product_versions_version_positive", sql`${table.version} >= 1`),
  ],
);

export const generations = pgTable(
  "generations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    productVersion: integer("product_version").notNull(),
    userId: text("user_id").references(() => users.id),
    anonymousId: text("anonymous_id"),
    ipHash: text("ip_hash").notNull(),
    input: jsonb("input").notNull(),
    output: jsonb("output"),
    model: text("model"),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    cachedInputTokens: integer("cached_input_tokens"),
    costMicros: integer("cost_micros"),
    status: generationStatus("status").notNull().default("pending"),
    idempotencyKey: text("idempotency_key").notNull().unique(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [
    foreignKey({
      name: "generations_product_version_fk",
      columns: [table.productId, table.productVersion],
      foreignColumns: [productVersions.productId, productVersions.version],
    }),
    index("generations_user_id_created_at_idx").on(table.userId, table.createdAt),
    index("generations_ip_hash_created_at_idx").on(table.ipHash, table.createdAt),
    index("generations_product_id_created_at_idx").on(table.productId, table.createdAt),
  ],
);

export const purchases = pgTable(
  "purchases",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    packId: text("pack_id").notNull(),
    credits: integer("credits").notNull(),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("EUR"),
    idempotencyKey: text("idempotency_key").notNull().unique(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [
    check("purchases_credits_positive", sql`${table.credits} > 0`),
    check("purchases_amount_cents_positive", sql`${table.amountCents} > 0`),
  ],
);

export const creditTransactions = pgTable(
  "credit_transactions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    delta: integer("delta").notNull(),
    reason: creditReason("reason").notNull(),
    generationId: uuid("generation_id").references(() => generations.id),
    purchaseId: uuid("purchase_id").references(() => purchases.id),
    idempotencyKey: text("idempotency_key").notNull().unique(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [
    check("credit_transactions_delta_nonzero", sql`${table.delta} <> 0`),
    index("credit_transactions_user_id_product_id_created_at_idx").on(table.userId, table.productId, table.createdAt),
  ],
);

export const balances = pgTable(
  "balances",
  {
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    balance: integer("balance").notNull().default(0),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.productId] }),
    check("balances_balance_nonnegative", sql`${table.balance} >= 0`),
  ],
);

export const events = pgTable(
  "events",
  {
    id: bigint("id", { mode: "number" }).primaryKey().generatedAlwaysAsIdentity(),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    type: eventType("type").notNull(),
    // No FK (docs/07): anonymous events carry no user row to reference.
    userId: text("user_id"),
    anonymousId: text("anonymous_id"),
    metadata: jsonb("metadata"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [index("events_product_id_type_created_at_idx").on(table.productId, table.type, table.createdAt)],
);

// A row with a null `product_id` carries the studio default; a row with a
// product carries its override. `nullsNotDistinct` makes the default row
// unique too (docs/07: "il n'existe qu'un réglage par défaut").
export const decisionThresholds = pgTable(
  "decision_thresholds",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    productId: uuid("product_id").references(() => products.id),
    minVisits: integer("min_visits"),
    killMaxConversion: numeric("kill_max_conversion", { precision: 5, scale: 4, mode: "number" }),
    scaleMinConversion: numeric("scale_min_conversion", { precision: 5, scale: 4, mode: "number" }),
    scaleRequiresPositiveMargin: boolean("scale_requires_positive_margin"),
    isSeed: boolean("is_seed").notNull().default(false),
    updatedBy: text("updated_by").references(() => users.id),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (table) => [
    unique("decision_thresholds_product_id_key").on(table.productId).nullsNotDistinct(),
    check("decision_thresholds_min_visits_positive", sql`${table.minVisits} IS NULL OR ${table.minVisits} > 0`),
    check(
      "decision_thresholds_kill_max_conversion_range",
      sql`${table.killMaxConversion} IS NULL OR (${table.killMaxConversion} >= 0 AND ${table.killMaxConversion} <= 1)`,
    ),
    check(
      "decision_thresholds_scale_min_conversion_range",
      sql`${table.scaleMinConversion} IS NULL OR (${table.scaleMinConversion} >= 0 AND ${table.scaleMinConversion} <= 1)`,
    ),
    check(
      "decision_thresholds_kill_lt_scale",
      sql`${table.killMaxConversion} IS NULL OR ${table.scaleMinConversion} IS NULL OR ${table.killMaxConversion} < ${table.scaleMinConversion}`,
    ),
    check(
      "decision_thresholds_default_row_complete",
      sql`${table.productId} IS NOT NULL OR (
        ${table.minVisits} IS NOT NULL AND
        ${table.killMaxConversion} IS NOT NULL AND
        ${table.scaleMinConversion} IS NOT NULL AND
        ${table.scaleRequiresPositiveMargin} IS NOT NULL
      )`,
    ),
  ],
);

lib/db/test-transaction.ts.content:
import "server-only";
import { TransactionRollbackError } from "drizzle-orm";
import { baseDb, testTxStorage, type TestTxScope } from "./index";

// Never drizzle-orm's own `TransactionRollbackError`: `db.transaction()`
// catches instances of that exact class specially — it issues a ROLLBACK
// and *resolves* the promise instead of rejecting it, treating the error as
// "the caller wants to cancel this transaction, quietly" (`tx.rollback()`).
// Sharing that class for our own always-rollback would make a real
// `tx.rollback()` escaping from `fn` indistinguishable from ours: both
// would resolve silently, hiding a bug in the code under test. A private
// sentinel keeps the two apart.
class TestRollback extends Error {}

// Wraps a TransactionRollbackError thrown by `fn` itself so it never
// reaches `baseDb.transaction()` as that exact class — see TestRollback
// above for why an unwrapped one would be swallowed the same way.
class EscapedTransactionRollback extends Error {
  constructor(public readonly original: unknown) {
    super("a TransactionRollbackError escaped from withTestTransaction's fn");
  }
}

/**
 * Runs `fn` inside a Postgres transaction opened on the base db instance,
 * always rolled back once `fn` settles — whether it resolves or rejects —
 * so nothing it writes survives. While `fn` runs, `db` (lib/db/index.ts)
 * routes every call into this same transaction: no DAL signature changes,
 * and a nested `db.transaction()` becomes a savepoint
 * (drizzle-orm/postgres-js).
 *
 * Not reentrant: calling it again from inside `fn` throws. Not for tests
 * that prove real concurrent access from several distinct connections
 * (`Promise.all` over independent `db.transaction()` calls) — postgres.js
 * never releases a savepoint, and concurrent savepoints on one connection
 * are unsafe, so those tests keep opening their own, separate transactions
 * (docs/07-modele-de-donnees.md's ledger concurrency tests, unchanged by
 * this spec).
 */
export async function withTestTransaction(fn: () => Promise<void>): Promise<void> {
  if (testTxStorage.getStore()) {
    throw new Error("withTestTransaction cannot be nested");
  }

  try {
    await baseDb.transaction(async (tx) => {
      const scope: TestTxScope = { tx, open: true };
      try {
        await testTxStorage.run(scope, fn);
      } catch (error) {
        scope.open = false;
        throw error instanceof TransactionRollbackError ? new EscapedTransactionRollback(error) : error;
      }
      scope.open = false;
      throw new TestRollback();
    });
  } catch (error) {
    if (error instanceof TestRollback) return;
    if (error instanceof EscapedTransactionRollback) throw error.original;
    throw error;
  }
}

lib/env.ts.content:
// Validated environment variables, imported by `next.config.ts`: the build
// fails if any of the 8 variables is missing or invalid. Application code
// reads `env.*`, never `process.env` directly (docs/10-tooling-dev.md).
//
// No `import "server-only"` here: `next.config.ts` (which runs outside a
// request) imports this module too.
import { createEnv } from "@t3-oss/env-nextjs";
import { z } from "zod";

export const createAppEnv = (source: Record<string, string | undefined>) =>
  createEnv({
    server: {
      DATABASE_URL: z.url(),
      BETTER_AUTH_SECRET: z.string().min(32),
      BETTER_AUTH_URL: z.url(),
      AI_MODE: z.enum(["mock", "live"]),
      DEMO_MODE: z.enum(["true", "false"]).transform((value) => value === "true"),
      AI_GATEWAY_API_KEY: z.string().min(1),
      BLOB_READ_WRITE_TOKEN: z.string().min(1),
      CRON_SECRET: z.string().min(1),
      // SECURITY (specs/SECURITY.md): the Postgres generation rate limit, N
      // generations per 60 s per user and per ip_hash. Optional: most local
      // and preview setups never set it.
      GENERATION_RATE_LIMIT_PER_MINUTE: z.coerce.number().int().positive().default(10),
      // SECURITY follow-up: Vercel sets this to "1" automatically at build
      // time and at runtime; absent everywhere else. lib/security.ts reads
      // it to tell a real Vercel deployment from a local `next start` (or
      // any other non-Vercel host), since it must never branch on
      // `process.env` directly.
      VERCEL: z.string().optional(),
      // TOOLING-test-transaction: read once here instead of `process.env`
      // scattered in application code. `lib/db/index.ts` uses it to pick the
      // Postgres pool size and to decide whether `db` routes through the
      // per-test transaction; Vitest sets `NODE_ENV=test` itself (see
      // `.env.test` and `vitest.config.mts`, both untouched by this spec).
      NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
    },
    runtimeEnv: source,
    emptyStringAsUndefined: true,
  });

export const env = createAppEnv(process.env);

lib/rate-limit.ts.content:
import "server-only";
import { env } from "@/lib/env";
import { countRecentGenerations } from "@/lib/dal/generations";

// The single source of client IP resolution (SECURITY plan, decision D4),
// imported by api/generate/route.ts (orchestrator follow-up: it used to keep
// its own byte-for-byte copy, proven identical by a parity test in
// rate-limit.test.ts) and by lib/security.ts.
//
// Trust model (security review, SA-02): `X-Forwarded-For` is only as
// trustworthy as whatever sits in front of Node. On Vercel, the edge
// network sets/overwrites this header itself, so a client cannot spoof it.
// Self-hosting (docs/06-vercel.md's Fly.io alternative) must have its own
// reverse proxy strip any inbound `X-Forwarded-For` before appending the
// real peer address — left to SECURITY's deployment hardening.
export function clientIp(requestHeaders: Headers): string {
  const forwardedFor = requestHeaders.get("x-forwarded-for");
  if (forwardedFor) {
    const [first] = forwardedFor.split(",");
    if (first?.trim()) return first.trim();
  }
  return requestHeaders.get("x-real-ip") ?? "unknown";
}

export type RateLimitIdentity = { userId: string | null; ipHash: string };

// Postgres rate limit (specs/SECURITY.md): N generations per 60 s, per
// signed-in user and per ip_hash, N from lib/env.ts. Limited when either
// count reaches N (decision D2). `countRecentGenerations` already counts
// with a `>` window boundary on the database clock; the `>=` here (decision
// D3) means the guard, called before `recordGeneration`, refuses the
// (N+1)th request first — the Nth still gets through.
//
// Accepted race (security/DB review, LOW note 2): this is a plain
// count-then-insert, not serialized by a lock like
// `recordAnonymousGeneration`'s advisory lock. A burst of concurrent
// `generate` requests can each read the same "under the limit" count
// before any of their rows is written, so the limit can be exceeded
// briefly under real concurrency. Bounded, not a correctness bug: credits
// are still debited atomically (lib/dal/credits.ts's `debit`), so nobody
// generates for free, and the AI Gateway's own budget cap is the backstop
// against a determined burst.
export async function isGenerationRateLimited({ userId, ipHash }: RateLimitIdentity): Promise<boolean> {
  const { byUser, byIp } = await countRecentGenerations({ userId, ipHash, windowSeconds: 60 });
  const limit = env.GENERATION_RATE_LIMIT_PER_MINUTE;
  return (userId !== null && byUser >= limit) || byIp >= limit;
}

lib/require-database-url.ts.content:
// Small helper reused by everything that builds its own Postgres client
// outside lib/env.ts's full validation (drizzle.config.ts, scripts/seed.ts,
// and the DB integration tests): a single readable error instead of a bare
// `process.env.DATABASE_URL!` non-null assertion scattered across files.
//
// No `import "server-only"`: drizzle-kit and tsx import this module too.
export const requireDatabaseUrl = (source: Record<string, string | undefined> = process.env): string => {
  const value = source.DATABASE_URL;
  if (!value) {
    throw new Error(
      "DATABASE_URL is not set. Run `pnpm tsx scripts/worktree-db.ts ensure --seed` to create and migrate this worktree's database.",
    );
  }
  return value;
};

