lib/security.ts.content:
import "server-only";
import { checkBotId } from "botid/server";
import { headers } from "next/headers";
import { hashIp } from "@/lib/dal/generations";
import { getSession } from "@/lib/dal/session";
import { env } from "@/lib/env";
import { clientIp, isGenerationRateLimited } from "@/lib/rate-limit";

// Frozen contract (specs/CONTRACT-types.md): the request guard used by
// generation, signup and purchase, plus the "test the prompt" backoffice
// button (docs/04-nextjs.md, docs/06-vercel.md). V1 stub: "laisse tout
// passer" (docs/11's contract table), replaced here by SECURITY's real
// BotID (`checkBotId()`) and Postgres rate limit. Kinds: SA-02 `generate`,
// SA-03 `signup`, SA-05 `purchase`, BO-05's "Tester le prompt`
// `test-prompt`.
export type GuardKind = "generate" | "signup" | "purchase" | "test-prompt";

export type GuardResult = { ok: true } | { ok: false; reason: "bot" | "rate_limited" };

// No try/catch here (SECURITY plan, decision D5): a rejection from
// checkBotId or from the rate limiter's DAL call propagates as-is — neither
// fail-open (silently letting the request through) nor fail-closed
// (masking the real error as a guard rejection).
//
// BotID is enforced only on Vercel (env.VERCEL === "1", set automatically
// by the platform at build time and at runtime — never read from
// `process.env` directly here). Off Vercel — including a fully local
// `next build && next start` — checkBotId()'s real path requires a
// VERCEL_OIDC_TOKEN that only exists on an actual Vercel deployment, so it
// throws instead of classifying anything; forcing its own dev bypass there
// (`developmentOptions.isDevelopment: true`) makes it always return
// "human" instead. This fails open *only* for BotID, and only where BotID
// cannot work at all: the Postgres rate limit below still applies
// everywhere, on Vercel or not.
export const guardRequest: (kind: GuardKind) => Promise<GuardResult> = async (kind) => {
  const bot = await checkBotId({ developmentOptions: { isDevelopment: env.VERCEL !== "1" } });
  if (bot.isBot) return { ok: false, reason: "bot" };

  // Only `generate` is rate-limited (SECURITY plan, decision D1): the cost
  // that justifies a Postgres rate limit is the AI call it precedes.
  if (kind !== "generate") return { ok: true };

  const session = await getSession();
  const userId = session?.user.id ?? null;
  const ipHash = hashIp(clientIp(await headers()));
  const limited = await isGenerationRateLimited({ userId, ipHash });
  if (limited) return { ok: false, reason: "rate_limited" };

  return { ok: true };
};

next.config.ts.content:
import type { NextConfig } from "next";
import createNextIntlPlugin from "next-intl/plugin";
import { withBotId } from "botid/next/config";
// Fails the build (and this import) if any of the 8 required variables is
// missing or invalid (docs/10-tooling-dev.md).
import "./lib/env";

// next-intl without i18n routing (docs/08-stack.md): i18n/request.ts reads
// the locale from the product config via next/root-params, not a URL
// segment.
const withNextIntl = createNextIntlPlugin("./i18n/request.ts");

const nextConfig: NextConfig = {
  cacheComponents: true, // 'use cache', PPR, dynamic by default
  partialPrefetching: true, // one prefetched shell per route, reused across links
  reactCompiler: true, // automatic memoization
  typedRoutes: true, // typed links and redirects
  typescript: {
    // tsconfig.json (protected, docs/10-tooling-dev.md) sets `baseUrl`,
    // deprecated as of TypeScript 6/7 (TS5101). tsconfig.build.json adds
    // `ignoreDeprecations: "6.0"`, the fix the tsc error message itself
    // suggests, without touching the protected file. IDEs still read
    // tsconfig.json directly and may show the same diagnostic.
    tsconfigPath: "tsconfig.build.json",
  },
};

// withBotId adds the rewrites and headers BotID's client challenge needs
// (docs/06-vercel.md); it must wrap the innermost config so next-intl's own
// plugin composition sees the result (SECURITY plan, task 9).
export default withNextIntl(withBotId(nextConfig));

proxy.ts.content:
import { randomUUID } from "node:crypto";
import { getSessionCookie } from "better-auth/cookies";
import { NextResponse, type NextRequest } from "next/server";
import {
  ANONYMOUS_ID_COOKIE,
  anonymousIdCookie,
  readAnonymousId,
} from "./app/(products)/[app]/api/events/anonymous-id";

const ADMIN_LOGIN_PATH = "/admin/login";
const OPS_PATH = "/admin/ops";

// A minimal French 404, never the framework's own English fallback and
// never mentioning ops/owner (specs/qa/QA1-P1-B12-statut-http.md): a real
// HTTP 404, not a 200 body carrying NEXT_HTTP_ERROR_FALLBACK (this route
// would otherwise leave under the implicit Suspense of
// app/(backoffice)/admin/loading.tsx before the page's own notFound() call
// resolves — docs/04-nextjs.md's streaming HTTP contract).
const NOT_FOUND_HTML = `<!doctype html>
<html lang="fr">
  <head>
    <meta charset="utf-8" />
    <meta name="robots" content="noindex" />
    <title>Page introuvable</title>
  </head>
  <body>
    <h1>Page introuvable</h1>
  </body>
</html>
`;

function notFoundResponse(): NextResponse {
  return new NextResponse(NOT_FOUND_HTML, {
    status: 404,
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

// QA1-P1-B12: an optimistic session guard for the backoffice, cookie
// presence only — never a DB query, never the role (docs/04-nextjs.md: no
// authorization in the proxy). It only turns a response that used to leave
// with HTTP 200 (NEXT_REDIRECT / NEXT_HTTP_ERROR_FALLBACK in the streamed
// body, see the QA1-P1-B12 plan's root cause) into the real status before
// any byte of the page is produced. The actual check stays `requireAdmin()`
// in the DAL: a stale or forged cookie passes here and is still caught
// there (plan's risk R6) — this function never imports `@/lib/auth` or
// `@/lib/dal`.
function adminSessionGuard(request: NextRequest): NextResponse | undefined {
  const { pathname } = request.nextUrl;
  if (pathname === ADMIN_LOGIN_PATH) return undefined;

  const hasSessionCookie = getSessionCookie(request) !== null;
  if (hasSessionCookie) return undefined;

  const isOps = pathname === OPS_PATH || pathname.startsWith(`${OPS_PATH}/`);
  if (isOps) return notFoundResponse();

  return NextResponse.redirect(new URL(ADMIN_LOGIN_PATH, request.url));
}

// QA1-P1-B4: mints the visitor's `anonymous_id` cookie on the first GET of
// a product page, before any beacon leaves the browser. Closes the race
// <TrackVisit>'s two concurrent cookieless beacons used to hit (docs/07's
// per-day dedupe only works once every beacon of a visit agrees on one,
// server-issued id). No DB access, no authorization here — docs/04-nextjs.md
// describes `proxy.ts` as the subdomain rewrite, the optimistic admin
// session guard above (QA1-P1-B12), and this cookie, all within that same
// description (docs/04 › Routing / the tree).
export function proxy(request: NextRequest): NextResponse {
  if (request.nextUrl.pathname.startsWith("/admin")) {
    return adminSessionGuard(request) ?? NextResponse.next();
  }

  const response = NextResponse.next();
  if (request.method !== "GET") return response;

  const existing = readAnonymousId(request.cookies.get(ANONYMOUS_ID_COOKIE)?.value);
  if (existing) return response;

  const secure = request.nextUrl.protocol === "https:";
  response.cookies.set(anonymousIdCookie(randomUUID(), secure));
  return response;
}

// Runs on product pages (`[app]` and its sub-pages, never `/api/*`, static
// assets, or a product's own `[app]/api/*` routes — a Set-Cookie on the
// beacon's own response would reopen the race the anonymous-id logic above
// exists to close) and, since QA1-P1-B12, on `/admin` and its sub-routes
// for adminSessionGuard. `/` alone (no slug) never matches either: there is
// no route there.
export const config = {
  matcher: ["/((?!_next/|api/|admin(?:/|$)|[^/]+/api/|.*\\.[^/]+$).+)", "/admin", "/admin/:path*"],
};

scripts/reset-demo.ts.content:
// specs/DEMO-mode.md: wipes every visitor-created row (products, their
// versions and threshold overrides) and every usage row (generations,
// purchases, the credit ledger, balances, events, and the end-user
// accounts they belong to), then replays the seeded catalogue and its 30
// days of usage (scripts/seed.ts's applySeed). Like scripts/seed.ts, this
// script builds its own Postgres client from `DATABASE_URL` alone: no
// `import "server-only"`, no `lib/env.ts` (which requires all 8
// variables) — app/(backoffice)/admin/ops/_actions.ts imports this file
// directly (an accepted exception, docs/09 flags a raw `lib/db` import
// outside `lib/dal/`, but a Server Action calling a script that owns its
// own connection is not that).
//
// Usage: pnpm tsx scripts/reset-demo.ts (called by the /admin/ops button)
import { realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";
// Namespace import: see the comment in drizzle.config.ts.
import * as nextEnvNs from "@next/env";

const { loadEnvConfig } = (nextEnvNs as { default?: typeof nextEnvNs }).default ?? nextEnvNs;
import { eq, inArray, sql } from "drizzle-orm";
import postgres from "postgres";
import { users } from "../lib/db/auth-schema";
import {
  balances,
  creditTransactions,
  decisionThresholds,
  events,
  generations,
  productVersions,
  products,
  purchases,
} from "../lib/db/schema";
import { requireDatabaseUrl } from "../lib/require-database-url";
import { applySeed, createSeedDb, type SeedTx } from "./seed";

// A Postgres advisory lock, held for the whole transaction
// (`pg_advisory_xact_lock`, auto-released at commit or rollback): a reset
// and a concurrent seed (or two concurrent resets — the button posts once,
// but a retried request must not race itself) always serialize instead of
// interleaving their deletes and inserts.
const RESET_LOCK_KEY = sql`hashtext('reset-demo')`;

// Deletes every visitor-created product (its versions and threshold
// override) and every usage row (docs/07's usage block: generations,
// purchases, the ledger, balances, events) along with the end-user
// accounts they belong to (role `user`; admin and owner keep their role
// and survive). Usage carries no `is_seed` column of its own, so a full
// wipe followed by applySeed's fresh, deterministic replay is the only
// way to guarantee the reset story matches the seed exactly — a partial
// wipe would leave stray visitor activity mixed into a seeded product's
// metrics. Exported so scripts/reset-demo.test.ts can assert on it
// directly, one statement at a time, on the isolated database it creates.
export async function applyReset(tx: SeedTx, now: Date): Promise<void> {
  await tx.execute(sql`select pg_advisory_xact_lock(${RESET_LOCK_KEY})`);

  // Usage first (children before the users they reference).
  await tx.delete(creditTransactions);
  await tx.delete(purchases);
  await tx.delete(generations);
  await tx.delete(balances);
  await tx.delete(events);
  await tx.delete(users).where(eq(users.role, "user"));

  // Visitor-created products (children before the product itself).
  const visitorProducts = await tx.select({ id: products.id }).from(products).where(eq(products.isSeed, false));
  const visitorProductIds = visitorProducts.map((row) => row.id);
  if (visitorProductIds.length > 0) {
    await tx.delete(decisionThresholds).where(inArray(decisionThresholds.productId, visitorProductIds));
    await tx.delete(productVersions).where(inArray(productVersions.productId, visitorProductIds));
    await tx.delete(products).where(inArray(products.id, visitorProductIds));
  }

  // Replays the seeded catalogue (idempotent upserts: themes, the 3 seeded
  // products, the default thresholds, admin/owner) and fresh usage.
  await applySeed(tx, now);
}

export async function resetDemo(opts: { sql?: postgres.Sql; now?: Date } = {}): Promise<void> {
  const ownsSql = !opts.sql;
  const sqlClient = opts.sql ?? postgres(requireDatabaseUrl(), { max: 1, connect_timeout: 5, onnotice: () => {} });
  const db = createSeedDb(sqlClient);
  try {
    await db.transaction(async (tx) => {
      await applyReset(tx, opts.now ?? new Date());
    });
    console.log("Reset complete: visitor products and usage wiped, seeded catalogue and usage replayed.");
  } finally {
    if (ownsSql) await sqlClient.end({ timeout: 5 });
  }
}

// Only run when executed directly (mirrors scripts/seed.ts), so tests can
// import resetDemo() without triggering it.
const isEntry = (): boolean => {
  try {
    return !!process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
};
if (isEntry()) {
  // Only loaded for the CLI, same reasoning as scripts/seed.ts's own
  // isEntry() block (orchestrator decision 4): Vitest and the Next.js
  // server bundle both load their own env already.
  loadEnvConfig(process.cwd());
  resetDemo()
    .then(() => process.exit(0))
    .catch((err: unknown) => {
      console.error(err instanceof Error ? err.message : err);
      process.exit(1);
    });
}

scripts/seed-if-empty.ts.content:
// Guards the automatic seed step in scripts/vercel-build.sh: idempotent by
// design, the same way drizzle-kit's own migration tracking makes it safe to
// run `pnpm db:migrate` on every deploy (docs/06-vercel.md). Seeds a fresh
// database exactly once — deploys after that see products already there and
// skip, so the demo's usage data is never reset by a routine deploy. Unlike
// scripts/seed.ts, never called directly by a developer who wants to refresh
// fixtures; that's still plain `pnpm db:seed`.
import { realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";
import * as nextEnvNs from "@next/env";
import postgres from "postgres";
import { requireDatabaseUrl } from "../lib/require-database-url";
import { seed } from "./seed";

const { loadEnvConfig } = (nextEnvNs as { default?: typeof nextEnvNs }).default ?? nextEnvNs;

export async function seedIfEmpty(): Promise<void> {
  const sql = postgres(requireDatabaseUrl(), { max: 1, connect_timeout: 5, onnotice: () => {} });
  let productCount: number;
  try {
    const [row] = await sql<{ count: number }[]>`SELECT count(*)::int AS count FROM products`;
    productCount = row!.count;
  } finally {
    await sql.end({ timeout: 5 });
  }

  if (productCount > 0) {
    console.log(`seed-if-empty: ${productCount} product(s) already in the database, skipping seed.`);
    return;
  }

  await seed();
}

const isEntry = (): boolean => {
  try {
    return !!process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
};
if (isEntry()) {
  loadEnvConfig(process.cwd());
  seedIfEmpty()
    .then(() => process.exit(0))
    .catch((err: unknown) => {
      console.error(err instanceof Error ? err.message : err);
      process.exit(1);
    });
}

