  publishProduct,
  saveVersion,
} from "@/lib/dal/product-editor";
import { requireAdmin } from "@/lib/dal/session";
import { env } from "@/lib/env";
import { guardRequest } from "@/lib/security";
import { generateInputSchema } from "@/lib/schemas/inputs";
import { productConfigSchema, slugSchema, templateVariables } from "@/lib/schemas/product-config";
import { detectImageType, IMAGE_EXTENSIONS, type DetectedImageType } from "./_components/product-form/image-signature";
import { MODEL_CATALOGUE_VALUES } from "./_components/product-form/model-catalogue";
import { issuesToErrors, stepOfPath } from "./_components/product-form/validation";

// BO-05a (specs/BO-05a-formulaire.md): one Server Action per domain
// (CLAUDE.md), used by both `/admin/products/new` (slug === null) and
// `/admin/products/[slug]/edit` (bound slug, `.bind(null, slug)` from the
// page). The form posts the already-cleaned config (product-form's
// `toConfig`) as a single JSON field: one shared schema, validated again
// here since a Server Action is a public POST endpoint (CLAUDE.md).
export type SaveProductState = {
  ok?: boolean;
  slug?: string;
  version?: number;
  errors?: Record<string, string>;
  step?: number;
  formError?: string;
};

const MAX_LOGO_BYTES = 512 * 1024;
const ALLOWED_LOGO_TYPES = new Set<DetectedImageType>(["image/png", "image/jpeg", "image/webp"]);

// Drizzle wraps the driver's own error instead of exposing `.code` on it
// directly: the real Postgres error (and its `code`) lives on `.cause`
// (lib/db/schema.test.ts's `expectViolation`). A plain `{ code: "23505" }`
// (e.g. a hand-built test double) is still accepted, so this also covers a
// driver that one day stops wrapping.
function isUniqueSlugViolation(err: unknown): boolean {
  if (typeof err !== "object" || err === null) return false;
  const cause = "cause" in err ? (err as { cause?: unknown }).cause : undefined;
  const code =
    typeof cause === "object" && cause !== null && "code" in cause
      ? (cause as { code?: unknown }).code
      : (err as { code?: unknown }).code;
  return code === "23505";
}

// Shared by every action below that reads the form's "config" hidden field
// (product-form.tsx): unreadable JSON is a form-level error, not a
// validation issue on a specific field.
function parseConfigForm(formData: FormData): { ok: true; candidate: unknown } | { ok: false; formError: string } {
  try {
    return { ok: true, candidate: JSON.parse(String(formData.get("config") ?? "")) };
  } catch {
    return { ok: false, formError: "Configuration illisible" };
  }
}

// Security review (LOW): `generation.model`'s frozen schema only checks
// `z.string().min(1)` (lib/schemas/product-config.ts), so `testPrompt` and
// `publish` — both public POST endpoints — enforce the picker's own
// catalogue (model-catalogue.ts) themselves. The one exception is the
// model already stored on the product being edited: the picker shows it
// too (generation-step.tsx's modelOptions()), so a draft that hasn't
// touched step 5 yet must still be re-testable/re-publishable.
async function isAllowedModel(model: string, slug: string | null): Promise<boolean> {
  if (MODEL_CATALOGUE_VALUES.includes(model)) return true;
  if (slug === null) return false;
  const draft = await getProductDraft(slug);
  return draft?.config.generation.model === model;
}

export async function saveProduct(
  slug: string | null,
  _prevState: SaveProductState,
  formData: FormData,
): Promise<SaveProductState> {
  await requireAdmin();

  const parsedForm = parseConfigForm(formData);
  if (!parsedForm.ok) return { formError: parsedForm.formError };
  const candidate = parsedForm.candidate;

  const parsed = productConfigSchema.safeParse(candidate);
  if (!parsed.success) {
    const step = Math.min(...parsed.error.issues.map((issue) => stepOfPath(issue.path)));
    return { errors: issuesToErrors(parsed.error.issues), step };
  }
  const config = parsed.data;

  const themeOptions = await listThemeOptions();
  if (!themeOptions.some((theme) => theme.id === config.themeId)) {
    return { errors: { themeId: "Thème introuvable" }, step: 2 };
  }

  try {
    if (slug === null) {
      if (!(await isSlugAvailable(config.slug))) {
        return { errors: { slug: "Ce slug est déjà utilisé" }, step: 1 };
      }
      const result = await createProduct(config);
      updateTag("products");
      updateTag(`product:${result.slug}`);
      return { ok: true, slug: result.slug, version: result.version };
    }

    if (!slugSchema.safeParse(slug).success) {
      return { formError: "Slug invalide" };
    }
    const result = await saveVersion(slug, config);
    if (!result) return { formError: "Produit introuvable" };
    return { ok: true, slug: result.slug, version: result.version };
  } catch (err) {
    unstable_rethrow(err);
    if (isUniqueSlugViolation(err)) {
      return { errors: { slug: "Ce slug est déjà utilisé" }, step: 1 };
    }
    console.error("[admin/products] saveProduct failed", err);
    throw err;
  }
}

// BO-05 step 1's live slug check, called on blur/typing from the client
// (docs/02-ecrans.md).
export async function checkSlug(candidate: string): Promise<{ available: boolean; error?: string }> {
  await requireAdmin();
  const parsed = slugSchema.safeParse(candidate);
  if (!parsed.success) {
    const reserved = parsed.error.issues.some((issue) => issue.message === "slug is reserved");
    return { available: false, error: reserved ? "Ce slug est réservé" : "Format de slug invalide" };
  }
  const available = await isSlugAvailable(parsed.data);
  return { available, error: available ? undefined : "Ce slug est déjà utilisé" };
}

// BO-05 step 2's logo upload (docs/06-vercel.md › Blob).
export async function uploadLogo(
  _prevState: { url?: string; error?: string },
  formData: FormData,
): Promise<{ url?: string; error?: string }> {
  await requireAdmin();

  const file = formData.get("file");
  if (!(file instanceof File) || file.size === 0) {
    return { error: "Aucun fichier reçu" };
  }
  if (file.size > MAX_LOGO_BYTES) {
    return { error: "Le logo dépasse 512 Ko" };
  }

  // Never trust the client-declared `file.type` (any file can be labelled
  // `image/png`): the real format is read from the file's own magic bytes.
  const bytes = new Uint8Array(await file.arrayBuffer());
  const detectedType = detectImageType(bytes);
  if (!detectedType || !ALLOWED_LOGO_TYPES.has(detectedType)) {
    return { error: "Formats acceptés : PNG, JPEG, WebP" };
  }

  try {
    // Never use the client-supplied file name for the blob pathname
    // either: a random name with the detected type's own extension.
    const pathname = `logos/${randomUUID()}.${IMAGE_EXTENSIONS[detectedType]}`;
    const blob = await put(pathname, file, {
      access: "public",
      addRandomSuffix: true,
      contentType: detectedType,
      token: env.BLOB_READ_WRITE_TOKEN,
    });
    return { url: blob.url };
  } catch (err) {
    console.error("[admin/products] uploadLogo failed", err);
    return { error: "Échec de l'envoi du logo" };
  }
}

export type TestPromptState = {
  ok?: boolean;
  output?: string;
  inputTokens?: number;
  outputTokens?: number;
  costMicros?: number;
  error?: string;
};

// The form waits for streamGeneration's callbacks rather than for
// `consumeStream()` alone (see below): this bounds that wait so a stuck
// mock or a misbehaving provider still returns to the admin.
const TEST_PROMPT_TIMEOUT_MS = 20_000;

// BO-05 step 5's « Tester le prompt » (docs/02-ecrans.md): a generation
// run from the backoffice, without touching credits or `generations`
// (docs/05-ia.md's `testPrompt` row: "Appel IA sans débit"). Reads the
// same "config" field as `saveProduct`/`publish`, but only needs its
// `inputs` and `generation` parts to be valid — the rest of the draft can
// still have errors on other steps.
export async function testPrompt(
  slug: string | null,
  _prevState: TestPromptState,
  formData: FormData,
): Promise<TestPromptState> {
  await requireAdmin();

  const guard = await guardRequest("test-prompt");
  if (!guard.ok) {
    return { error: "Trop de tests pour le moment, réessayez dans un instant." };
  }

  const parsedForm = parseConfigForm(formData);
  if (!parsedForm.ok) return { error: parsedForm.formError };
  const candidate = parsedForm.candidate as { inputs?: unknown; generation?: unknown };

  const inputsResult = productConfigSchema.shape.inputs.safeParse(candidate.inputs);
  if (!inputsResult.success) return { error: "Les champs de l'outil sont invalides" };
  const generationResult = productConfigSchema.shape.generation.safeParse(candidate.generation);
  if (!generationResult.success) return { error: "La configuration de génération est invalide" };
  const inputs = inputsResult.data;
  const generation = generationResult.data;

  if (!(await isAllowedModel(generation.model, slug))) {
    return { error: "Modèle non autorisé" };
  }

  const fieldKeys = new Set(inputs.map((field) => field.key));
  for (const variable of templateVariables(generation.promptTemplate)) {
    if (!fieldKeys.has(variable)) {
      return { error: `Variable {{${variable}}} sans champ correspondant` };
    }
  }

  // Bonus per docs/01 (image output), out of this spec's Périmètre (plan's
  // orchestrator decision 5): shown disabled in the picker, refused here
  // too rather than silently mis-handled as markdown.
  if (generation.outputType === "image") {
    return { error: "La sortie image n'est pas encore disponible" };
  }

  let sampleCandidate: unknown;
  try {
    sampleCandidate = JSON.parse(String(formData.get("sample") ?? "{}"));
  } catch {
    return { error: "Échantillon illisible" };
  }
  const sampleResult = generateInputSchema.shape.input.safeParse(sampleCandidate);
  if (!sampleResult.success) return { error: "Échantillon invalide" };

  const fields = toolInputSchema(inputs, sampleResult.data);
  if (!fields.success) return { error: "Complétez les champs obligatoires de l'échantillon" };

  // `resolveModel` (lib/ai/model.ts) picks a mock fixture by slug in
  // AI_MODE=mock; a brand-new product (create mode, no slug yet) falls
  // back to the same default fixture as an unknown slug.
  const effectiveSlug = slug ?? "test-prompt-draft";

  let settle!: (state: TestPromptState) => void;
  const settled = new Promise<TestPromptState>((resolvePromise) => {
    settle = resolvePromise;
  });

  const result = streamGeneration({
    product: { slug: effectiveSlug, generation },
    inputs: fields.data,
    onSuccess: (generationResult) => {
      settle({
        ok: true,
        output:
          typeof generationResult.output === "string"
            ? generationResult.output
            : JSON.stringify(generationResult.output),
        inputTokens: generationResult.inputTokens,
        outputTokens: generationResult.outputTokens,
        costMicros: generationResult.costMicros,
      });
    },
    onError: (error) => {
      console.error("[admin/products] testPrompt failed", error);
      settle({ error: "La génération de test a échoué" });
    },
  });

  // Registered with after() in the real generation route (api/generate);
  // here the action itself is the caller waiting on it, so it is awaited
  // directly instead.
  await result.consumeStream();

  const timeout = new Promise<TestPromptState>((resolveTimeout) => {
    setTimeout(() => resolveTimeout({ error: "La génération de test a échoué" }), TEST_PROMPT_TIMEOUT_MS);
  });

  return Promise.race([settled, timeout]);
}

// docs/05-ia.md's reference usage for BO-05 step 6's estimated margin,
// before any real test has run (the plan's orchestrator decision 2):
// ~1000 input / ~500 output tokens, the order of magnitude of the demo's
// text generations (docs/05: "1 000 / 600" for the largest example).
const REFERENCE_USAGE: GenerationUsage = { inputTokens: 1000, outputTokens: 500, cachedInputTokens: 0 };

// BO-05 step 6's margin panel, before "Tester le prompt" has run: no AI
// call, just the reference usage priced at the chosen model's rate
// (lib/ai/generate.ts's `costMicros`, which already prices an unrecognized
// model at the highest known rate rather than under-billing it).
export async function estimateGenerationCost(model: string): Promise<{ costMicros: number }> {
  await requireAdmin();
  return { costMicros: costMicros(model, REFERENCE_USAGE) };
}

export type PublishState = {
  ok?: boolean;
  slug?: string;
  version?: number;
  url?: string;
  errors?: Record<string, string>;
  step?: number;
  formError?: string;
};

// BO-05 step 7's « Publier » (docs/02-ecrans.md): "what you see goes live"
// (the plan's orchestrator decision 1) — saves the current form as a new
// version, then publishes that very version, in create mode as well as
// edit mode (a create-mode publish never requires a prior "Enregistrer").
// Same full-config validation as `saveProduct` (a product only goes live
// once every step is valid), plus `publishProduct`'s cache-visible move of
// `current_version`.
export async function publish(
  slug: string | null,
  _prevState: PublishState,
  formData: FormData,
): Promise<PublishState> {
  await requireAdmin();

  const parsedForm = parseConfigForm(formData);
  if (!parsedForm.ok) return { formError: parsedForm.formError };

  const parsed = productConfigSchema.safeParse(parsedForm.candidate);
  if (!parsed.success) {
    const step = Math.min(...parsed.error.issues.map((issue) => stepOfPath(issue.path)));
    return { errors: issuesToErrors(parsed.error.issues), step };
  }
  const config = parsed.data;

  const themeOptions = await listThemeOptions();
  if (!themeOptions.some((theme) => theme.id === config.themeId)) {
    return { errors: { themeId: "Thème introuvable" }, step: 2 };
  }

  if (!(await isAllowedModel(config.generation.model, slug))) {
    return { errors: { "generation.model": "Modèle non autorisé" }, step: 5 };
  }

  try {
    let publishedSlug: string;
    let publishedVersion: number;

    if (slug === null) {
      if (!(await isSlugAvailable(config.slug))) {
        return { errors: { slug: "Ce slug est déjà utilisé" }, step: 1 };
      }
      const created = await createProduct(config);
      const published = await publishProduct(created.slug, created.version);
      if (!published) {
        // createProduct just returned this very (id, version): publishProduct
        // not finding it would be a database inconsistency, not a normal
        // "not found" the admin can act on.
        throw new Error(
          `publish: publishProduct(${created.slug}, ${created.version}) returned null right after createProduct`,
        );
      }
      publishedSlug = published.slug;
      publishedVersion = published.version;
    } else {
      if (!slugSchema.safeParse(slug).success) {
        return { formError: "Slug invalide" };
      }
      const saved = await saveVersion(slug, config);
      if (!saved) return { formError: "Produit introuvable" };
      const published = await publishProduct(slug, saved.version);
      if (!published) {
        throw new Error(`publish: publishProduct(${slug}, ${saved.version}) returned null right after saveVersion`);
      }
      publishedSlug = published.slug;
      publishedVersion = published.version;
    }

    updateTag("products");
    updateTag(`product:${publishedSlug}`);
    return { ok: true, slug: publishedSlug, version: publishedVersion, url: `/${publishedSlug}` };
  } catch (err) {
    unstable_rethrow(err);
    if (isUniqueSlugViolation(err)) {
      return { errors: { slug: "Ce slug est déjà utilisé" }, step: 1 };
    }
    console.error("[admin/products] publish failed", err);
    throw err;
  }
}

app/(backoffice)/admin/products/_compone.content:
"use client";

import { MAX_INPUTS } from "@/lib/schemas/product-config";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { moveItem, type FieldDraft } from "./form-values";

const MIN_INPUTS = 1;
const FIELD_TYPES: FieldDraft["type"][] = ["text", "textarea", "select"];
const TYPE_LABELS: Record<FieldDraft["type"], string> = { text: "Texte", textarea: "Zone de texte", select: "Liste" };

// BO-05 step 4 (docs/02-ecrans.md): the outil's own mini form-builder, one
// row per field, reordered by up/down buttons.
export function FieldsStep({
  fields,
  errors,
  onChange,
}: {
  fields: FieldDraft[];
  errors: Record<string, string>;
  onChange: (fields: FieldDraft[]) => void;
}) {
  function updateField(index: number, patch: Partial<FieldDraft>) {
    onChange(fields.map((field, i) => (i === index ? { ...field, ...patch } : field)));
  }

  function addField() {
    const key = `champ_${fields.length + 1}`;
    onChange([
      ...fields,
      { id: crypto.randomUUID(), key, label: `Champ ${fields.length + 1}`, type: "text", required: false },
    ]);
  }

  function removeField(index: number) {
    onChange(fields.filter((_field, i) => i !== index));
  }

  return (
    <div className="grid gap-3">
      {fields.map((field, index) => (
        <div key={field.id} className="grid gap-2 rounded-md border p-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="grid gap-1.5">
              <Label htmlFor={`field-key-${field.id}`}>Clé</Label>
              <Input
                id={`field-key-${field.id}`}
                value={field.key}
                onChange={(event) => updateField(index, { key: event.target.value })}
                aria-invalid={errors[`inputs.${index}.key`] ? "true" : undefined}
              />
              {errors[`inputs.${index}.key`] ? (
                <p className="text-sm text-destructive">{errors[`inputs.${index}.key`]}</p>
              ) : null}
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor={`field-label-${field.id}`}>Libellé</Label>
              <Input
                id={`field-label-${field.id}`}
                value={field.label}
                onChange={(event) => updateField(index, { label: event.target.value })}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <div className="grid gap-1.5">
              <Label htmlFor={`field-type-${field.id}`}>Type</Label>
              <select
                id={`field-type-${field.id}`}
                className="h-9 rounded-md border border-input bg-transparent px-3 text-sm"
                value={field.type}
                onChange={(event) => updateField(index, { type: event.target.value as FieldDraft["type"] })}
              >
                {FIELD_TYPES.map((type) => (
                  <option key={type} value={type}>
                    {TYPE_LABELS[type]}
                  </option>
                ))}
              </select>
            </div>
            <label className="flex items-end gap-2 pb-1.5 text-sm">
              <input
                type="checkbox"
                checked={field.required}
                onChange={(event) => updateField(index, { required: event.target.checked })}
              />
              Requis
            </label>
          </div>

          {field.type === "select" ? (
            <div className="grid gap-1.5">
              <Label htmlFor={`field-options-${field.id}`}>Options (une par ligne)</Label>
              <Textarea
                id={`field-options-${field.id}`}
                value={(field.options ?? []).join("\n")}
                onChange={(event) => updateField(index, { options: event.target.value.split("\n") })}
                aria-invalid={errors[`inputs.${index}.options`] ? "true" : undefined}
              />
              {errors[`inputs.${index}.options`] ? (
                <p className="text-sm text-destructive">{errors[`inputs.${index}.options`]}</p>
              ) : null}
            </div>
          ) : null}

          <div className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={index === 0}
              onClick={() => onChange(moveItem(fields, index, "up"))}
            >
              Monter
            </Button>
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={index === fields.length - 1}
              onClick={() => onChange(moveItem(fields, index, "down"))}
            >
              Descendre
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={fields.length <= MIN_INPUTS}
              onClick={() => removeField(index)}
            >
              Supprimer ce champ
            </Button>
          </div>
        </div>
      ))}

      <Button type="button" variant="outline" disabled={fields.length >= MAX_INPUTS} onClick={addField}>
        Ajouter un champ
      </Button>
    </div>
  );
}

import type { ProductConfig } from "@/lib/schemas/product-config";

// The starting point for BO-05 steps 5 and 6 (GenerationStep, PricingStep)
// on a brand-new product: sensible defaults the admin edits from there.
// Also what a step-4 draft save falls back to before steps 5-6 have been
// touched at all, so the config stays valid end to end.
export const DEFAULT_GENERATION: ProductConfig["generation"] = {
  model: "anthropic/claude-haiku-4.5",
  promptTemplate: "Rédige une réponse claire et utile à partir des informations fournies.",
  outputType: "markdown",
};

export const DEFAULT_PRICING: ProductConfig["pricing"] = {
  freeCreditsOnSignup: 3,
  anonymousFreeGenerations: 1,
  costPerGeneration: 1,
  packs: [
    { id: "pack-10", credits: 10, priceCents: 490 },
    { id: "pack-50", credits: 50, priceCents: 1490, recommended: true },
  ],
};

// A field of step 4, with a client-only `id` for stable React keys: an
// input's `key` can change while the admin edits it (or briefly collide
// while typing), so the row's identity in the list cannot rely on it.
// `toConfig` strips this id back out before validation and save.
export type FieldDraft = ProductConfig["inputs"][number] & { id: string };

// A "how it works" step of step 3, same reasoning as `FieldDraft`: reordered
// rows (`moveItem`) cannot use their array index as a React key, and the
// step has no other stable identifier of its own. `toConfig` strips this id
// back out before validation and save (review QA1-P1-M1, MEDIUM #1).
export type LandingStepDraft = NonNullable<ProductConfig["landing"]["steps"]>[number] & { id: string };

export type LandingDraft = Omit<ProductConfig["landing"], "steps"> & { steps?: LandingStepDraft[] };

export type ProductDraft = Omit<ProductConfig, "inputs" | "landing"> & { inputs: FieldDraft[]; landing: LandingDraft };

// The in-progress form state for a brand-new product (BO-05's "new"
// route). An edited product's draft comes from `getProductDraft` instead,
// mapped the same way (a client-only id added to each input row).
export function newProductDraft(themeId: string): ProductDraft {
  return {
    slug: "",
    name: "",
    status: "test",
    themeId,
    locale: "fr",
    branding: {},
    landing: { headline: "", subheadline: "", faq: [], seoTitle: "", seoDescription: "" },
    inputs: [{ id: crypto.randomUUID(), key: "champ_1", label: "Champ 1", type: "text", required: true }],
    generation: DEFAULT_GENERATION,
    pricing: DEFAULT_PRICING,
  };
}

// The inverse of `toConfig`, for a config that already validated (import
// panel, QA1-P1-M1): adds a fresh client-only `id` per input row (needed by
// FieldsStep's `key`-based list) and per "how it works" step (LandingStep's
// list, same reasoning), everything else passes through unchanged.
export function fromConfig(config: ProductConfig): ProductDraft {
  return {
    ...config,
    inputs: config.inputs.map((input) => ({ ...input, id: crypto.randomUUID() })),
    landing: {
      ...config.landing,
      steps: config.landing.steps?.map((step) => ({ ...step, id: crypto.randomUUID() })),
    },
  };
}

function cleanBranding(branding: ProductConfig["branding"]): ProductConfig["branding"] {
  const cleaned: ProductConfig["branding"] = {};
  if (branding.logoUrl?.trim()) cleaned.logoUrl = branding.logoUrl.trim();
  if (branding.primaryColor?.trim()) cleaned.primaryColor = branding.primaryColor.trim();
  return cleaned;
}

function cleanField(field: FieldDraft): ProductConfig["inputs"][number] {
  const { id: _id, options, label, key, ...rest } = field;
  const cleanedOptions =
    field.type === "select" ? options?.map((option) => option.trim()).filter((option) => option.length > 0) : undefined;
  return {
    ...rest,
    key: key.trim(),
    label: label.trim(),
    ...(cleanedOptions ? { options: cleanedOptions } : {}),
  };
}

// Converts the form's draft into the shape `productConfigSchema` validates
// and the DAL stores: strips the client-only ids, trims text values, and
// drops values the schema would otherwise reject (an empty branding
// override, options on a non-select field, blank option lines). Never
// mutates its argument.
export function toConfig(draft: ProductDraft): ProductConfig {
  return {
    ...draft,
    name: draft.name.trim(),
    branding: cleanBranding(draft.branding),
    landing: {
      ...draft.landing,
      headline: draft.landing.headline.trim(),
      subheadline: draft.landing.subheadline.trim(),
      seoTitle: draft.landing.seoTitle.trim(),
      seoDescription: draft.landing.seoDescription.trim(),
      steps: draft.landing.steps?.map(({ id: _id, ...rest }) => rest),
    },
    inputs: draft.inputs.map(cleanField),
  };
}

// BO-05's up/down reordering (docs/02-ecrans.md): swaps an item with its
// neighbour, a no-op at either edge, always returning a new array.
export function moveItem<T>(items: T[], index: number, direction: "up" | "down"): T[] {
  const target = direction === "up" ? index - 1 : index + 1;
  if (target < 0 || target >= items.length) return items;
  const next = [...items];
  const [item] = next.splice(index, 1);
  // `index` itself may be out of range (e.g. beyond the array's length)
  // even when `target` lands in bounds: splice(index, 1) then removes
  // nothing and `item` is undefined. Splicing it back in would grow the
  // array with a hole instead of leaving it untouched.
  if (item === undefined) return items;
  next.splice(target, 0, item);
  return next;
}

"use client";

import { useRef } from "react";
import type { ProductConfig } from "@/lib/schemas/product-config";
import { templateVariables } from "@/lib/schemas/product-config";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/components/utils";
import { MODEL_CATALOGUE } from "./model-catalogue";
import { insertVariable } from "./prompt-variables";

export type GenerationPatch = Partial<ProductConfig["generation"]>;

type Generation = ProductConfig["generation"];

// The plan's orchestrator decision 8: a stored model that is neither Haiku
// nor Sonnet (MODEL_CATALOGUE) is kept as a third option, rather than
// silently replaced — and `_actions.ts` accepts that same stored model
// server-side (security review, LOW).
function modelOptions(current: string) {
  if (MODEL_CATALOGUE.some((option) => option.value === current)) return MODEL_CATALOGUE;
  return [...MODEL_CATALOGUE, { value: current, label: current }];
}

// BO-05 step 5 (docs/02-ecrans.md): model, prompt template with clickable
// {{variables}}, output type. The unknown-variable check runs live on every
// render (not only after a save), on top of whatever the server/step
// validation already reported in `errors`.
export function GenerationStep({
  generation,
  inputs,
  errors,
  onChange,
}: {
  generation: Generation;
  // B-N2 (.claude/qa/reports/2026-09-25-full-3.md): a step-4 field's `key`
  // can transiently duplicate another one's while the admin is editing it
  // ("Clé déjà utilisée" blocks the step, but the {{variable}} chip list
  // below still renders meanwhile) — the client-only `id` (FieldDraft.id,
  // form-values.ts) is used as the React key instead, since it never
  // collides.
  inputs: { id: string; key: string }[];
  errors: Record<string, string>;
  onChange: (patch: GenerationPatch) => void;
}) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const fieldKeys = new Set(inputs.map((input) => input.key));
  const unknownVariables = templateVariables(generation.promptTemplate).filter((variable) => !fieldKeys.has(variable));
  const liveError = unknownVariables[0] ? `Variable {{${unknownVariables[0]}}} sans champ correspondant` : undefined;
  const templateError = errors["generation.promptTemplate"] ?? liveError;

  function insertChip(key: string) {
    const textarea = textareaRef.current;
    const start = textarea?.selectionStart ?? generation.promptTemplate.length;
    const end = textarea?.selectionEnd ?? generation.promptTemplate.length;
    const { value } = insertVariable(generation.promptTemplate, start, end, key);
    onChange({ promptTemplate: value });
  }

  return (
    <div className="grid gap-4">
      <div className="grid gap-1.5">
        <Label htmlFor="generation-system-prompt">Prompt système</Label>
        <Textarea
          id="generation-system-prompt"
          rows={3}
          value={generation.systemPrompt ?? ""}
          onChange={(event) => onChange({ systemPrompt: event.target.value })}
        />
      </div>

      <div className="grid gap-1.5">
        <Label htmlFor="generation-model">Modèle</Label>
        <select
          id="generation-model"
          className="h-9 rounded-md border border-input bg-transparent px-3 text-sm"
          value={generation.model}
          onChange={(event) => onChange({ model: event.target.value })}
        >
          {modelOptions(generation.model).map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      </div>

      <div className="grid gap-1.5">
        <Label htmlFor="generation-prompt-template">Template de prompt</Label>
        {inputs.length > 0 ? (
          <div className="flex flex-wrap gap-1.5">
            {inputs.map((input) => (
              <button
                key={input.id}
                type="button"
                className="rounded-full border px-2 py-0.5 text-xs hover:bg-muted"
                onClick={() => insertChip(input.key)}
              >
                {`{{${input.key}}}`}
              </button>
            ))}
          </div>
        ) : null}
        <Textarea
          id="generation-prompt-template"
          ref={textareaRef}
          rows={4}
          value={generation.promptTemplate}
          onChange={(event) => onChange({ promptTemplate: event.target.value })}
          aria-invalid={templateError ? "true" : undefined}
        />
        {templateError ? <p className="text-sm text-destructive">{templateError}</p> : null}
      </div>

      <div className="grid gap-1.5">
        <span className="text-sm font-medium">Type de sortie</span>
        <div role="radiogroup" aria-label="Type de sortie" className="flex gap-3">
          <button
            type="button"
            role="radio"
            aria-checked={generation.outputType === "markdown"}
            onClick={() => onChange({ outputType: "markdown" })}
            className={cn(
              "rounded-md border px-3 py-1.5 text-sm",
              generation.outputType === "markdown" ? "border-primary bg-accent" : "hover:bg-muted",
            )}
          >
            Markdown
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={false}
            disabled
            title="Bientôt disponible"
            className="cursor-not-allowed rounded-md border px-3 py-1.5 text-sm opacity-50"
          >
            Image (bientôt)
          </button>
        </div>
      </div>
    </div>
  );
}

