import "server-only";
import { and, asc, eq, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { productVersions, products, themes } from "@/lib/db/schema";
import { productConfigSchema, type ProductConfig } from "@/lib/schemas/product-config";
import { themeTokensSchema } from "@/lib/schemas/theme-tokens";
import { requireAdmin } from "./session";
import type { Theme } from "./themes";

// BO-05a (specs/BO-05a-formulaire.md): the real product-editor DAL. Its
// exports are additive next to `createProduct` (plan's orchestrator
// decision 2): the signature and return shape of `createProduct` stay
// byte-identical to the CONTRACT-data stub (pinned by
// lib/dal/contract.test.ts and contract-shape.test.ts), only its body now
// validates the config before writing.
export const createProduct: (config: ProductConfig) => Promise<{ id: string; slug: string; version: number }> = async (
  config,
) => {
  const session = await requireAdmin();
  const parsed = productConfigSchema.parse(config);
  return db.transaction(async (tx) => {
    const [product] = await tx
      .insert(products)
      .values({
        slug: parsed.slug,
        status: parsed.status,
        themeId: parsed.themeId,
        currentVersion: 1,
        locale: parsed.locale,
        createdBy: session.user.id,
      })
      .returning({ id: products.id, slug: products.slug });
    await tx
      .insert(productVersions)
      .values({ productId: product!.id, version: 1, config: parsed, createdBy: session.user.id });
    return { id: product!.id, slug: product!.slug, version: 1 };
  });
};

// BO-05: a step-4 draft save, never a mutation in place
// (docs/07-modele-de-donnees.md › product_versions: "jamais de modification
// en place"). It never touches `products.current_version`: publishing (a
// separate action, BO-05b) is what moves the published version forward.
// The row is locked with `SELECT … FOR UPDATE` so two concurrent saves on
// the same product get distinct version numbers instead of racing on
// `coalesce(max(version), 0) + 1`.
export async function saveVersion(
  slug: string,
  config: ProductConfig,
): Promise<{ id: string; slug: string; version: number } | null> {
  const session = await requireAdmin();
  const parsed = productConfigSchema.parse(config);
  return db.transaction(async (tx) => {
    const [row] = await tx.select().from(products).where(eq(products.slug, slug)).for("update");
    if (!row) return null;

    const [nextVersionRow] = await tx
      .select({ next: sql<number>`coalesce(max(${productVersions.version}), 0) + 1` })
      .from(productVersions)
      .where(eq(productVersions.productId, row.id));
    const version = Number(nextVersionRow!.next);

    // The catalogue row wins over the submitted config for the fields it
    // also owns (docs/07): a draft save never lets the client change slug
    // or status behind the row's back (both stay read-only in the BO-05
    // form for an existing product, but the DAL is the real guarantee).
    await tx.insert(productVersions).values({
      productId: row.id,
      version,
      config: { ...parsed, slug: row.slug, status: row.status },
      createdBy: session.user.id,
    });
    return { id: row.id, slug: row.slug, version };
  });
}

// BO-05b (specs/BO-05b-generation-publication.md): publishes an existing
// version — "what you see goes live" (the plan's orchestrator decision 1).
// Additive next to `saveVersion`: draft saves never move `current_version`
// (docs/07-modele-de-donnees.md), only this does. `themeId` and `locale`
// are synced from the published version's own config, since the product
// row (not just `product_versions`) also carries them (docs/07 › `products`
// table). Any existing version can be republished, including an earlier
// one (a rollback), since `product_versions` is append-only.
export async function publishProduct(
  slug: string,
  version: number,
): Promise<{ id: string; slug: string; version: number } | null> {
  await requireAdmin();
  return db.transaction(async (tx) => {
    const [row] = await tx.select().from(products).where(eq(products.slug, slug)).for("update");
    if (!row) return null;

    const versionRow = await tx.query.productVersions.findFirst({
      where: and(eq(productVersions.productId, row.id), eq(productVersions.version, version)),
    });
    if (!versionRow) return null;

    const config = productConfigSchema.parse(versionRow.config);
    await tx
      .update(products)
      .set({ currentVersion: version, themeId: config.themeId, locale: config.locale, updatedAt: new Date() })
      .where(eq(products.id, row.id));

    return { id: row.id, slug: row.slug, version };
  });
}

// BO-05's edit page: the latest draft (which may be ahead of the published
// version), next to the product's published version and lock state.
export async function getProductDraft(slug: string): Promise<{
  productId: string;
  isSeed: boolean;
  version: number;
  publishedVersion: number;
  config: ProductConfig;
} | null> {
  await requireAdmin();
  const row = await db.query.products.findFirst({ where: eq(products.slug, slug) });
  if (!row) return null;
  const latest = await db.query.productVersions.findFirst({
    where: eq(productVersions.productId, row.id),
    orderBy: (version, { desc }) => [desc(version.version)],
  });
  if (!latest) throw new Error(`getProductDraft(${slug}): missing product_versions row`);
  const config = productConfigSchema.parse({
    ...(latest.config as Record<string, unknown>),
    slug: row.slug,
    status: row.status,
  });
  return {
    productId: row.id,
    isSeed: row.isSeed,
    version: latest.version,
    publishedVersion: row.currentVersion,
    config,
  };
}

// BO-05 step 1's live slug check (`checkSlug` Server Action).
export async function isSlugAvailable(slug: string): Promise<boolean> {
  await requireAdmin();
  const row = await db.query.products.findFirst({ where: eq(products.slug, slug) });
  return !row;
}

// BO-05 step 2's theme thumbnails; BO-07 reuses it too (plan's orchestrator
// decision 1).
export async function listThemeOptions(): Promise<Theme[]> {
  await requireAdmin();
  const rows = await db.select().from(themes).orderBy(asc(themes.name));
  return rows.map((row) => ({
    id: row.id,
    slug: row.slug,
    name: row.name,
    tokens: themeTokensSchema.parse(row.tokens),
    landingVariant: row.landingVariant,
    isSeed: row.isSeed,
  }));
}

lib/schemas/product-config.ts.content:
import { z } from "zod";
import { packSchema } from "./pack";

// Slugs reserved by the routing (docs/09-arborescence.md › Deux pièges
// relevés en lisant la doc): `[app]` captures every top-level segment, so a
// product cannot use a name that collides with a static route or a
// public/ entry served without an extension. Any extension-less file added
// to public/ (e.g. a new well-known file) must be added to this list too.
export const RESERVED_SLUGS = ["admin", "api"] as const;

const MIN_SLUG_LENGTH = 2;
const MAX_SLUG_LENGTH = 60;
const MAX_NAME_LENGTH = 60;
const MAX_SEO_TITLE_LENGTH = 60;
const MAX_SEO_DESCRIPTION_LENGTH = 160;
const MIN_INPUTS = 1;
// Exported: reused by lib/schemas/inputs.ts to bound generateInputSchema's
// `input` record to the number of fields a product can actually declare.
export const MAX_INPUTS = 10;

export const slugSchema = z
  .string()
  .min(MIN_SLUG_LENGTH)
  .max(MAX_SLUG_LENGTH)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "slug must be lowercase, kebab-case")
  .refine((slug) => !(RESERVED_SLUGS as readonly string[]).includes(slug), {
    error: "slug is reserved",
  });

export const productStatusSchema = z.enum(["test", "learn", "scale", "killed"]);
export type ProductStatus = z.infer<typeof productStatusSchema>;

export const localeSchema = z.enum(["fr", "en"]);

export const inputFieldSchema = z.object({
  key: z.string().regex(/^[a-z][a-z0-9_]*$/, "key must start with a lowercase letter"),
  label: z.string().min(1),
  type: z.enum(["text", "textarea", "select"]),
  required: z.boolean(),
  options: z.array(z.string().min(1)).optional(),
  maxLength: z.int().positive().optional(),
});

// Extracts the deduplicated list of `{{variable}}` names referenced by a
// prompt template, in order of first appearance.
export function templateVariables(template: string): string[] {
  const matches = template.matchAll(/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/g);
  const seen = new Set<string>();
  for (const match of matches) {
    const name = match[1];
    if (name) seen.add(name);
  }
  return [...seen];
}

const brandingSchema = z.object({
  logoUrl: z.url({ protocol: /^https?$/ }).optional(),
  primaryColor: z
    .string()
    .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color")
    .optional(),
});

const faqEntrySchema = z.object({
  question: z.string().min(1),
  answer: z.string().min(1),
});

const landingStepSchema = z.object({
  title: z.string().min(1),
  description: z.string().min(1),
});

const landingSchema = z.object({
  headline: z.string().min(1),
  subheadline: z.string().min(1),
  faq: z.array(faqEntrySchema),
  seoTitle: z.string().min(1).max(MAX_SEO_TITLE_LENGTH),
  seoDescription: z.string().min(1).max(MAX_SEO_DESCRIPTION_LENGTH),
  exampleOutput: z.string().optional(),
  steps: z.array(landingStepSchema).optional(),
});

const generationSchema = z.object({
  model: z.string().min(1),
  fallbackModels: z.array(z.string().regex(/^[a-z0-9-]+\/[a-z0-9.-]+$/i, "must be `provider/model`")).optional(),
  systemPrompt: z.string().optional(),
  promptTemplate: z.string().min(1),
  outputType: z.enum(["markdown", "image"]),
});

const pricingSchema = z.object({
  freeCreditsOnSignup: z.int().min(0),
  anonymousFreeGenerations: z.int().min(0),
  costPerGeneration: z.int().min(1),
  packs: z.array(packSchema).min(1),
});

// Unrefined base shape first: Zod 4 throws on `.pick`/`.omit`/`.extend` of a
// refined object (Zod 4 release notes), so the cross-field checks below are
// added last, with `.superRefine`.
const productConfigBaseSchema = z.object({
  slug: slugSchema,
  name: z.string().min(1).max(MAX_NAME_LENGTH),
  status: productStatusSchema,
  themeId: z.uuid(),
  locale: localeSchema,
  branding: brandingSchema,
  landing: landingSchema,
  inputs: z.array(inputFieldSchema).min(MIN_INPUTS).max(MAX_INPUTS),
  generation: generationSchema,
  pricing: pricingSchema,
});

function addDuplicateIssues(
  ctx: z.RefinementCtx,
  values: string[],
  pathFor: (index: number) => (string | number)[],
  message: string,
) {
  const seen = new Set<string>();
  values.forEach((value, index) => {
    if (seen.has(value)) {
      ctx.addIssue({ code: "custom", message, path: pathFor(index) });
    } else {
      seen.add(value);
    }
  });
}

// The single Zod schema that validates the backoffice form, types the
// database and drives the sub-app's rendering (docs/01-produit.md ›
// Configuration d'un produit).
export const productConfigSchema = productConfigBaseSchema.superRefine((config, ctx) => {
  const fieldKeys = new Set(config.inputs.map((input) => input.key));
  for (const variable of templateVariables(config.generation.promptTemplate)) {
    if (!fieldKeys.has(variable)) {
      ctx.addIssue({
        code: "custom",
        message: `Variable {{${variable}}} sans champ correspondant`,
        path: ["generation", "promptTemplate"],
      });
    }
  }

  addDuplicateIssues(
    ctx,
    config.inputs.map((input) => input.key),
    (index) => ["inputs", index, "key"],
    "key must be unique",
  );

  config.inputs.forEach((input, index) => {
    if (input.type === "select" && (!input.options || input.options.length === 0)) {
      ctx.addIssue({
        code: "custom",
        message: "a select field needs at least one option",
        path: ["inputs", index, "options"],
      });
    }
  });

  addDuplicateIssues(
    ctx,
    config.pricing.packs.map((pack) => pack.id),
    (index) => ["pricing", "packs", index, "id"],
    "pack id must be unique",
  );
});

export type ProductConfig = z.infer<typeof productConfigSchema>;

