import type { FontKey } from "@/lib/fonts";

// BO-08's font `<select>`: FONT_KEYS is the fixed catalogue
// (lib/fonts.ts › "a theme can only reference a key of this catalogue,
// never an arbitrary font"), each key carries a readable French label.
export const FONT_LABELS: Record<FontKey, string> = {
  serif: "Serif (éditorial)",
  grotesk: "Grotesque (néon)",
  sans: "Sans-serif (corporate)",
  rounded: "Arrondie (ludique)",
};

import type { CSSProperties } from "react";
import type { ThemeTokens } from "@/lib/schemas/theme-tokens";

// camelCase color token key -> kebab-case CSS variable suffix, same rule as
// components/product/theme-vars.ts (not imported from there: that module
// prefixes with `--light-` / `--dark-` for the product layout's
// `prefers-color-scheme` split, which this preview does not use — it
// renders one mode at a time, directly under its own scoped element).
function kebab(key: string): string {
  return key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

// BO-08's preview column (plan's design decision 6): the chosen mode's
// tokens as the *direct* shadcn variables (`--background`, `--primary`…)
// plus `--radius`, scoped to the preview's own root element rather than
// `<html>`. `themeTokensSchema` already rejects values that could break out
// of a `style` attribute, so values are passed through verbatim.
export function previewCssVars(tokens: ThemeTokens, mode: "light" | "dark"): CSSProperties {
  const vars: Record<string, string> = { "--radius": tokens.radius };
  for (const [key, value] of Object.entries(tokens[mode])) {
    vars[`--${kebab(key)}`] = value;
  }
  return vars as CSSProperties;
}

// BO-08's radius slider (plan's design decision 5): 0 to 2rem, step 0.125.
// The frozen `themeTokensSchema` accepts either `rem` or `px`, but the
// slider only ever produces `rem`, so the round trip through the schema is
// exact (no float noise from a px conversion back out).
const PX_PER_REM = 16;
const MIN_REM = 0;
const MAX_REM = 2;

// Reads a persisted radius (rem or px) back into the slider's rem number.
export function radiusToRem(radius: string): number {
  const match = /^(\d+(?:\.\d+)?)(rem|px)$/.exec(radius);
  if (!match) return 0;
  const value = Number(match[1]);
  return match[2] === "px" ? value / PX_PER_REM : value;
}

// Formats the slider's rem number back to a CSS length, clamped to the
// slider's own range so an out-of-range value (e.g. a stale draft) never
// produces a length the schema would reject.
export function remToRadius(rem: number): string {
  const clamped = Math.min(MAX_REM, Math.max(MIN_REM, rem));
  return `${clamped}rem`;
}

"use client";

import Link from "next/link";
import type { Route } from "next";
import { useActionState, useEffect, useState } from "react";
import { toast } from "sonner";
import { FONT_KEYS } from "@/lib/fonts";
import type { Theme } from "@/lib/dal/themes";
import type { LandingVariant, ThemeTokens } from "@/lib/schemas/theme-tokens";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { LANDING_VARIANT_LABELS } from "../../_components/landing-variant-labels";
import { saveTheme, type SaveThemeState } from "../_actions";
import { FONT_LABELS } from "./font-labels";
import { radiusToRem, remToRadius } from "./radius";
import { ThemePreview } from "./theme-preview";

// The 16 keys of colorTokensSchema (lib/schemas/theme-tokens.ts), in the
// schema's own order (plan's design decision 4). A literal tuple rather
// than `Object.keys(tokens.light)`: the schema is frozen, but a runtime
// key order is not a contract worth depending on.
const COLOR_KEYS = [
  "background",
  "foreground",
  "card",
  "cardForeground",
  "primary",
  "primaryForeground",
  "secondary",
  "secondaryForeground",
  "muted",
  "mutedForeground",
  "accent",
  "accentForeground",
  "destructive",
  "border",
  "input",
  "ring",
] as const satisfies readonly (keyof ThemeTokens["light"])[];

function colorLabel(key: string): string {
  const kebab = key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
  const words = kebab.split("-");
  return `${words[0]![0]!.toUpperCase()}${words[0]!.slice(1)}${words.length > 1 ? ` ${words.slice(1).join(" ")}` : ""}`;
}

const initialState: SaveThemeState = {};

// BO-08's editor (specs/BO-08-editeur-theme.md, docs/03-maquettes.md ›
// BO-08): stacked `<fieldset>` sections (plan's orchestrator decision 1)
// instead of the mockup's tabs. `theme.id` is bound to `saveTheme` once
// (next/root-params is not available in Server Actions, same reasoning as
// admin/products' `.bind(null, slug)`).
export function ThemeEditor({ theme, sampleProductName }: { theme: Theme; sampleProductName?: string }) {
  const [tokens, setTokens] = useState<ThemeTokens>(theme.tokens);
  const [landingVariant, setLandingVariant] = useState<LandingVariant>(theme.landingVariant);
  const [mode, setMode] = useState<"light" | "dark">("light");
  const [state, formAction, pending] = useActionState(saveTheme.bind(null, theme.id), initialState);

  useEffect(() => {
    if (state.ok) toast.success("Thème enregistré");
    if (state.formError) toast.error(state.formError);
  }, [state]);

  const errors = state.errors ?? {};
  const hasErrors = Object.keys(errors).length > 0;

  function updateColor(key: (typeof COLOR_KEYS)[number], value: string) {
    setTokens((current) => ({ ...current, [mode]: { ...current[mode], [key]: value } }));
  }

  const payload = JSON.stringify({ tokens, landingVariant });

  return (
    <div className="grid gap-6 lg:grid-cols-2">
      <form action={formAction} className="grid gap-6">
        <input type="hidden" name="payload" value={payload} readOnly />

        {hasErrors ? (
          <p role="alert" className="text-sm text-destructive">
            Ce thème contient des erreurs.
          </p>
        ) : null}

        <fieldset className="grid gap-6">
          <fieldset className="grid gap-3">
            <legend className="text-sm font-semibold">Couleurs</legend>
            <div role="group" aria-label="Mode" className="flex w-fit gap-1 rounded-md border p-1">
              <button
                type="button"
                aria-pressed={mode === "light"}
                className="rounded px-2 py-1 text-sm aria-pressed:bg-secondary"
                onClick={() => setMode("light")}
              >
                Clair
              </button>
              <button
                type="button"
                aria-pressed={mode === "dark"}
                className="rounded px-2 py-1 text-sm aria-pressed:bg-secondary"
                onClick={() => setMode("dark")}
              >
                Sombre
              </button>
            </div>

            <div className="grid grid-cols-2 gap-3">
              {COLOR_KEYS.map((key) => {
                const value = tokens[mode][key];
                const path = `tokens.${mode}.${key}`;
                const fieldId = `theme-color-${mode}-${key}`;
                return (
                  <div key={key} className="grid gap-1.5">
                    <Label htmlFor={fieldId}>{colorLabel(key)}</Label>
                    <div className="flex items-center gap-2">
                      <span
                        aria-hidden="true"
                        className="size-6 shrink-0 rounded border"
                        style={{ backgroundColor: /^#[0-9a-fA-F]{3,8}$/.test(value) ? value : "transparent" }}
                      />
                      <Input
                        id={fieldId}
                        value={value}
                        aria-invalid={path in errors}
                        aria-describedby={errors[path] ? `${fieldId}-error` : undefined}
                        onChange={(event) => updateColor(key, event.target.value)}
                      />
                    </div>
                    {errors[path] ? (
                      <p id={`${fieldId}-error`} className="text-sm text-destructive">
                        {errors[path]}
                      </p>
                    ) : null}
                  </div>
                );
              })}
            </div>
          </fieldset>

          <fieldset className="grid gap-1.5">
            <legend className="text-sm font-semibold">Typographie</legend>
            <Label htmlFor="theme-font-key">Police</Label>
            <select
              id="theme-font-key"
              className="w-fit rounded-md border bg-background px-3 py-2 text-sm"
              value={tokens.fontKey}
              aria-invalid={"tokens.fontKey" in errors}
              aria-describedby={errors["tokens.fontKey"] ? "theme-font-key-error" : undefined}
              onChange={(event) => setTokens((current) => ({ ...current, fontKey: event.target.value }))}
            >
              {FONT_KEYS.map((key) => (
                <option key={key} value={key}>
                  {FONT_LABELS[key]}
                </option>
              ))}
            </select>
            {errors["tokens.fontKey"] ? (
              <p id="theme-font-key-error" className="text-sm text-destructive">
                {errors["tokens.fontKey"]}
              </p>
            ) : null}
          </fieldset>

          <fieldset className="grid gap-1.5">
            <legend className="text-sm font-semibold">Forme</legend>
            <Label htmlFor="theme-radius">Radius</Label>
            <div className="flex items-center gap-3">
              <input
                id="theme-radius"
                type="range"
                min={0}
                max={2}
                step={0.125}
                value={radiusToRem(tokens.radius)}
                aria-invalid={"tokens.radius" in errors}
                aria-describedby={errors["tokens.radius"] ? "theme-radius-error" : undefined}
                onChange={(event) =>
                  setTokens((current) => ({ ...current, radius: remToRadius(Number(event.target.value)) }))
                }
              />
              <span className="text-sm text-muted-foreground">{tokens.radius}</span>
            </div>
            {errors["tokens.radius"] ? (
              <p id="theme-radius-error" className="text-sm text-destructive">
                {errors["tokens.radius"]}
              </p>
            ) : null}
          </fieldset>

          <fieldset className="grid gap-1.5">
            <legend className="text-sm font-semibold">Landing</legend>
            <Label htmlFor="theme-landing-variant">Variante de landing</Label>
            <select
              id="theme-landing-variant"
              className="w-fit rounded-md border bg-background px-3 py-2 text-sm"
              value={landingVariant}
              aria-invalid={"landingVariant" in errors}
              aria-describedby={errors.landingVariant ? "theme-landing-variant-error" : undefined}
              onChange={(event) => setLandingVariant(event.target.value as LandingVariant)}
            >
              {Object.entries(LANDING_VARIANT_LABELS).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
            {errors.landingVariant ? (
              <p id="theme-landing-variant-error" className="text-sm text-destructive">
                {errors.landingVariant}
              </p>
            ) : null}
          </fieldset>
        </fieldset>

        <div className="flex justify-between">
          <Button variant="outline" asChild>
            <Link href={"/admin/themes" as Route}>Annuler</Link>
          </Button>
          <Button type="submit" disabled={pending}>
            Enregistrer
          </Button>
        </div>
      </form>

      <ThemePreview tokens={tokens} landingVariant={landingVariant} mode={mode} sampleProductName={sampleProductName} />
    </div>
  );
}

import type { z } from "zod";

// BO-08 (specs/BO-08-editeur-theme.md): translates the frozen
// `themeTokensSchema` / `landingVariantSchema`'s own issues (English,
// shared with the runtime, plan's design decision) to the message shown
// next to a field of the editor. Mirrors
// admin/products/_components/product-form/validation.ts's
// `toFrenchMessage` / `issuesToErrors`, scoped to this schema's two custom
// regex messages; anything else (a Zod built-in, e.g. the enum message on
// `landingVariant`) falls back to the raw message rather than being
// silently dropped.
const FRENCH_MESSAGES: Record<string, string> = {
  "must be a #hex color or a color function call (oklch, hsl, rgb…)":
    "Doit être une couleur CSS valide (#hex ou oklch/hsl/rgb…)",
  "must be a CSS length in rem or px": "Doit être une longueur CSS en rem ou px (ex. 0.5rem)",
};

// First message per dotted path (e.g. "tokens.light.background"), same
// convention as issuesToErrors.
export function toThemeErrors(issues: readonly z.core.$ZodIssue[]): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const issue of issues) {
    const path = issue.path.join(".");
    if (path in errors) continue;
    errors[path] = FRENCH_MESSAGES[issue.message] ?? issue.message;
  }
  return errors;
}

import { fontFor } from "@/lib/fonts";
import type { LandingVariant, ThemeTokens } from "@/lib/schemas/theme-tokens";
import { cn } from "@/components/utils";
import { previewCssVars } from "./preview-vars";

// BO-08's preview column (docs/03-maquettes.md › BO-08: "Tokens à gauche,
// rendu de la landing et des composants à droite", plan's design decision
// 6). A real mini-render (docs/04-nextjs.md: "ce sont de vrais mini-rendus
// React avec les tokens du thème"), scoped through `previewCssVars` on its
// own root rather than `<html>`: `var(--token)` in every child's inline
// style resolves through this root, live as the draft tokens change.
export function ThemePreview({
  tokens,
  landingVariant,
  mode,
  sampleProductName,
}: {
  tokens: ThemeTokens;
  landingVariant: LandingVariant;
  mode: "light" | "dark";
  sampleProductName?: string;
}) {
  const font = fontFor(tokens.fontKey);
  const headline = sampleProductName ?? "Produit exemple";

  return (
    <div
      data-testid="theme-preview"
      data-mode={mode}
      data-variant={landingVariant}
      className={cn(font.className, "flex flex-col gap-4 border p-4")}
      style={{
        ...previewCssVars(tokens, mode),
        backgroundColor: "var(--background)",
        color: "var(--foreground)",
        borderColor: "var(--border)",
        borderRadius: "var(--radius)",
      }}
    >
      <div className={cn("flex gap-4", landingVariant === "split" && "items-center justify-between")}>
        <div className="flex flex-col gap-2">
          <h2 className="text-lg font-semibold">{headline}</h2>
          {landingVariant !== "minimal" ? (
            <p style={{ color: "var(--muted-foreground)" }}>Un sous-titre de démonstration pour l’aperçu.</p>
          ) : null}
          <button
            type="button"
            className="w-fit rounded px-3 py-1.5 text-sm"
            style={{
              backgroundColor: "var(--primary)",
              color: "var(--primary-foreground)",
              borderRadius: "var(--radius)",
            }}
          >
            Essayer
          </button>
        </div>
        {landingVariant === "split" ? (
          <div
            data-testid="theme-preview-example"
            className="w-24 shrink-0 rounded p-3 text-xs"
            style={{
              backgroundColor: "var(--card)",
              color: "var(--card-foreground)",
              borderRadius: "var(--radius)",
            }}
          >
            Exemple de résultat
          </div>
        ) : null}
      </div>

      <div data-testid="theme-preview-components" className="flex flex-wrap items-center gap-2">
        <button
          data-testid="theme-preview-button-primary"
          type="button"
          className="rounded px-3 py-1.5 text-sm"
          style={{
            backgroundColor: "var(--primary)",
            color: "var(--primary-foreground)",
            borderRadius: "var(--radius)",
          }}
        >
          Primaire
        </button>
        <button
          data-testid="theme-preview-button-secondary"
          type="button"
          className="rounded px-3 py-1.5 text-sm"
          style={{
            backgroundColor: "var(--secondary)",
            color: "var(--secondary-foreground)",
            borderRadius: "var(--radius)",
          }}
        >
          Secondaire
        </button>
        <span
          data-testid="theme-preview-badge-accent"
          className="rounded-full px-2 py-0.5 text-xs"
          style={{ backgroundColor: "var(--accent)", color: "var(--accent-foreground)" }}
        >
          Accent
        </span>
        <span
          data-testid="theme-preview-badge-destructive"
          className="rounded-full px-2 py-0.5 text-xs"
          style={{ backgroundColor: "var(--destructive)", color: "var(--primary-foreground)" }}
        >
          Erreur
        </span>
      </div>
    </div>
  );
}

