import type { CSSProperties } from "react";
import type { ProductConfig } from "@/lib/schemas/product-config";
import type { ThemeTokens } from "@/lib/schemas/theme-tokens";

// camelCase color token key -> kebab-case CSS variable suffix, e.g.
// `cardForeground` -> `card-foreground`.
function kebab(key: string): string {
  return key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

// Theme tokens as inline CSS variables on the product layout's `<html>`
// (docs/04-nextjs.md › Thèmes, polices et images): app/globals.css reads
// `--light-*` / `--dark-*` with a `prefers-color-scheme` media query and no
// theme JavaScript. `themeTokensSchema` already rejects values that could
// break out of a `style` attribute (`;`, `}`, `url(`…), so values are passed
// through verbatim.
export function themeCssVars(tokens: ThemeTokens, branding: ProductConfig["branding"]): CSSProperties {
  const vars: Record<string, string> = { "--radius": tokens.radius };

  for (const [key, value] of Object.entries(tokens.light)) {
    vars[`--light-${kebab(key)}`] = value;
  }
  for (const [key, value] of Object.entries(tokens.dark)) {
    vars[`--dark-${kebab(key)}`] = value;
  }

  if (branding.primaryColor) {
    vars["--light-primary"] = branding.primaryColor;
    vars["--dark-primary"] = branding.primaryColor;
  }

  return vars as CSSProperties;
}

lib/dal/themes.ts.content:
import "server-only";
import { asc, eq } from "drizzle-orm";
import { cacheLife, cacheTag } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { products, themes } from "@/lib/db/schema";
import {
  landingVariantSchema,
  themeTokensSchema,
  type LandingVariant,
  type ThemeTokens,
} from "@/lib/schemas/theme-tokens";
import { requireAdmin } from "./session";

// † Frozen contract (specs/CONTRACT-types.md): not a row of the contract
// table (docs/11), but named by docs/04-nextjs.md's layout excerpt
// (`getTheme(product.themeId)`, `'use cache'` + `cacheTag(theme:{id})`).
export type Theme = {
  id: string;
  slug: string;
  name: string;
  tokens: ThemeTokens;
  landingVariant: LandingVariant;
  isSeed: boolean;
};

// The theme's tokens are public data (they drive the sub-app's layout), so
// no session check here, like getProduct (lib/dal/products.ts).
export const getTheme: (id: string) => Promise<Theme | null> = async (id) => {
  "use cache";
  cacheLife("max");
  cacheTag(`theme:${id}`);
  // A malformed id (e.g. a slug typed by mistake) is not a database error:
  // it is simply not found, without a round trip.
  if (!z.uuid().safeParse(id).success) return null;
  const row = await db.query.themes.findFirst({ where: eq(themes.id, id) });
  if (!row) return null;
  return {
    id: row.id,
    slug: row.slug,
    name: row.name,
    tokens: themeTokensSchema.parse(row.tokens),
    landingVariant: row.landingVariant,
    isSeed: row.isSeed,
  };
};

// BO-08 (specs/BO-08-editeur-theme.md): additive next to `getTheme` (plan's
// frozen inputs), `getTheme`'s own contract untouched. `requireAdmin` first
// (a Server Action is a public POST endpoint, CLAUDE.md); a non-uuid `id`
// returns null without a round trip, same convention as `getTheme`. Inside
// the transaction: the row is locked with `SELECT … FOR UPDATE` so two
// concurrent saves serialize instead of racing, then tokens /
// landingVariant / updatedAt are written and every product on the theme
// (including `killed` ones: they still reference it) is returned so the
// caller can invalidate their own tag too.
export async function updateTheme(
  id: string,
  input: { tokens: ThemeTokens; landingVariant: LandingVariant },
): Promise<{ id: string; productSlugs: string[] } | null> {
  await requireAdmin();
  if (!z.uuid().safeParse(id).success) return null;
  const tokens = themeTokensSchema.parse(input.tokens);
  const landingVariant = landingVariantSchema.parse(input.landingVariant);

  return db.transaction(async (tx) => {
    const [row] = await tx.select().from(themes).where(eq(themes.id, id)).for("update");
    if (!row) return null;

    await tx.update(themes).set({ tokens, landingVariant, updatedAt: new Date() }).where(eq(themes.id, id));

    const productRows = await tx
      .select({ slug: products.slug })
      .from(products)
      .where(eq(products.themeId, id))
      .orderBy(asc(products.slug));

    return { id, productSlugs: productRows.map((product) => product.slug) };
  });
}

lib/fonts.ts.content:
// The fixed font catalogue `next/font` requires (docs/04-nextjs.md ›
// Thèmes, polices et images): fonts are downloaded and self-hosted at
// build time, so a theme can only reference a key of this catalogue, never
// an arbitrary font. The 4 keys are semantic and shared with CONTRACT-data's
// seed (plan decision 1): editorial -> serif, neon -> grotesk,
// corporate -> sans, playful -> rounded.
import { Fraunces, Inter, Nunito, Space_Grotesk } from "next/font/google";

export const FONT_KEYS = ["serif", "grotesk", "sans", "rounded"] as const;
export type FontKey = (typeof FONT_KEYS)[number];

// Every loader shares the same `variable`: the theme applies its font by
// putting the matching `className` on `<html>`, and `--font-theme` is read
// by `@theme inline` in app/globals.css. `preload: false` so only the
// active theme's font is preloaded by the browser, not all 4. The options
// object is repeated (not shared through a constant): `next/font`'s
// compiler statically analyzes each call and requires an inline literal.
const serif = Fraunces({ variable: "--font-theme", display: "swap", preload: false });
const grotesk = Space_Grotesk({ variable: "--font-theme", display: "swap", preload: false });
const sans = Inter({ variable: "--font-theme", display: "swap", preload: false });
const rounded = Nunito({ variable: "--font-theme", display: "swap", preload: false });

const FONTS: Record<FontKey, { variable: string; className: string }> = { serif, grotesk, sans, rounded };

// Unknown key (a theme edited outside the catalogue) falls back to `sans`
// rather than throwing: the layout still renders with a readable font.
export function fontFor(key: string): { variable: string; className: string } {
  return FONTS[key as FontKey] ?? FONTS.sans;
}

lib/schemas/theme-tokens.ts.content:
import { z } from "zod";

// A CSS color value only: `#hex` or a function call (`oklch()`, `hsl()`,
// `rgb()`, `rgba()`…) whose arguments are digits, `.`, `%`, spaces, `/` or
// `,`. Values are injected verbatim into `style` (docs/04-nextjs.md), so
// anything that could break out of that context (`;`, `}`, `url(`…) is
// rejected.
const cssColorSchema = z
  .string()
  .regex(
    /^(#[0-9a-fA-F]{3,8}|[a-z-]+\([0-9.%\s/,]+\))$/,
    "must be a #hex color or a color function call (oklch, hsl, rgb…)",
  );

// The shadcn/ui CSS variable set (docs/01-produit.md › Thèmes).
const colorTokensSchema = z.object({
  background: cssColorSchema,
  foreground: cssColorSchema,
  card: cssColorSchema,
  cardForeground: cssColorSchema,
  primary: cssColorSchema,
  primaryForeground: cssColorSchema,
  secondary: cssColorSchema,
  secondaryForeground: cssColorSchema,
  muted: cssColorSchema,
  mutedForeground: cssColorSchema,
  accent: cssColorSchema,
  accentForeground: cssColorSchema,
  destructive: cssColorSchema,
  border: cssColorSchema,
  input: cssColorSchema,
  ring: cssColorSchema,
});

// Tokens of a theme (table `themes`, docs/07). `fontKey` and `radius` are
// laid out on the layout's `<html>` element next to the color variables.
export const themeTokensSchema = z.object({
  light: colorTokensSchema,
  dark: colorTokensSchema,
  fontKey: z.string().min(1),
  radius: z.string().regex(/^\d+(\.\d+)?(rem|px)$/, "must be a CSS length in rem or px"),
});

export type ThemeTokens = z.infer<typeof themeTokensSchema>;

// The landing page layout a theme renders (docs/01-produit.md › Thèmes).
export const landingVariantSchema = z.enum(["centered", "split", "minimal"]);

export type LandingVariant = z.infer<typeof landingVariantSchema>;

