components/track-visit.tsx.content:
"use client";
import { useEffect } from "react";

// specs/TRACKING.md bullet 1: on mount, sends a `visit` beacon to the
// product's `api/events` (docs/04-nextjs.md: the landing stays static, so a
// client leaf does the write instead of a server-side `track()` call,
// which would force the page dynamic).
//
// QA1-P1-B4: this used to mint `crypto.randomUUID()` on every beacon, so
// StrictMode's doubled effect (or two tabs) produced two different ids and
// two visitors for one visit. Identity now only ever comes from the
// httpOnly `anonymous_id` cookie proxy.ts sets before this component ever
// mounts (docs/04's proxy.ts line); the body id is a fixed placeholder,
// still a syntactically valid uuid so it satisfies the frozen
// trackEventInputSchema, and api/events/route.ts ignores it entirely.
const PLACEHOLDER_ANONYMOUS_ID = "00000000-0000-0000-0000-000000000000";

export const TrackVisit: (props: { slug: string }) => null = ({ slug }) => {
  useEffect(() => {
    navigator.sendBeacon?.(
      `/${slug}/api/events`,
      new Blob([JSON.stringify({ type: "visit", anonymousId: PLACEHOLDER_ANONYMOUS_ID })], {
        type: "application/json",
      }),
    );
  }, [slug]);
  return null;
};

i18n/load-messages.ts.content:
import type { ProductConfig } from "@/lib/schemas/product-config";
import files from "@/messages/manifest";

// One zone file per namespace (docs/09-arborescence.md, messages/{fr,en}/*.json):
// each spec adds its own `messages/<locale>/<zone>.json`, picked up
// automatically by messages/manifest.ts's `import.meta.glob` (moved there:
// Turbopack's glob only resolves descending patterns, see that file).

// Namespace: the zone file's base name (`common.json` -> `common`).
function zoneName(path: string): string {
  return path
    .split("/")
    .pop()!
    .replace(/\.json$/, "");
}

export async function loadMessages(locale: ProductConfig["locale"]): Promise<Record<string, unknown>> {
  const messages: Record<string, unknown> = {};
  for (const [path, content] of Object.entries(files)) {
    if (!path.includes(`/${locale}/`)) continue;
    messages[zoneName(path)] = content;
  }
  // Never render a page with silently missing translations (the Turbopack
  // glob regression that fixed by messages/manifest.ts, docs/11
  // "no silent failure"): an empty result or a locale without its common
  // zone means messages/manifest.ts stopped globbing files, not that this
  // product genuinely has none.
  if (Object.keys(messages).length === 0 || !("common" in messages)) {
    throw new Error(`loadMessages(${locale}): no messages resolved, check messages/manifest.ts`);
  }
  return messages;
}

