                </th>
                <th scope="col" className="py-2 pr-4 font-medium">
                  Entrée
                </th>
                <th scope="col" className="py-2 pr-4 font-medium">
                  Sortie
                </th>
                <th scope="col" className="py-2 pr-4 font-medium">
                  Modèle
                </th>
                <th scope="col" className="py-2 pr-4 font-medium">
                  Coût IA
                </th>
                <th scope="col" className="py-2 pr-4 font-medium">
                  Statut
                </th>
              </tr>
            </thead>
            <tbody>
              {entries.map((entry) => {
                const status = generationStatus(entry);
                return (
                  <tr key={entry.id} className="border-b last:border-0">
