  currentPages,
}: {
  slug: string;
  listKey: ActivityListKey;
  page: number;
  hasMore: boolean;
  currentPages: Partial<Record<ActivityListKey, number>>;
}) {
  if (page <= 1 && !hasMore) return null;

  return (
    <nav className="flex items-center justify-between text-sm">
      {page > 1 ? (
        <Link href={activityHref(slug, currentPages, { key: listKey, page: page - 1 })}>Précédent</Link>
      ) : (
        <span />
      )}
      {hasMore ? (
        <Link href={activityHref(slug, currentPages, { key: listKey, page: page + 1 })}>Suivant</Link>
      ) : (
        <span />
      )}
    </nav>
  );
}

import Link from "next/link";
import { EmptyState } from "@/components/shared/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { ActivityPurchase, PurchaseSummary } from "@/lib/dal/activity";
import { formatRelative, purchaseSummaryLines } from "../_lib/activity-format";
import { formatEuroCents } from "@/app/(backoffice)/admin/_components/portfolio/format";
import { activityHref, type ActivityListKey } from "../_lib/pagination";
import { PaginationNav } from "./pagination-nav";

// BO-04's "Achats" card: the mockup's 30-day summary ("14 achats · 72 €",
// "Pack 10 : 11 · Pack 50 : 3") plus a paginated list of every purchase
// (plan § "Purchases show the mockup's 30-day summary and a paginated
// list").
export function PurchasesCard({
  slug,
  summary,
  entries,
  total,
  page,
  hasMore,
  now,
  currentPages,
}: {
  slug: string;
  summary: PurchaseSummary;
  entries: ActivityPurchase[];
  total: number;
  page: number;
  hasMore: boolean;
  now: Date;
  currentPages: Partial<Record<ActivityListKey, number>>;
}) {
  const listKey: ActivityListKey = "purchases";
  const [headline, breakdown] = purchaseSummaryLines(summary);

  return (
    <Card>
      <CardHeader>
        <CardTitle>Achats · 30 j</CardTitle>
      </CardHeader>
      <CardContent className="grid gap-4">
        <div>
          <p className="text-lg font-semibold">{headline}</p>
          {breakdown ? <p className="text-sm text-muted-foreground">{breakdown}</p> : null}
        </div>

        {total === 0 ? (
          <EmptyState title="Aucun achat pour l'instant" />
        ) : entries.length === 0 ? (
          <EmptyState
            title="Page vide"
            action={
              <Link href={activityHref(slug, currentPages, { key: listKey, page: 1 })} className="underline">
                Revenir à la première page
              </Link>
            }
          />
        ) : (
          <ul className="grid gap-2">
            {entries.map((purchase) => (
              <li key={purchase.id} className="flex items-center justify-between gap-3 text-sm">
                <span className="font-medium">+{purchase.credits}</span>
                <span className="flex-1">{formatEuroCents(purchase.amountCents)}</span>
                <span className="text-muted-foreground">{formatRelative(purchase.createdAt, now)}</span>
              </li>
            ))}
          </ul>
        )}
        <PaginationNav slug={slug} listKey={listKey} page={page} hasMore={hasMore} currentPages={currentPages} />
      </CardContent>
    </Card>
  );
}

import { formatEuroCents, formatEuroMicros } from "@/app/(backoffice)/admin/_components/portfolio/format";
import { excerpt, summarizeInput } from "@/app/(products)/[app]/history/_lib/summarize";
import type { ActivityGeneration, ActivityMovement, PurchaseSummary } from "@/lib/dal/activity";

// BO-04 (specs/BO-04-activite.md), pure view formatting — no DB, no
// session — colocated under the route (plan § "Pure helpers"). Re-uses two
// read-only helpers from SA-06's private `_lib` (plan design decision 4)
// instead of duplicating truncation logic: `summarizeInput` for the
// "Entrée" column, `excerpt` for "Sortie".

const EM_DASH = "—";

// AI cost with at least 3 decimals ("0,004 €", plan design decision 4),
// more when needed so a sub-millieuro generation never reads 0,000 €
// (QA1 B8): the portfolio's adaptive `formatEuroMicros`.
export function formatCostMicros(costMicros: number | null): string {
  return formatEuroMicros(costMicros ?? 0, 3);
}

const MS_PER_MINUTE = 60_000;
const MINUTES_PER_HOUR = 60;
const HOURS_PER_DAY = 24;

// "il y a 2 min" / "il y a 1 h" / "il y a 3 j" (mockup, specs/mockups/BO-04.png): abbreviated
// French units, not Intl.RelativeTimeFormat's full words ("il y a 2 minutes"). `now` is passed in
// (plan design decision 8: created once, after requireAdmin(), by the caller) rather than read
// here, so this stays a pure function of its two arguments.
export function formatRelative(date: Date, now: Date): string {
  const diffMinutes = Math.max(0, Math.floor((now.getTime() - date.getTime()) / MS_PER_MINUTE));
  if (diffMinutes < 1) return "à l'instant";
  if (diffMinutes < MINUTES_PER_HOUR) return `il y a ${diffMinutes} min`;
  const diffHours = Math.floor(diffMinutes / MINUTES_PER_HOUR);
  if (diffHours < HOURS_PER_DAY) return `il y a ${diffHours} h`;
  const diffDays = Math.floor(diffHours / HOURS_PER_DAY);
  return `il y a ${diffDays} j`;
}

const MINUS_SIGN = "−"; // U+2212, not a hyphen (plan § "Pure helpers": "formatDelta (U+2212)").

export function formatDelta(delta: number): string {
  return delta >= 0 ? `+${delta}` : `${MINUS_SIGN}${Math.abs(delta)}`;
}

// "Achat pack 10", "Génération", "Remboursement", "Bonus inscription"
// (mockup's "Mouvements de crédits" card).
export function movementLabel(movement: Pick<ActivityMovement, "reason" | "packCredits">): string {
  switch (movement.reason) {
    case "purchase":
      return movement.packCredits !== null ? `Achat pack ${movement.packCredits}` : "Achat";
    case "generation":
      return "Génération";
    case "refund":
      return "Remboursement";
    case "signup_bonus":
      return "Bonus inscription";
  }
}

export type GenerationStatusView = { label: string; variant: "ok" | "error" | "pending" };

// "OK" (green), "Erreur · remboursé" (red, mockup) when a failed generation
// was refunded, "Erreur" for a failed one that hasn't been (yet), "En
// cours" for a still-pending row.
export function generationStatus(entry: Pick<ActivityGeneration, "status" | "refunded">): GenerationStatusView {
  if (entry.status === "succeeded") return { label: "OK", variant: "ok" };
  if (entry.status === "pending") return { label: "En cours", variant: "pending" };
  return { label: entry.refunded ? "Erreur · remboursé" : "Erreur", variant: "error" };
}

// The "Sortie" column: an em dash for a generation with no output yet (a
// failed or pending row, mockup), the joined items of a structured output
// (docs/07: "output … Texte ou objet structuré"), otherwise the excerpted
// text.
export function summarizeOutput(output: unknown, max = 80): string {
  if (output === null || output === undefined) return EM_DASH;
  if (typeof output === "string") return excerpt(output, max);
  if (Array.isArray(output)) return excerpt(output.map((item) => String(item)).join(", "), max);
  return excerpt(JSON.stringify(output), max);
}

export { excerpt, summarizeInput };

// The "Achats · 30 j" card (mockup): a headline ("14 achats · 72 €") and,
// when at least one pack was sold, a breakdown line ("Pack 10 : 11 · Pack
// 50 : 3"). Returned as lines (not a single string) so the component
// decides how to lay them out, mirroring the mockup's two-line card.
export function purchaseSummaryLines(summary: PurchaseSummary): string[] {
  const headline = `${summary.count} achat${summary.count > 1 ? "s" : ""} · ${formatEuroCents(summary.revenueCents)}`;
  if (summary.byPack.length === 0) return [headline];
  const breakdown = summary.byPack.map((pack) => `Pack ${pack.credits} : ${pack.count}`).join(" · ");
  return [headline, breakdown];
}

import type { Route } from "next";

// BO-04 (specs/BO-04-activite.md): the page owns three independently
// paginated lists (generations, purchases, credit movements), so their
// `?page=` query keys must not collide, and paginating one list must not
// reset the other two (plan § "pagination.ts: parsePageParam, activityHref,
// which keeps each list's page param").

export type ActivityListKey = "generations" | "purchases" | "movements";

const PAGE_PARAM: Record<ActivityListKey, string> = {
  generations: "genPage",
  purchases: "purPage",
  movements: "movPage",
};

// A malformed, missing or non-positive value falls back to page 1 (mirrors
// SA-06's `pageParamSchema`), never throws: it drives a link's query string,
// not a DAL call.
export function parsePageParam(value: string | string[] | undefined): number {
  const raw = Array.isArray(value) ? value[0] : value;
  const parsed = raw === undefined ? Number.NaN : Number.parseInt(raw, 10);
  return Number.isInteger(parsed) && parsed >= 1 ? parsed : 1;
}

// The activity page's own href builder: `current` carries the three lists'
// current pages, `next` the one being changed. Page 1 is the default (never
// written to the URL), so a fresh visit's URL stays bare.
export function activityHref(
  slug: string,
  current: Partial<Record<ActivityListKey, number>>,
  next: { key: ActivityListKey; page: number },
): Route {
  const merged: Partial<Record<ActivityListKey, number>> = { ...current, [next.key]: next.page };
  const params = new URLSearchParams();
  (Object.keys(PAGE_PARAM) as ActivityListKey[]).forEach((key) => {
    const page = merged[key];
    if (page && page > 1) params.set(PAGE_PARAM[key], String(page));
  });
  const query = params.toString();
  return `/admin/products/${slug}/activity${query ? `?${query}` : ""}` as Route;
}

export function readPageParam(
  searchParams: Record<string, string | string[] | undefined>,
  key: ActivityListKey,
): number {
  return parsePageParam(searchParams[PAGE_PARAM[key]]);
}

import { notFound } from "next/navigation";
import { Suspense } from "react";
import {
  getPurchaseSummary,
  listProductCreditMovements,
  listProductGenerations,
  listProductPurchases,
} from "@/lib/dal/activity";
import { getProduct } from "@/lib/dal/products";
import { requireAdmin } from "@/lib/dal/session";
import { ActivitySkeleton } from "./_components/activity-skeleton";
import { ActivityView } from "./_components/activity-view";
import { readPageParam } from "./_lib/pagination";

// BO-04 (specs/BO-04-activite.md): session-gated (own requireAdmin(), like
// every /admin page — require-admin-coverage.test.ts), never cached
// (docs/04-nextjs.md), so it streams under <Suspense> while the shell above
// renders instantly. notFound() for an unknown slug; a killed product still
// shows its history (plan § "killed product still shows its history").
async function Activity({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  await requireAdmin();
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();

  // Created once, after requireAdmin() (a request-time API), then passed
  // down to every pure helper that formats a relative date or windows the
  // purchase summary (plan design decision 8).
  const now = new Date();

  const search = await searchParams;
  const genPage = readPageParam(search, "generations");
  const purPage = readPageParam(search, "purchases");
  const movPage = readPageParam(search, "movements");

  const [generations, purchases, movements, purchaseSummary] = await Promise.all([
    listProductGenerations(product.id, genPage),
    listProductPurchases(product.id, purPage),
    listProductCreditMovements(product.id, movPage),
    getPurchaseSummary(product.id, now),
  ]);

  return (
    <ActivityView
      slug={product.slug}
      name={product.name}
      status={product.status}
      fields={product.inputs}
      generations={generations}
      movements={movements}
      purchases={purchases}
      purchaseSummary={purchaseSummary}
      now={now}
    />
  );
}

export default function ProductActivityPage({ params, searchParams }: PageProps<"/admin/products/[slug]/activity">) {
  return (
    <main className="p-6">
      <Suspense fallback={<ActivitySkeleton />}>
        <Activity params={params} searchParams={searchParams} />
      </Suspense>
    </main>
  );
}

