            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import type { Route } from "next";
import { useRouter } from "next/navigation";
import { useEffect, useRef } from "react";

// SA-07 (plan's design decision 5): a not-signed-in visitor sees the
// account page's content replaced by the SA-03 sign-up gate, and this leaf
// auto-opens it by replacing the URL once the page mounts, so
// `/${slug}/signup`'s intercepting route (@modal/(.)signup, SA-03) opens
// over the account page instead of leaving a dead end. `router.replace`,
// never `push`: closing the modal must not come back to a history entry
// that reopens it. Renders nothing — SignupPrompt's own EmptyState and
// link are the visible, no-JS fallback.
export function OpenSignupModal({ href }: { href: Route }) {
  const router = useRouter();
  const opened = useRef(false);

  useEffect(() => {
    if (opened.current) return;
    opened.current = true;
    router.replace(href);
  }, [router, href]);

  return null;
}

import { getFormatter, getTranslations } from "next-intl/server";
import type { AccountPurchase } from "@/lib/dal/account";
import { EmptyState } from "@/components/shared/empty-state";

// SA-07 (docs/03-maquettes.md › SA-07): the purchases list, newest first as
// returned by listPurchases. Price formatting mirrors PackCard
// (components/product/pack-card.tsx). A Server Component (review fix,
// MEDIUM): no interactivity, so getTranslations/getFormatter from
// next-intl/server, mirroring history-list.tsx, instead of a 'use client'
// leaf with no client behavior.
export async function PurchaseList({ purchases }: { purchases: AccountPurchase[] }) {
  const t = await getTranslations("account");
  const format = await getFormatter();

  if (purchases.length === 0) {
    return <EmptyState title={t("purchases.empty")} />;
  }

  return (
    <div className="grid gap-2">
      <h2 className="font-medium">{t("purchases.title")}</h2>
      <ul className="grid gap-3">
        {purchases.map((purchase) => (
          <li key={purchase.id} className="flex items-center justify-between rounded-md border p-3 text-sm">
            <span>
              {t("purchases.pack", { count: purchase.credits })} ·{" "}
              {format.dateTime(purchase.createdAt, { dateStyle: "medium", timeZone: "UTC" })}
            </span>
            <span className="font-semibold">
              {format.number(purchase.amountCents / 100, { style: "currency", currency: purchase.currency })}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import type { Route } from "next";
import Link from "next/link";
import { getTranslations } from "next-intl/server";
import { EmptyState } from "@/components/shared/empty-state";
import { Button } from "@/components/ui/button";
import { OpenSignupModal } from "./open-signup-modal";

// SA-07 (spec: "Non connecté → modale d'inscription"): shown instead of the
// balance/movements/purchases when there is no session, no DAL call made.
// The link is the visible, no-JS-required fallback to the full /signup page
// (SA-03); OpenSignupModal is the client leaf that auto-opens the
// intercepted modal on top of this page. The Link href is a template
// literal inline in JSX, which typedRoutes accepts without a cast; passing
// the same slug to OpenSignupModal's `href: Route` prop still needs one,
// since typedRoutes cannot prove a plain string fits the route type outside
// a JSX href (docs/04-nextjs.md: "typedRoutes… type les href").
export async function SignupPrompt({ slug }: { slug: string }) {
  const t = await getTranslations("account");
  const href = `/${slug}/signup`;

  return (
    <>
      <EmptyState
        title={t("signup.title")}
        action={
          <Button asChild>
            <Link href={`/${slug}/signup`}>{t("signup.cta")}</Link>
          </Button>
        }
      />
      <OpenSignupModal href={href as Route} />
    </>
  );
}

