scripts/monitor.ts.content:
// Machine monitor for orchestration runs, adapted from castflow's saturation
// Monitor. A daemon samples CPU and memory every 5 s, checks disk and Postgres,
// and tunes three limits shared by every worktree: the `test` and `typecheck`
// slots and the worktree pool (WORKTREE_MAX).
//
// Tuning, one step at a time within [floor, cap], at most every 30 s:
// - up when CPU and memory are underused over the last 30 s and the limit is the
//   bottleneck (jobs waiting in its queue, or every worktree in use);
// - down on pressure: CPU over the last 30 s, or memory right now (the OOM
//   killer does not wait for an average). The worktree pool only goes down on
//   memory pressure: agents mostly wait on the model, and the CPU spikes come
//   from queued jobs, which the slots already cap.
//
// The daemon writes events only (adjustments, alerts entering and clearing,
// start and stop) to monitor.log: the orchestrator follows that file with its
// Monitor tool and is notified of each line.
//
// State lives in the queue directory (QUEUE_LOCK_DIR, default /tmp/msb-queue):
// `test.slots`, `typecheck.slots`, `worktrees.max` override the QUEUE_SLOTS_* and
// WORKTREE_MAX defaults; `monitor.pid`, `monitor.alive` and `monitor.log` belong
// to the daemon.
//
// MONITOR_SAMPLE_MS changes the sampling period (default 5000).
//
// Usage: pnpm tsx scripts/monitor.ts <start | stop | status | live [--interval <s>] | run | reset>
//   start   launch the daemon in the background (no-op when it already runs)
//   run     the daemon loop in the foreground (what `start` launches)
//   live    real-time view: machine, queues, jobs with their memory, last events

import { execFileSync, spawn } from "node:child_process";
import {
  appendFileSync,
  existsSync,
  mkdirSync,
  openSync,
  readdirSync,
  readFileSync,
  readlinkSync,
  rmSync,
  statfsSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { availableParallelism, cpus, totalmem } from "node:os";
import { basename, join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";

const DIR = process.env.QUEUE_LOCK_DIR ?? "/tmp/msb-queue";
const LOG = join(DIR, "monitor.log");
const PID = join(DIR, "monitor.pid");
const ALIVE = join(DIR, "monitor.alive");
const GB = 1024 ** 3;

const SAMPLE_MS = Number(process.env.MONITOR_SAMPLE_MS ?? 5_000);
const WINDOW = 6; // samples averaged for decisions: 30 s by default
const COOLDOWN_MS = WINDOW * SAMPLE_MS; // after a change, observe a full window before the next one
const PG_EVERY = WINDOW; // check Postgres once per window

// Underused: room for one more job. Pressure: back off before the OOM killer does.
const IDLE = { cpu: 0.6, memFree: 0.4 };
const PRESSURE = { cpu: 0.9, memFree: 0.15 };
const ALERT = { diskFree: 0.1, pgConnections: 0.8 };
const ADMIN_URL = process.env.POSTGRES_ADMIN_URL ?? "postgres://postgres:postgres@localhost:5432/postgres";

const memTotal = Math.min(totalmem(), process.constrainedMemory() || Infinity);
const cores = availableParallelism();

type Limit = { file: string; env: string; fallback: number; floor: number; cap: number };
// A typecheck or a Vitest suite peaks around 1.5-2 GB; an agent session with its worktree around 1 GB.
const LIMITS = {
  test: {
    file: "test.slots",
    env: "QUEUE_SLOTS_TEST",
    fallback: 4,
    floor: 2,
    cap: Math.min(cores * 2, Math.floor(memTotal / (2 * GB))),
  },
  typecheck: {
    file: "typecheck.slots",
    env: "QUEUE_SLOTS_TYPECHECK",
    fallback: 4,
    floor: 2,
    cap: Math.min(cores * 2, Math.floor(memTotal / (2 * GB))),
  },
  worktrees: {
    file: "worktrees.max",
    env: "WORKTREE_MAX",
    fallback: 10,
    floor: 2,
    cap: Math.min(20, Math.floor(memTotal / GB)),
  },
} satisfies Record<string, Limit>;
type Name = keyof typeof LIMITS;

const readLimit = (l: Limit): number => {
  const path = join(DIR, l.file);
  const raw = existsSync(path) ? readFileSync(path, "utf8").trim() : (process.env[l.env] ?? "");
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : l.fallback;
};
const limits = (): Record<Name, number> => ({
  test: readLimit(LIMITS.test),
  typecheck: readLimit(LIMITS.typecheck),
  worktrees: readLimit(LIMITS.worktrees),
});

const alive = (pid: number): boolean => {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
};

const daemonPid = (): number | null => {
  const pid = existsSync(PID) ? Number(readFileSync(PID, "utf8").trim()) : NaN;
  return Number.isInteger(pid) && alive(pid) ? pid : null;
};

// ---------------------------------------------------------------- measures

type Job = { queue: string; state: "run" | "wait"; pid: number; since: number };

/** Live jobs, from the `<queue>.run.<pid>` / `<queue>.wait.<pid>` markers queued.sh keeps. */
const jobs = (): Job[] => {
  if (!existsSync(DIR)) return [];
  const list: Job[] = [];
  for (const f of readdirSync(DIR)) {
    const m = f.match(/^([a-z0-9]+)\.(run|wait)\.(\d+)$/);
    if (!m) continue;
    const pid = Number(m[3]);
    const path = join(DIR, f);
    if (!alive(pid)) {
      rmSync(path, { force: true }); // killed before its trap ran
      continue;
    }
    try {
      list.push({ queue: m[1]!, state: m[2] as Job["state"], pid, since: statSync(path).mtimeMs });
    } catch {
      // finished between readdir and stat
    }
  }
  return list;
};

const count = (all: Job[], queue: string) => ({
  running: all.filter((j) => j.queue === queue && j.state === "run").length,
  waiting: all.filter((j) => j.queue === queue && j.state === "wait").length,
});

const activeWorktrees = (): number => {
  try {
    const out = execFileSync("git", ["worktree", "list", "--porcelain"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    return out.split("\n").filter((l) => l.startsWith("worktree ")).length - 1; // minus the main checkout
  } catch {
    return 0;
  }
};

const cpuTimes = () =>
  cpus().reduce(
    (acc, c) => {
      const t = c.times;
      acc.idle += t.idle;
      acc.total += t.user + t.nice + t.sys + t.idle + t.irq;
      return acc;
    },
    { idle: 0, total: 0 },
  );

type Usage = { cpu: number; memFree: number };

/** CPU busy share over `ms`, and the share of memory still available. */
const sample = async (ms: number): Promise<Usage> => {
  const a = cpuTimes();
  await sleep(ms);
  const b = cpuTimes();
  const total = b.total - a.total;
  // availableMemory() honours the cgroup limit of a container; freemem() only sees the host.
  return {
    cpu: total > 0 ? 1 - (b.idle - a.idle) / total : 0,
    memFree: Math.min(process.availableMemory(), memTotal) / memTotal,
  };
};

/** Free share of the disk holding the worktrees (they are siblings of this checkout). */
const diskFree = (): number => {
  try {
    const s = statfsSync(process.cwd());
    return s.bavail / s.blocks;
  } catch {
    return 1;
  }
};

/** Postgres connections in use, or "down"; null when psql is not installed. */
const postgres = (): { used: number; max: number } | "down" | null => {
  try {
    const out = execFileSync(
      "psql",
      [ADMIN_URL, "-tAc", "select count(*), current_setting('max_connections') from pg_stat_activity"],
      { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], timeout: 3000 },
    );
    const [used, max] = out.trim().split("|").map(Number);
    return { used: used ?? 0, max: max ?? 100 };
  } catch (err) {
    return (err as NodeJS.ErrnoException).code === "ENOENT" ? null : "down";
  }
};

// ---------------------------------------------------------------- daemon

const pct = (x: number): string => `${Math.round(x * 100)}%`;

/** One event line in monitor.log (the orchestrator's Monitor tool turns each into a notification). */
const emit = (event: string, detail: string): void => {
  mkdirSync(DIR, { recursive: true });
  const line = `${new Date().toISOString()} ${event} ${detail}`;
  appendFileSync(LOG, `${line}\n`);
  if (process.stdout.isTTY) console.log(line);
};

const run = async (): Promise<void> => {
  mkdirSync(DIR, { recursive: true });
  const other = daemonPid();
  if (other && other !== process.pid) {
    console.error(`The monitor already runs (pid ${other}).`);
    process.exit(1);
  }
  writeFileSync(PID, `${process.pid}\n`);
  const stop = (reason: string) => {
    emit("MONITOR-STOPPED", reason);
    rmSync(PID, { force: true });
    process.exit(0);
  };
  process.on("SIGTERM", () => stop("SIGTERM"));
  process.on("SIGINT", () => stop("SIGINT"));
  emit(
    "MONITOR-STARTED",
    `pid ${process.pid}, sample ${SAMPLE_MS / 1000}s, decisions on ${(WINDOW * SAMPLE_MS) / 1000}s`,
  );

  const history: Usage[] = [];
  const active = new Map<string, string>(); // alert -> detail, to emit on enter and on clear
  let lastChange = 0;
  let pg: ReturnType<typeof postgres> = null;

  for (let n = 0; ; n++) {
    const now = await sample(SAMPLE_MS);
    writeFileSync(ALIVE, `${new Date().toISOString()}\n`);
    history.push(now);
    if (history.length > WINDOW) history.shift();
    const avg: Usage = {
      cpu: history.reduce((s, u) => s + u.cpu, 0) / history.length,
      memFree: history.reduce((s, u) => s + u.memFree, 0) / history.length,
    };
    if (n % PG_EVERY === 0) pg = postgres();

    // Alerts: one line when a condition starts, one when it clears.
    const alerts = new Map<string, string>();
    if (history.length === WINDOW && avg.cpu > PRESSURE.cpu)
      alerts.set("SATURATION-CPU", `cpu ${pct(avg.cpu)} over the window on ${cores} cores`);
    if (now.memFree < PRESSURE.memFree) alerts.set("SATURATION-MEM", `memory available ${pct(now.memFree)}`);
    const disk = diskFree();
    if (disk < ALERT.diskFree) alerts.set("SATURATION-DISK", `disk available ${pct(disk)}`);
    if (pg === "down") alerts.set("CRASH-POSTGRES", "no answer on the admin URL");
    else if (pg && pg.used / pg.max > ALERT.pgConnections)
      alerts.set("SATURATION-PG-CONNS", `${pg.used}/${pg.max} connections`);
    for (const [key, detail] of alerts) if (!active.has(key)) emit(key, detail);
    for (const key of active.keys()) if (!alerts.has(key)) emit(key, "cleared");
    active.clear();
    for (const [key, detail] of alerts) active.set(key, detail);

    // Tuning: after a full window, and not twice within the cooldown.
    if (history.length < WINDOW || Date.now() - lastChange < COOLDOWN_MS) continue;
    const current = limits();
    const all = jobs();
    const memPressure = now.memFree < PRESSURE.memFree;
    const cpuPressure = avg.cpu > PRESSURE.cpu;
    const idle = avg.cpu < IDLE.cpu && avg.memFree > IDLE.memFree && now.memFree > IDLE.memFree;
    const bottleneck: Record<Name, boolean> = {
      test: count(all, "test").waiting > 0,
      typecheck: count(all, "typecheck").waiting > 0,
      worktrees: activeWorktrees() >= current.worktrees,
    };
    const changes: string[] = [];
    for (const name of Object.keys(LIMITS) as Name[]) {
      const l = LIMITS[name];
      const from = current[name];
      const pressure = memPressure || (cpuPressure && name !== "worktrees");
      const to = pressure ? Math.max(l.floor, from - 1) : idle && bottleneck[name] ? Math.min(l.cap, from + 1) : from;
      if (to === from) continue;
      writeFileSync(join(DIR, l.file), `${to}\n`);
      changes.push(`${name} ${from} -> ${to}`);
    }
    if (changes.length) {
      lastChange = Date.now();
      emit(
        "ADJUST",
        `${changes.join(", ")} (cpu ${pct(avg.cpu)} over the window, memory available ${pct(now.memFree)})`,
      );
    }
  }
};

const start = (): void => {
  const pid = daemonPid();
  if (pid) {
    console.log(`The monitor already runs (pid ${pid}).`);
    return;
  }
  mkdirSync(DIR, { recursive: true });
  const err = openSync(join(DIR, "monitor.err"), "a"); // crash traces; events go to monitor.log
  // Same runtime and loader flags (tsx) as this process, detached so it outlives the caller.
  const child = spawn(process.execPath, [...process.execArgv, process.argv[1]!, "run"], {
    detached: true,
    stdio: ["ignore", "ignore", err],
  });
  child.unref();
  console.log(`Monitor started (pid ${child.pid}); events in ${LOG}`);
};

const stopDaemon = (): void => {
  const pid = daemonPid();
  if (!pid) {
    console.log("The monitor is not running.");
    return;
  }
  process.kill(pid, "SIGTERM");
  console.log(`Monitor stopped (pid ${pid}).`);
};

// ---------------------------------------------------------------- views

const daemonLine = (): string => {
  const pid = daemonPid();
  if (!pid) return "daemon     NOT RUNNING: pnpm tsx scripts/monitor.ts start";
  const last = existsSync(ALIVE) ? Date.parse(readFileSync(ALIVE, "utf8").trim()) : NaN;
  const age = Number.isNaN(last) ? "no sample yet" : `last sample ${Math.round((Date.now() - last) / 1000)}s ago`;
  return `daemon     running (pid ${pid}), ${age}`;
};

type Snapshot = Usage & { limits: Record<Name, number>; jobs: Job[]; worktrees: number };

const snapshot = async (sampleMs: number): Promise<Snapshot> => ({
  ...(await sample(sampleMs)),
  limits: limits(),
  jobs: jobs(),
  worktrees: activeWorktrees(),
});

const queueLines = (s: Snapshot): string[] =>
  (["test", "typecheck"] as const).map((q) => {
    const c = count(s.jobs, q);
    return `${q.padEnd(10)} ${c.running}/${s.limits[q]} slots · ${c.waiting} waiting (cap ${LIMITS[q].cap})`;
  });

/** Resident memory of every process tree rooted at the given pids, from one `ps` call. */
const treeMemory = (roots: number[]): Map<number, number> => {
  const result = new Map<number, number>();
  if (roots.length === 0) return result;
  let rows: number[][] = [];
  try {
    rows = execFileSync("ps", ["-A", "-o", "pid=,ppid=,rss="], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    })
      .trim()
      .split("\n")
      .map((l) => l.trim().split(/\s+/).map(Number));
  } catch {
    return result;
  }
  const children = new Map<number, number[]>();
  const rss = new Map<number, number>();
  for (const [pid = 0, ppid = 0, kb = 0] of rows) {
    rss.set(pid, kb * 1024);
    children.set(ppid, [...(children.get(ppid) ?? []), pid]);
  }
  for (const root of roots) {
    let total = 0;
    const stack = [root];
    while (stack.length) {
      const pid = stack.pop()!;
      total += rss.get(pid) ?? 0;
      stack.push(...(children.get(pid) ?? []));
    }
    result.set(root, total);
  }
  return result;
};

/** The command a job runs (queued.sh's arguments after the queue name), and the worktree it runs in. */
const describe = (pid: number): { cmd: string; where: string } => {
  try {
    const argv = readFileSync(`/proc/${pid}/cmdline`, "utf8").split("\0").filter(Boolean);
    const i = argv.findIndex((a) => a.endsWith("queued.sh"));
    return { cmd: argv.slice(i + 2).join(" "), where: basename(readlinkSync(`/proc/${pid}/cwd`)) };
  } catch {
    return { cmd: "?", where: "?" }; // no /proc (macOS) or the job just ended
  }
};

const bar = (x: number, width = 30): string => {
  const full = Math.round(Math.min(1, Math.max(0, x)) * width);
  return `[${"#".repeat(full)}${".".repeat(width - full)}] ${pct(x).padStart(4)}`;
};
const duration = (ms: number): string => {
  const s = Math.floor(ms / 1000);
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m${String(s % 60).padStart(2, "0")}s`;
};

const lastEvents = (n: number): string[] =>
  existsSync(LOG) ? readFileSync(LOG, "utf8").trim().split("\n").slice(-n) : [];

/** Full-screen view for `live`. */
const render = (s: Snapshot): string => {
  const used = memTotal * (1 - s.memFree);
  const lines = [
    `msb monitor · ${new Date().toLocaleTimeString()} · Ctrl-C to quit`,
    "",
    `cpu     ${bar(s.cpu)}  ${cores} cores`,
    `memory  ${bar(1 - s.memFree)}  ${(used / GB).toFixed(1)} / ${(memTotal / GB).toFixed(1)} GB`,
    `disk    ${bar(1 - diskFree())}`,
    "",
    ...queueLines(s),
    `worktrees  ${s.worktrees}/${s.limits.worktrees} active (cap ${LIMITS.worktrees.cap})`,
    daemonLine(),
    "",
  ];
  const memory = treeMemory(s.jobs.filter((j) => j.state === "run").map((j) => j.pid));
  const sorted = [...s.jobs].sort((a, b) => a.state.localeCompare(b.state) || a.since - b.since);
  lines.push(
    sorted.length ? "QUEUE      STATE  TIME     MEM      WORKTREE                        COMMAND" : "no queued jobs",
  );
  for (const j of sorted) {
    const { cmd, where } = describe(j.pid);
    const mem = j.state === "run" ? `${((memory.get(j.pid) ?? 0) / GB).toFixed(2)} GB` : "-";
    lines.push(
      [
        j.queue.padEnd(10),
        j.state.padEnd(6),
        duration(Date.now() - j.since).padEnd(8),
        mem.padEnd(8),
        where.padEnd(31),
        cmd,
      ].join(" "),
    );
  }
  const events = lastEvents(5);
  if (events.length) lines.push("", "last events:", ...events.map((l) => `  ${l}`));
  return lines.join("\n");
};

const printStatus = (s: Snapshot): void => {
  console.log(
    `cpu ${pct(s.cpu)} of ${cores} cores · memory available ${pct(s.memFree)} of ${(memTotal / GB).toFixed(1)} GB · disk available ${pct(diskFree())}`,
  );
  for (const line of queueLines(s)) console.log(line);
  console.log(`worktrees  ${s.worktrees}/${s.limits.worktrees} active (cap ${LIMITS.worktrees.cap})`);
  console.log(daemonLine());
};

// ---------------------------------------------------------------- CLI

const main = async (): Promise<void> => {
  const [command, ...args] = process.argv.slice(2);
  switch (command) {
    case "start":
      return start();
    case "stop":
      return stopDaemon();
    case "run":
      return run();
    case "status":
      return printStatus(await snapshot(2000));
    case "live": {
      const i = args.indexOf("--interval");
      const seconds = i >= 0 ? Number(args[i + 1]) : 2;
      // The CPU sample spans the whole interval, so each frame shows the load since the previous one.
      for (;;) process.stdout.write(`\x1b[2J\x1b[H${render(await snapshot(seconds * 1000))}\n`);
    }
    case "reset":
      for (const l of Object.values(LIMITS)) rmSync(join(DIR, l.file), { force: true });
      console.log("Limits reset to QUEUE_SLOTS_* / WORKTREE_MAX defaults.");
      return;
    default:
      console.error("Usage: pnpm tsx scripts/monitor.ts <start | stop | status | live [--interval <s>] | run | reset>");
      process.exit(2);
  }
};

main().catch((err: unknown) => {
  const message = err instanceof Error ? (err.stack ?? err.message) : String(err);
  if (process.argv[2] === "run") emit("MONITOR-CRASH", message.split("\n")[0] ?? "");
  console.error(message);
  process.exit(1);
});

scripts/qa-baseline.ts.content:
// The QA baseline: the git blob hash of every application file at the end of
// the last QA run whose findings were all handled (skill qa-orchestrator).
// The next `qa` pass diffs the current tree against it: an added or changed
// file is tested in depth, an unchanged one gets a light regression check.
// Hashes, not a commit SHA: they survive the squash merge of the integration
// branch into main, which leaves the run's own commits unreachable.
//
// Usage: pnpm tsx scripts/qa-baseline.ts diff
//        pnpm tsx scripts/qa-baseline.ts write --note "<run, date, scenario>"
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const BASELINE_PATH = ".claude/qa/route-baseline.json";
// What a QA pass can see: routes, their actions and components, the DAL, AI
// and credit code behind them, their messages, the mock fixtures, the proxy.
const TRACKED = ["app", "lib", "messages", "fixtures", "proxy.ts"];
const TEST_FILE = /\.(test|spec)\.[cm]?[jt]sx?$/;

type Entry = { path: string; hash: string };
type Baseline = { commitSha: string; branch: string; generatedAt: string; note: string; entries: Entry[] };

/** Parse `git ls-tree -r --format='%(objectname) %(path)'`, without test files. */
export const parseLsTree = (output: string): Entry[] =>
  output
    .split("\n")
    .filter((line) => line.trim() !== "")
    .map((line) => {
      const space = line.indexOf(" ");
      return { hash: line.slice(0, space), path: line.slice(space + 1) };
    })
    .filter((entry) => !TEST_FILE.test(entry.path))
    .sort((a, b) => a.path.localeCompare(b.path));

/** Without a baseline (first pass), every current file is new. */
export const diffBaseline = (baseline: Entry[] | null, current: Entry[]) => {
  const before = new Map((baseline ?? []).map((entry) => [entry.path, entry.hash]));
  const now = new Set(current.map((entry) => entry.path));
  return {
    added: current.filter((entry) => !before.has(entry.path)).map((entry) => entry.path),
    changed: current
      .filter((entry) => before.has(entry.path) && before.get(entry.path) !== entry.hash)
      .map((entry) => entry.path),
    removed: [...before.keys()].filter((path) => !now.has(path)),
    unchanged: current.filter((entry) => before.get(entry.path) === entry.hash).map((entry) => entry.path),
  };
};

const git = (args: string[]): string => execFileSync("git", args, { encoding: "utf8" }).trim();

const currentEntries = (): Entry[] =>
  parseLsTree(git(["ls-tree", "-r", "HEAD", "--format=%(objectname) %(path)", "--", ...TRACKED]));

const readBaseline = (): Baseline | null =>
  existsSync(BASELINE_PATH) ? (JSON.parse(readFileSync(BASELINE_PATH, "utf8")) as Baseline) : null;

const cmdDiff = (): void => {
  const baseline = readBaseline();
  const diff = diffBaseline(baseline?.entries ?? null, currentEntries());
  console.log(
    baseline
      ? `Baseline: ${baseline.commitSha} (${baseline.branch}, ${baseline.generatedAt}) — ${baseline.note}`
      : "No baseline: first pass, every file is new",
  );
  for (const path of diff.added) console.log(`A ${path}`);
  for (const path of diff.changed) console.log(`M ${path}`);
  for (const path of diff.removed) console.log(`D ${path}`);
  console.log(
    `${diff.added.length} added, ${diff.changed.length} changed, ${diff.removed.length} removed, ${diff.unchanged.length} unchanged`,
  );
};

const cmdWrite = (note: string | undefined): void => {
  if (!note) throw new Error('write needs --note "<run, date, scenario>"');
  const baseline: Baseline = {
    commitSha: git(["rev-parse", "HEAD"]),
    branch: git(["rev-parse", "--abbrev-ref", "HEAD"]),
    generatedAt: new Date().toISOString().slice(0, 10),
    note,
    entries: currentEntries(),
  };
  writeFileSync(BASELINE_PATH, `${JSON.stringify(baseline, null, 2)}\n`);
  console.log(`Wrote ${BASELINE_PATH}: ${baseline.entries.length} files at ${baseline.commitSha}`);
};

const isEntry = (): boolean => {
  try {
    return !!process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
};
if (isEntry()) {
  const [command, ...args] = process.argv.slice(2);
  const noteAt = args.indexOf("--note");
  try {
    if (command === "diff") cmdDiff();
    else if (command === "write") cmdWrite(noteAt === -1 ? undefined : args[noteAt + 1]);
    else throw new Error('Usage: pnpm tsx scripts/qa-baseline.ts diff | write --note "<run, date, scenario>"');
  } catch (err) {
    console.error(err instanceof Error ? err.message : err);
    process.exit(1);
  }
}

scripts/worktree-db.ts.content:
// One Postgres database per git worktree, all on the shared local cluster
// (native cluster, or `docker compose up -d postgres`). The database name derives from the current
// branch: main/master -> `msb`, anything else -> `msb_<sanitized branch>`.
//
// Usage: pnpm tsx scripts/worktree-db.ts <ensure [--seed] | drop | url | list | prune [--yes]>
// Admin connection: POSTGRES_ADMIN_URL (default postgres://postgres:postgres@localhost:5432/postgres).

import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import postgres from "postgres";

const ADMIN_URL = process.env.POSTGRES_ADMIN_URL ?? "postgres://postgres:postgres@localhost:5432/postgres";
const MAIN_DB = "msb";
const PROTECTED_BRANCHES = new Set(["main", "master"]);

const git = (args: string[], cwd?: string): string => execFileSync("git", args, { cwd, encoding: "utf8" }).trim();

export const dbNameForBranch = (branch: string): string => {
  if (PROTECTED_BRANCHES.has(branch)) return MAIN_DB;
  // Postgres identifiers are capped at 63 bytes; "msb_" takes 4.
  const sanitized = branch
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 59);
  return `${MAIN_DB}_${sanitized}`;
};

export const dbUrlFor = (dbName: string): string => {
  const url = new URL(ADMIN_URL);
  url.pathname = `/${dbName}`;
  return url.toString();
};

/** Set or replace KEY=value in an env file, keeping every other line. Creates the file if missing. */
export const setEnvVar = (filePath: string, key: string, value: string): void => {
  const content = existsSync(filePath) ? readFileSync(filePath, "utf8") : "";
  const line = `${key}=${value}`;
  const pattern = new RegExp(`^${key}=.*$`, "m");
  const next = pattern.test(content)
    ? content.replace(pattern, () => line)
    : `${content.trimEnd()}${content.trim() ? "\n" : ""}${line}\n`;
  writeFileSync(filePath, next, "utf8");
};

export const readEnvVar = (filePath: string, key: string): string | undefined => {
  if (!existsSync(filePath)) return undefined;
  const match = readFileSync(filePath, "utf8").match(new RegExp(`^${key}=(.*)$`, "m"));
  return match?.[1]?.trim();
};

const currentBranch = (): string => {
  const branch = git(["branch", "--show-current"]);
  if (!branch) throw new Error("Detached HEAD: check out a branch first.");
  return branch;
};

const quoteIdent = (name: string): string => `"${name.replace(/"/g, '""')}"`;

const withAdmin = async <T>(fn: (sql: postgres.Sql) => Promise<T>): Promise<T> => {
  const sql = postgres(ADMIN_URL, { max: 1, connect_timeout: 5, onnotice: () => {} });
  try {
    await sql`SELECT 1`;
  } catch (err) {
    await sql.end({ timeout: 1 }).catch(() => {});
    const reason = err instanceof Error ? err.message : String(err);
    console.error(
      `\nERROR: cannot reach Postgres at ${new URL(ADMIN_URL).host} (${reason}).\n` +
        "Start it with `pg_ctlcluster <version> main start` (native) or `docker compose up -d postgres`.\n",
    );
    process.exit(1);
  }
  try {
    return await fn(sql);
  } finally {
    await sql.end({ timeout: 5 });
  }
};

const listDatabases = (sql: postgres.Sql): Promise<string[]> =>
  sql<{ datname: string }[]>`
    SELECT datname FROM pg_database
    WHERE datname = ${MAIN_DB} OR datname LIKE ${`${MAIN_DB}\\_%`}
    ORDER BY datname
  `.then((rows) => rows.map((r) => r.datname));

/** branch -> worktree path, from `git worktree list --porcelain`. */
const worktreesByBranch = (): Map<string, string> => {
  const map = new Map<string, string>();
  let path = "";
  for (const line of git(["worktree", "list", "--porcelain"]).split("\n")) {
    if (line.startsWith("worktree ")) path = line.slice("worktree ".length);
    else if (line.startsWith("branch refs/heads/")) map.set(line.slice("branch refs/heads/".length), path);
  }
  return map;
};

const ensure = async (seed: boolean): Promise<void> => {
  const root = git(["rev-parse", "--show-toplevel"]);
  const dbName = dbNameForBranch(currentBranch());
  const dbUrl = dbUrlFor(dbName);

  await withAdmin(async (sql) => {
    const [exists] = await sql`SELECT 1 FROM pg_database WHERE datname = ${dbName}`;
    if (exists) {
      console.log(`Database ${dbName} already exists`);
    } else {
      await sql.unsafe(`CREATE DATABASE ${quoteIdent(dbName)}`);
      console.log(`Created database ${dbName}`);
    }
    // All worktree databases share one cluster and one max_connections budget.
    // A leaked connection or abandoned transaction in one worktree must fail
    // fast instead of starving the others. ALTER DATABASE applies to every
    // future connection and is idempotent.
    const q = quoteIdent(dbName);
    await sql.unsafe(`ALTER DATABASE ${q} SET idle_in_transaction_session_timeout = '30s'`);
    await sql.unsafe(`ALTER DATABASE ${q} SET lock_timeout = '15s'`);
    await sql.unsafe(`ALTER DATABASE ${q} SET idle_session_timeout = '5min'`);
  });

  const envLocal = resolve(root, ".env.local");
  const envExample = resolve(root, ".env.example");
  if (!existsSync(envLocal) && existsSync(envExample)) {
    copyFileSync(envExample, envLocal);
    console.log("Created .env.local from .env.example");
  }
  setEnvVar(envLocal, "DATABASE_URL", dbUrl);
  console.log(`Set DATABASE_URL in .env.local -> ${dbName}`);

  const env = { ...process.env, DATABASE_URL: dbUrl };
  execFileSync("pnpm", ["db:migrate"], { cwd: root, stdio: "inherit", env });
  if (seed) execFileSync("pnpm", ["db:seed"], { cwd: root, stdio: "inherit", env });
  console.log(`Database ${dbName} is ready`);
};

const drop = async (): Promise<void> => {
  const dbName = dbNameForBranch(currentBranch());
  if (dbName === MAIN_DB) {
    console.error(`Refusing to drop the main database "${MAIN_DB}".`);
    process.exit(1);
  }
  await withAdmin(async (sql) => {
    // WITH (FORCE) terminates the worktree's own lingering connections (dev server, tests).
    await sql.unsafe(`DROP DATABASE IF EXISTS ${quoteIdent(dbName)} WITH (FORCE)`);
  });
  console.log(`Dropped database ${dbName}`);
};

const list = async (): Promise<void> => {
  const byDb = new Map<string, string>();
  for (const [branch, path] of worktreesByBranch()) byDb.set(dbNameForBranch(branch), `${path} (${branch})`);
  const dbs = await withAdmin(listDatabases);
  if (dbs.length === 0) {
    console.log("No msb databases.");
    return;
  }
  const width = Math.max(...dbs.map((d) => d.length));
  for (const db of dbs) console.log(`${db.padEnd(width)}  ${byDb.get(db) ?? "-"}`);
};

const prune = async (apply: boolean): Promise<void> => {
  const branches = git(["for-each-ref", "--format=%(refname:short)", "refs/heads"]).split("\n").filter(Boolean);
  const live = new Set(branches.map(dbNameForBranch));
  live.add(MAIN_DB);
  await withAdmin(async (sql) => {
    const orphans = (await listDatabases(sql)).filter((db) => !live.has(db));
    if (orphans.length === 0) {
      console.log("Nothing to prune.");
      return;
    }
    for (const db of orphans) {
      if (apply) {
        await sql.unsafe(`DROP DATABASE IF EXISTS ${quoteIdent(db)} WITH (FORCE)`);
        console.log(`Dropped ${db}`);
      } else {
        console.log(`Would drop ${db}`);
      }
    }
    if (!apply) console.log("Dry run. Re-run with --yes to drop.");
  });
};

const main = async (): Promise<void> => {
  const [command, ...flags] = process.argv.slice(2);
  switch (command) {
    case "ensure":
      return ensure(flags.includes("--seed"));
    case "drop":
      return drop();
    case "url":
      console.log(dbUrlFor(dbNameForBranch(currentBranch())));
      return;
    case "list":
      return list();
    case "prune":
      return prune(flags.includes("--yes"));
    default:
      console.error("Usage: pnpm tsx scripts/worktree-db.ts <ensure [--seed] | drop | url | list | prune [--yes]>");
      process.exit(2);
  }
};

// Only run when executed directly, so scripts/worktree.ts can import the helpers.
const isEntry = (): boolean => {
  try {
    return !!process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
};
if (isEntry()) {
  main().catch((err: unknown) => {
    console.error(err instanceof Error ? err.message : err);
    process.exit(1);
  });
}

scripts/worktree.ts.content:
// Create, remove and list sibling git worktrees, one per feature agent. Each
// worktree gets its own branch (feat/<slug>) and its own Postgres database, so
// up to worktreeMax() agents can run side by side. No dev server runs in a
// worktree: agents loop on typecheck and Vitest, and Playwright starts its own
// server on E2E_PORT, serialised by the `e2e` queue that `pnpm test:e2e` takes itself.
//
// Usage: pnpm tsx scripts/worktree.ts <integration [<branch>] | new <slug> [--from <ref>] | rm <slug> [--keep-branch] | list>

import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, readFileSync } from "node:fs";
import { basename, dirname, resolve, sep } from "node:path";
import { dbNameForBranch, dbUrlFor, readEnvVar, setEnvVar } from "./worktree-db";

/** Pool size: the value scripts/monitor.ts tuned to the machine's load, else WORKTREE_MAX. */
const worktreeMax = (): number => {
  const file = resolve(process.env.QUEUE_LOCK_DIR ?? "/tmp/msb-queue", "worktrees.max");
  const n = Number(existsSync(file) ? readFileSync(file, "utf8").trim() : (process.env.WORKTREE_MAX ?? 10));
  return Number.isInteger(n) && n > 0 ? n : 10;
};
// The integration branch of the current orchestration run: created by
// `worktree.ts integration <branch>` and recorded in the repository's git config,
// which every worktree shares. Feature branches start from it and target it.
const INTEGRATION_KEY = "msb.integration";

type Worktree = { path: string; branch: string | null };

const run = (cmd: string, args: string[], cwd?: string): void => {
  execFileSync(cmd, args, { cwd, stdio: "inherit" });
};
const git = (args: string[], cwd?: string): string =>
  execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();

const fail = (message: string): never => {
  console.error(`ERROR: ${message}`);
  process.exit(1);
};

/** The main checkout, found from any worktree via the shared git dir. */
const mainRoot = (): string => dirname(git(["rev-parse", "--path-format=absolute", "--git-common-dir"]));

const worktrees = (): Worktree[] => {
  const list: Worktree[] = [];
  for (const line of git(["worktree", "list", "--porcelain"]).split("\n")) {
    if (line.startsWith("worktree ")) list.push({ path: line.slice("worktree ".length), branch: null });
    else if (line.startsWith("branch refs/heads/") && list.length > 0)
      list[list.length - 1]!.branch = line.slice("branch refs/heads/".length);
  }
  return list;
};

const extraWorktrees = (root: string): Worktree[] => worktrees().filter((w) => resolve(w.path) !== resolve(root));

const pathFor = (root: string, slug: string): string => resolve(root, "..", `${basename(root)}-${slug}`);

const validateSlug = (slug: string | undefined): string => {
  if (!slug || !/^[a-z0-9][a-z0-9-]*$/.test(slug)) fail("slug must match [a-z0-9][a-z0-9-]* (e.g. credits-ledger)");
  return slug as string;
};

const branchExists = (branch: string): boolean => {
  try {
    git(["rev-parse", "--verify", "--quiet", `refs/heads/${branch}`]);
    return true;
  } catch {
    return false;
  }
};

const integrationBranch = (): string | null => {
  try {
    return git(["config", "--get", INTEGRATION_KEY]) || null;
  } catch {
    return null;
  }
};

/** Without a name, print the current integration branch. With one, create it
 * from origin/main (unless it already exists on origin), push it and record it. */
const cmdIntegration = (branch: string | undefined): void => {
  if (!branch) {
    console.log(
      integrationBranch() ?? fail("no integration branch; create one with: worktree.ts integration <branch>"),
    );
    return;
  }
  const root = mainRoot();
  try {
    git(["check-ref-format", "--branch", branch]);
  } catch {
    fail(`invalid branch name: ${branch}`);
  }
  if (["main", "master"].includes(branch) || branch.startsWith("feat/"))
    fail(`${branch} cannot be an integration branch`);
  run("git", ["fetch", "origin"], root);
  let onOrigin = true;
  try {
    git(["rev-parse", "--verify", "--quiet", `refs/remotes/origin/${branch}`], root);
  } catch {
    onOrigin = false;
  }
  if (!onOrigin) run("git", ["push", "origin", `origin/main:refs/heads/${branch}`], root);
  git(["config", INTEGRATION_KEY, branch], root);
  console.log(`Integration branch: ${branch}${onOrigin ? " (already on origin)" : " (created from origin/main)"}`);
};

const cmdNew = (slug: string, from: string): void => {
  const root = mainRoot();
  const path = pathFor(root, slug);
  const branch = `feat/${slug}`;
  git(["worktree", "prune"]);
  const existing = worktrees().find((w) => resolve(w.path) === path);

  if (existing) {
    if (existing.branch !== branch)
      fail(`${path} exists on branch ${existing.branch ?? "(detached)"}, expected ${branch}`);
    console.log(`Worktree ${path} already exists, re-running setup`);
  } else {
    if (existsSync(path)) fail(`${path} exists but is not a git worktree; move it away first`);
    const active = extraWorktrees(root).length;
    const max = worktreeMax();
    if (active >= max) fail(`${active} worktrees already active (max ${max}); remove one first`);
    run("git", ["fetch", "origin"], root);
    if (branchExists(branch)) run("git", ["worktree", "add", path, branch], root);
    else run("git", ["worktree", "add", path, "-b", branch, from], root);
  }

  // `worktree add -b <branch> origin/<integration>` sets the new branch's
  // upstream to the integration branch. A bare `git push` from an agent would
  // then push feature commits straight to it. Pushing with -u rebinds the upstream to
  // origin/feat/<slug> before anything else can push.
  run("git", ["push", "-u", "origin", branch], path);

  const envLocal = resolve(path, ".env.local");
  if (!existsSync(envLocal)) {
    const source = [resolve(root, ".env.local"), resolve(path, ".env.example")].find(existsSync);
    if (source) copyFileSync(source, envLocal);
  }
  const dbName = dbNameForBranch(branch);
  // Point at the worktree's own database right away so a copied main
  // DATABASE_URL is never left in place if a later step fails.
  setEnvVar(envLocal, "DATABASE_URL", dbUrlFor(dbName));

  if (existsSync(resolve(path, "package.json"))) {
    run("pnpm", ["install", "--frozen-lockfile", "--prefer-offline"], path);
    run("pnpm", ["tsx", "scripts/worktree-db.ts", "ensure", "--seed"], path);
  } else {
    console.warn("No package.json in the worktree yet: skipped pnpm install and database setup.");
  }

  console.log(
    ["", `Worktree ready`, `  path    ${path}`, `  branch  ${branch}`, `  db      ${dbName}`, `Next: cd ${path}`].join(
      "\n",
    ),
  );
};

const cmdRm = (slug: string, keepBranch: boolean): void => {
  const root = mainRoot();
  const path = pathFor(root, slug);
  const branch = `feat/${slug}`;
  const cwd = resolve(process.cwd());
  if (cwd === path || cwd.startsWith(path + sep)) fail(`run this from outside ${path}`);

  const existing = worktrees().find((w) => resolve(w.path) === path);
  if (existing) {
    // Check before dropping the database: a dirty worktree is kept, so its data must be too.
    if (existsSync(path) && git(["status", "--porcelain"], path))
      fail(`${path} has uncommitted changes; commit, push or discard them first`);
    try {
      run("pnpm", ["tsx", "scripts/worktree-db.ts", "drop"], path);
    } catch {
      console.warn(
        `Could not drop the database of ${branch}; clean up later with: pnpm tsx scripts/worktree-db.ts prune`,
      );
    }
    try {
      // No --force: a dirty worktree must be committed or discarded by a human.
      run("git", ["worktree", "remove", path], root);
    } catch {
      fail(`git worktree remove failed (uncommitted changes?). Inspect ${path}`);
    }
  } else {
    console.log(`No worktree at ${path}`);
  }

  if (!keepBranch && branchExists(branch)) {
    try {
      // -d only: refuses unmerged work. A pushed branch counts as merged into its upstream.
      run("git", ["branch", "-d", branch], root);
    } catch {
      fail(`branch ${branch} has unpushed or unmerged commits; kept. Delete it yourself once checked.`);
    }
  }
};

const cmdList = (): void => {
  const root = mainRoot();
  const prefix = `${basename(root)}-`;
  const rows = extraWorktrees(root).map((w) => {
    const env = resolve(w.path, ".env.local");
    const dbUrl = readEnvVar(env, "DATABASE_URL");
    let dirty = "?";
    try {
      dirty = git(["status", "--porcelain"], w.path) ? "yes" : "no";
    } catch {
      // missing directory: leave "?"
    }
    const name = basename(w.path);
    return [
      name.startsWith(prefix) ? name.slice(prefix.length) : name,
      w.branch ?? "(detached)",
      dbUrl ? new URL(dbUrl).pathname.slice(1) : "-",
      dirty,
    ];
  });
  if (rows.length === 0) {
    console.log("No extra worktrees.");
    return;
  }
  const table = [["SLUG", "BRANCH", "DB", "DIRTY"], ...rows];
  const widths = table[0]!.map((_, i) => Math.max(...table.map((r) => r[i]!.length)));
  for (const r of table) console.log(r.map((c, i) => c.padEnd(widths[i]!)).join("  "));
};

const main = async (): Promise<void> => {
  const [command, ...args] = process.argv.slice(2);
  const flag = (name: string): string | undefined => {
    const i = args.indexOf(name);
    return i >= 0 ? args[i + 1] : undefined;
  };
  switch (command) {
    case "integration":
      return cmdIntegration(args[0]);
    case "new": {
      const from = flag("--from") ?? integrationBranch();
      if (!from) return fail("no integration branch; create one first: worktree.ts integration <branch>");
      return cmdNew(validateSlug(args[0]), flag("--from") ? from : `origin/${from}`);
    }
    case "rm":
      return cmdRm(validateSlug(args[0]), args.includes("--keep-branch"));
    case "list":
      return cmdList();
    default:
      console.error(
        "Usage: pnpm tsx scripts/worktree.ts <integration [<branch>] | new <slug> [--from <ref>] | rm <slug> [--keep-branch] | list>",
      );
      process.exit(2);
  }
};

main().catch((err: unknown) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

